class SignalBlocker:
    """
    信号阻塞上下文管理器，用于临时禁用 Qt 对象的信号发射
    
    原理：
    - blockSignals(True) 会临时禁用对象的所有信号发射
    - 使用 try-finally 确保信号状态一定会被恢复
    - 保存原始状态，避免覆盖已有的阻塞状态
    
    使用示例：
        # 方式1：使用上下文管理器（推荐）
        with SignalBlocker(self.param_table):
            self.param_table.setItem(0, 1, QTableWidgetItem("新值"))
            # 这里修改表格不会触发 itemChanged 信号
        
        # 方式2：手动控制（更灵活）
        blocker = SignalBlocker(self.graphics_scene)
        blocker.block()
        try:
            # 执行批量操作
            self.graphics_scene.clear()
        finally:
            blocker.unblock()
    """
    
    def __init__(self, obj):
        """
        初始化信号阻塞器
        
        Args:
            obj: 需要阻塞信号的 Qt 对象（如 QTableWidget, QGraphicsScene 等）
        """
        self.obj = obj
        self._was_blocked = None
    
    def __enter__(self):
        """进入上下文时自动阻塞信号"""
        self.block()
        return self
    
    def __exit__(self, exc_type, exc_val, exc_tb):
        """退出上下文时自动恢复信号"""
        self.unblock()
    
    def block(self):
        """阻塞信号，保存原始状态"""
        if self.obj is not None:
            self._was_blocked = self.obj.blockSignals(True)
    
    def unblock(self):
        """恢复信号到原始状态"""
        if self.obj is not None and self._was_blocked is not None:
            self.obj.blockSignals(self._was_blocked)


class _ParamNameDisplayDelegate(QStyledItemDelegate):
    """参数名显示代理：仅改显示文案，不改底层存储键。"""

    def __init__(self, owner=None, parent=None):
        super().__init__(parent)
        self._owner = owner

    def displayText(self, value, locale):
        text = "" if value is None else str(value)
        try:
            hx = str(getattr(self._owner, "heat_exchanger", "") or "").strip().upper()
            if hx in ("AKU", "BKU") and text.strip() == "壳体内直径 Dis":
                return "壳体小端内直径"
        except Exception:
            pass
        return super().displayText(value, locale)


class _ParamValueCellDelegate(QStyledItemDelegate):
    """参数值列：圆角白底边框（对照示例输入框）。"""

    def __init__(self, owner=None, parent=None):
        super().__init__(parent)
        self._owner = owner

    def paint(self, painter, option, index):
        if index.column() != 2:
            super().paint(painter, option, index)
            return

        table = option.widget
        if table is not None and table.cellWidget(index.row(), index.column()) is not None:
            return

        from PyQt5.QtGui import QPainter
        from PyQt5.QtWidgets import QStyle

        painter.save()
        painter.setRenderHint(QPainter.Antialiasing)

        if option.state & QStyle.State_Selected:
            painter.fillRect(option.rect, option.palette.highlight())

        box_rect = option.rect.adjusted(5, 4, -5, -4)
        editable = bool(index.flags() & Qt.ItemIsEditable)

        paint_param_value_box(painter, box_rect, editable)

        text = "" if index.data(Qt.DisplayRole) is None else str(index.data(Qt.DisplayRole))
        painter.setPen(
            _buguan_param_value_text_color(self._owner, index.row(), editable, index)
        )
        text_rect = box_rect.adjusted(10, 0, -8, 0)
        painter.drawText(text_rect, Qt.AlignLeft | Qt.AlignVCenter, text)
        painter.restore()

    def createEditor(self, parent, option, index):
        editor = QLineEdit(parent)
        editor.setFrame(False)
        editor.setStyleSheet(
            "QLineEdit {"
            "  border: 1px solid #CCCCCC;"
            "  border-radius: 4px;"
            "  padding: 2px 10px;"
            "  background-color: #ffffff;"
            "  color: #303133;"
            "  font-size: 10pt;"
            "}"
            "QLineEdit:focus {"
            "  border: 1px solid #c0c4cc;"
            "}"
        )
        return editor

    def setEditorData(self, editor, index):
        editor.setText("" if index.data(Qt.DisplayRole) is None else str(index.data(Qt.DisplayRole)))

    def setModelData(self, editor, model, index):
        text = editor.text()
        model.setData(index, text, Qt.EditRole)
        table = self._owner.param_table if self._owner else None
        if table is not None:
            it = table.item(index.row(), index.column())
            if it is None:
                it = QTableWidgetItem(text)
                table.setItem(index.row(), index.column(), it)
            else:
                it.setText(text)
        _buguan_delegate_sync_modified_display(self._owner, index.row())

    def updateEditorGeometry(self, editor, option, index):
        editor.setGeometry(option.rect.adjusted(5, 4, -5, -4))


