class ZoomableGraphicsView(QGraphicsView):
    def __init__(self, scene):
        super().__init__(scene)
        self.zoom_factor = 1.1  # 缩放因子

    def wheelEvent(self, event):
        if event.modifiers() == Qt.ControlModifier:
            if event.angleDelta().y() > 0:
                # 向上滚动，放大
                self.scale(self.zoom_factor, self.zoom_factor)
            else:
                # 向下滚动，缩小
                self.scale(1 / self.zoom_factor, 1 / self.zoom_factor)
        else:
            super().wheelEvent(event)

    def mouseDoubleClickEvent(self, event):
        try:
            scene_pos = self.mapToScene(event.pos())
            item = self.itemAt(event.pos())
            item_info = type(item).__name__ if item is not None else "None"
            print(
                f"[DBG][ZoomableGraphicsView] ENTER doubleClick pos=({event.pos().x()},{event.pos().y()}) scene=({scene_pos.x():.3f},{scene_pos.y():.3f}) itemAt={item_info}"
            )
        except Exception:
            pass

        # 获取 editor 引用（在多个地方使用）
        editor = getattr(self, "editor", None)
        if editor is None and self.scene() is not None:
            for it in self.scene().items():
                try:
                    ed = getattr(it, "editor", None)
                    if ed is not None:
                        editor = ed
                        break
                except Exception:
                    continue
        try:
            print(f"[DBG][ZoomableGraphicsView] editor={type(editor).__name__ if editor else None}")
        except Exception:
            pass

        # 视图层优先处理：若双击位置下存在防冲板图元（is_baffle=True），
        # 则直接进入防冲板编辑，不再依赖精确命中路径上的单个 item。
        try:
            if editor is not None and hasattr(editor, "edit_baffle"):
                # 从视图坐标反查场景中所有命中图元，优先选择 is_baffle 的图元
                hit_items = self.items(event.pos()) or []
                chosen_baffle = None
                for it in hit_items:
                    try:
                        if getattr(it, "is_baffle", False):
                            chosen_baffle = it
                            break
                    except Exception:
                        continue

                if chosen_baffle is not None:
                    try:
                        print(
                            f"[ZoomableGraphicsView] double-click hit baffle -> type={getattr(chosen_baffle, 'baffle_type', None)}, id={getattr(chosen_baffle, 'impingement_plate_id', None)}"
                        )
                    except Exception:
                        pass

                    try:
                        editor.edit_baffle(chosen_baffle)
                    except Exception:
                        pass

                    event.accept()
                    return
        except Exception:
            pass

        # 优先检测吊环螺钉：如果双击的是吊环螺钉，打开编辑对话框
        try:
            if editor is not None:
                # 获取所有命中的图元（因为吊环螺钉由多个图形项组成）
                hit_items = self.items(event.pos()) or []
                print(f"[DBG][ZoomableGraphicsView] screw-check hit_items count={len(hit_items)}")
                chosen_screw_ring = None
                screw_ring_id = None
                for it in hit_items:
                    try:
                        is_screw = getattr(it, "is_screw_ring", False)
                        print(
                            f"[DBG][ZoomableGraphicsView] screw-check item={type(it).__name__} is_screw_ring={is_screw} screw_ring_id={getattr(it,'screw_ring_id',None)}"
                        )
                        if is_screw:
                            chosen_screw_ring = it
                            screw_ring_id = getattr(it, "screw_ring_id", None)
                            print(f"[DBG][ZoomableGraphicsView] screw-check FOUND id={screw_ring_id}")
                            if screw_ring_id is not None:
                                break
                    except Exception as e:
                        print(f"[DBG][ZoomableGraphicsView] screw-check error checking item: {e}")
                        continue
                
                if chosen_screw_ring is not None and screw_ring_id is not None:
                    try:
                        print(f"[DBG][ZoomableGraphicsView] CALL edit_screw_ring_params_dialog id={screw_ring_id}")
                        if hasattr(editor, "edit_screw_ring_params_dialog"):
                            editor.edit_screw_ring_params_dialog(screw_ring_id)
                            event.accept()
                            return
                        else:
                            print(f"[DBG][ZoomableGraphicsView] editor has NO edit_screw_ring_params_dialog()")
                    except Exception as e:
                        print(f"[DBG][ZoomableGraphicsView] error opening screw ring dialog: {e}")
                        import traceback
                        traceback.print_exc()
        except Exception as e:
            print(f"[DBG][ZoomableGraphicsView] error in screw ring detection: {e}")
            import traceback
            traceback.print_exc()

        # 视图层补充处理：若双击到的是一个圆（包括普通拉杆/换热管，使用 addEllipse 绘制），
        # 则判断该圆心是否在 editor.lagan_info 中；若在则仅弹出参数对话框。
        try:
            try:
                print(
                    f"[ZoomableGraphicsView] resolve editor -> {'found' if editor is not None else 'none'}"
                )
            except Exception:
                pass

            # 优先使用当前选中的圆心（与换热管选中逻辑一致）进行判断
            if (
                    editor is not None
                    and hasattr(editor, "selected_centers")
                    and editor.selected_centers
            ):
                try:
                    abs_selected = []
                    try:
                        abs_selected = editor.selected_to_current_coords(
                            editor.selected_centers
                        )
                    except Exception:
                        abs_selected = []
                    # 统一到6位小数
                    abs_selected6 = []
                    for p in abs_selected or []:
                        try:
                            abs_selected6.append(
                                (round(float(p[0]), 6), round(float(p[1]), 6))
                            )
                        except Exception:
                            continue
                    print(
                        f"[ZoomableGraphicsView] selected_centers -> count={len(editor.selected_centers)}, abs_count={len(abs_selected6)}, sample={abs_selected6[:5]}"
                    )

                    # 构造 lagan_info 集合
                    def key6_pair2(p):
                        try:
                            return (round(float(p[0]), 6), round(float(p[1]), 6))
                        except Exception:
                            return None

                    lagan_list_raw2 = (
                        list(editor.lagan_info)
                        if hasattr(editor, "lagan_info")
                           and isinstance(editor.lagan_info, (list, tuple))
                        else []
                    )
                    lagan_set2 = set(
                        k
                        for k in (key6_pair2(p) for p in lagan_list_raw2)
                        if k is not None
                    )
                    print(
                        f"[ZoomableGraphicsView] (selected-check) lagan_info size={len(lagan_set2)}"
                    )

                    matched = False
                    for sc in abs_selected6:
                        if sc in lagan_set2:
                            matched = True
                            break
                    print(f"[ZoomableGraphicsView] (selected-check) matched={matched}")
                    if matched and hasattr(editor, "edit_lagan_params_dialog_only"):
                        print(
                            "[ZoomableGraphicsView] (selected-check) open edit_lagan_params_dialog_only()"
                        )
                        editor.edit_lagan_params_dialog_only()
                        event.accept()
                        return
                except Exception:
                    pass

            # 次优先：复用 eventFilter 的“最近圆心”定位逻辑，用双击点的场景坐标映射到圆心
            try:
                if (
                        editor is not None
                        and hasattr(editor, "find_nearest_circle_index")
                        and hasattr(editor, "r")
                ):
                    mx, my = float(scene_pos.x()), float(scene_pos.y())
                    # 选择上下两组中心列表
                    centers = None
                    if hasattr(editor, "full_sorted_current_centers_up") and hasattr(
                            editor, "full_sorted_current_centers_down"
                    ):
                        if my >= 0:
                            centers = editor.full_sorted_current_centers_up
                        else:
                            centers = editor.full_sorted_current_centers_down
                    if centers:
                        res = editor.find_nearest_circle_index(
                            centers, [], mx, my, editor.r
                        )
                        if res:
                            row, col = res
                            try:
                                x, y = centers[row][col]
                                cx2, cy2 = round(float(x), 6), round(float(y), 6)
                                print(
                                    f"[ZoomableGraphicsView] nearest-center -> ({cx2}, {cy2}) from scene_pos=({mx:.3f},{my:.3f})"
                                )

                                # 与 lagan_info 匹配
                                def key6_pair3(p):
                                    try:
                                        return (
                                            round(float(p[0]), 6),
                                            round(float(p[1]), 6),
                                        )
                                    except Exception:
                                        return None

                                lagan_list_raw3 = (
                                    list(editor.lagan_info)
                                    if hasattr(editor, "lagan_info")
                                       and isinstance(editor.lagan_info, (list, tuple))
                                    else []
                                )
                                lagan_set3 = set(
                                    k
                                    for k in (key6_pair3(p) for p in lagan_list_raw3)
                                    if k is not None
                                )
                                hit = (cx2, cy2) in lagan_set3
                                print(
                                    f"[ZoomableGraphicsView] (nearest-check) in_lagan_info={hit}, lagan_size={len(lagan_set3)}"
                                )
                                if hit and hasattr(
                                        editor, "edit_lagan_params_dialog_only"
                                ):
                                    print(
                                        "[ZoomableGraphicsView] (nearest-check) open edit_lagan_params_dialog_only()"
                                    )
                                    editor.edit_lagan_params_dialog_only()
                                    event.accept()
                                    return
                            except Exception:
                                pass
            except Exception:
                pass

            # 仅当点击到圆形并且拿到 editor 时才处理
            if (
                    item is not None
                    and isinstance(item, QGraphicsEllipseItem)
                    and editor is not None
            ):
                # 计算该圆在场景中的中心坐标
                try:
                    c = item.sceneBoundingRect().center()
                    cx, cy = round(float(c.x()), 6), round(float(c.y()), 6)
                except Exception:
                    # 回退：用视图映射的场景坐标（可能与圆心有偏差）
                    cx, cy = round(float(scene_pos.x()), 6), round(
                        float(scene_pos.y()), 6
                    )
                try:
                    print(f"[ZoomableGraphicsView] ellipse center -> ({cx}, {cy})")
                except Exception:
                    pass

                # 构造 lagan_info 的坐标集合（按 6 位小数统一）
                if (
                        hasattr(editor, "lagan_info")
                        and editor.lagan_info is not None
                        and hasattr(editor, "edit_lagan_params_dialog_only")
                ):

                    def key6_pair(p):
                        try:
                            return (round(float(p[0]), 6), round(float(p[1]), 6))
                        except Exception:
                            return None

                    lagan_list_raw = (
                        list(editor.lagan_info)
                        if isinstance(editor.lagan_info, (list, tuple))
                        else []
                    )
                    lagan_set = set(
                        k
                        for k in (key6_pair(p) for p in lagan_list_raw)
                        if k is not None
                    )
                    try:
                        sample = list(lagan_set)[:5]
                        print(
                            f"[ZoomableGraphicsView] lagan_info size={len(lagan_set)}, sample={sample}"
                        )
                    except Exception:
                        pass
                    if (cx, cy) in lagan_set:
                        try:
                            print(
                                "[ZoomableGraphicsView] center matched lagan_info -> open edit_lagan_params_dialog_only()"
                            )
                            editor.edit_lagan_params_dialog_only()
                            event.accept()
                            return
                        except Exception:
                            pass
                    else:
                        # 未命中时打印最近距离，辅助调试容差
                        try:
                            import math

                            if lagan_set:
                                dmin = min(
                                    math.hypot(cx - x, cy - y) for (x, y) in lagan_set
                                )
                                print(
                                    f"[ZoomableGraphicsView] center NOT in lagan_info, nearest_dist={dmin:.6f}"
                                )
                            else:
                                print(
                                    "[ZoomableGraphicsView] center NOT in lagan_info, lagan_set is empty"
                                )
                        except Exception:
                            pass
                else:
                    try:
                        has_list = (
                                hasattr(editor, "lagan_info")
                                and editor.lagan_info is not None
                        )
                        has_func = hasattr(editor, "edit_lagan_params_dialog_only")
                        print(
                            f"[ZoomableGraphicsView] skip check: lagan_info_exists={has_list}, has_dialog={has_func}"
                        )
                    except Exception:
                        pass
        except Exception:
            pass

        super().mouseDoubleClickEvent(event)


class ClickableRectItem(QGraphicsPathItem):
    def __init__(
            self,
            path=None,
            parent=None,
            is_side_block=False,
            is_baffle=False,
            is_slide=False,
            is_center_dangguan=False,
            is_center_dangban=False,
            editor=None,
    ):
        # 关键修改：将QRectF自动转换为QPainterPath
        if isinstance(path, QRectF):
            temp_path = QPainterPath()
            temp_path.addRect(path)  # 将矩形添加到路径
            path = temp_path

        # 初始化父类，使用提供的路径或空路径
        super().__init__(path if path else QPainterPath(), parent)

        self.setAcceptHoverEvents(True)
        self.setFlag(QGraphicsPathItem.ItemIsSelectable, True)

        # 各种类型标记
        self.is_side_block = is_side_block  # 旁路挡板
        self.is_baffle = is_baffle  # 防冲板
        self.is_slide = is_slide  # 滑道
        self.is_center_dangguan = is_center_dangguan  # 中间挡管
        self.is_center_dangban = is_center_dangban  # 中间挡板

        self.is_selected = False  # 选中状态
        self.editor = editor  # 主窗口引用
        self.original_pen = self.pen()  # 保存原始画笔

        # 高亮选中样式
        self.selected_pen = QPen(
            QColor(255, 215, 0), 3, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin  # 金色
        )

        self.paired_block = None  # 配对挡板引用
        self.baffle_type = None  # 防冲板类型
        self.interfering_tubes = []  # 干涉的换热管坐标
        self.original_selected_center = None  # 存储原始选中坐标

    def set_paired_block(self, block):
        """设置配对挡板（双向绑定）"""
        self.paired_block = block
        if block and block.paired_block != self:
            block.paired_block = self

    def mouseDoubleClickEvent(self, event):
        """双击事件：对防冲板图元，直接调用编辑对话框"""
        try:
            if self.is_baffle and self.editor and hasattr(self.editor, "edit_baffle"):
                print(
                    f"[DEBUG] Double-click baffle: type={getattr(self, 'baffle_type', None)}, id={getattr(self, 'impingement_plate_id', None)}"
                )
                # 调用主窗口的防冲板编辑函数
                self.editor.edit_baffle(self)
                event.accept()
                return
        except Exception:
            pass

        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton and (
                self.is_side_block
                or self.is_baffle
                or self.is_slide
                or self.is_center_dangguan
                or self.is_center_dangban
        ):
            # 切换选中状态
            self.is_selected = not self.is_selected
            # 更新边框样式
            self.setPen(self.selected_pen if self.is_selected else self.original_pen)

            # 更新主窗口选中列表
            if self.editor:
                if self.is_side_block and hasattr(self.editor, "selected_side_blocks"):
                    if self.is_selected:
                        if self not in self.editor.selected_side_blocks:
                            self.editor.selected_side_blocks.append(self)
                    else:
                        if self in self.editor.selected_side_blocks:
                            self.editor.selected_side_blocks.remove(self)
                elif self.is_baffle and hasattr(self.editor, "selected_baffles"):
                    # 调试：确认防冲板（含焊接式）是否收到单击事件
                    try:
                        print(
                            f"[DEBUG] Click baffle: type={getattr(self, 'baffle_type', None)}, id={getattr(self, 'impingement_plate_id', None)}, selected={self.is_selected}"
                        )
                    except Exception:
                        pass

                    if self.is_selected:
                        if self not in self.editor.selected_baffles:
                            self.editor.selected_baffles.append(self)
                    else:
                        if self in self.editor.selected_baffles:
                            self.editor.selected_baffles.remove(self)
                elif self.is_slide and hasattr(self.editor, "selected_slides"):
                    if self.is_selected:
                        if self not in self.editor.selected_slides:
                            self.editor.selected_slides.append(self)
                    else:
                        if self in self.editor.selected_slides:
                            self.editor.selected_slides.remove(self)
                elif self.is_center_dangguan and hasattr(
                        self.editor, "selected_center_dangguan"
                ):
                    if self.is_selected:
                        if self not in self.editor.selected_center_dangguan:
                            self.editor.selected_center_dangguan.append(self)
                            print(
                                f"已选中挡板，unique_id={getattr(self, 'unique_id', 'None')}, 当前选中数量={len(self.editor.selected_center_dangguan)}"
                            )
                            # 同步到全局变量
                            try:
                                from modules.buguan.buguan_ziyong.variable import (
                                    update_selected_center_dangguan,
                                )

                                update_selected_center_dangguan(
                                    list(self.editor.selected_center_dangguan)
                                )
                            except:
                                pass
                    else:
                        if self in self.editor.selected_center_dangguan:
                            self.editor.selected_center_dangguan.remove(self)
                            print("未选中")
                            # 同步到全局变量
                            try:
                                from modules.buguan.buguan_ziyong.variable import (
                                    update_selected_center_dangguan,
                                )

                                update_selected_center_dangguan(
                                    list(self.editor.selected_center_dangguan)
                                )
                            except:
                                pass
                elif self.is_center_dangban and hasattr(
                        self.editor, "selected_center_dangban"
                ):
                    if self.is_selected:
                        if self not in self.editor.selected_center_dangban:
                            self.editor.selected_center_dangban.append(self)
                            print(
                                f"已选中中间挡板，original_selected_center={getattr(self, 'original_selected_center', 'None')}, 当前选中数量={len(self.editor.selected_center_dangban)}"
                            )
                    else:
                        if self in self.editor.selected_center_dangban:
                            self.editor.selected_center_dangban.remove(self)
                            print(
                                f"取消选中中间挡板，当前选中数量={len(self.editor.selected_center_dangban)}"
                            )
            event.accept()
        else:
            super().mousePressEvent(event)
    #TODO 双击事件
    def mouseDoubleClickEvent(self, event):
        if self.is_baffle and self.editor:
            try:
                # 调用编辑器的防冲板编辑入口
                self.editor.edit_baffle(self)
                event.accept()
                return
            except Exception:
                pass
        # 旁路挡板双击编辑
        if (
                getattr(self, "is_side_block", False)
                and self.editor
                and hasattr(self.editor, "edit_side_block")
        ):
            try:
                self.editor.edit_side_block(self)
                event.accept()
                return
            except Exception:
                pass
        # 滑道双击编辑
        if (
                getattr(self, "is_slide", False)
                and self.editor
                and hasattr(self.editor, "edit_slide")
        ):
            try:
                self.editor.edit_slide(self)
                event.accept()
                return
            except Exception:
                pass
        # 中间挡板双击编辑
        if (
                getattr(self, "is_center_dangban", False)
                and self.editor
                and hasattr(self.editor, "edit_center_dangban")
        ):
            try:
                self.editor.edit_center_dangban(self)
                event.accept()
                return
            except Exception:
                pass
        super().mouseDoubleClickEvent(event)


class ClickableCircleItem(QGraphicsEllipseItem):
    def __init__(
            self, rect, parent=None, is_side_rod=False, is_lagan=False, editor=None
    ):
        super().__init__(rect, parent)
        self.setAcceptHoverEvents(True)
        # 明确接受左键以确保能接收双击事件
        try:
            self.setAcceptedMouseButtons(Qt.LeftButton)
        except Exception:
            pass
        self.is_side_rod = is_side_rod  # 标记是否为最左最右拉杆
        self.is_lagan = is_lagan  # 标记是否为普通拉杆
        self.is_selected = False  # 选中状态
        self.editor = editor  # 主窗口引用
        self.original_pen = self.pen()  # 保存原始画笔
        self.original_brush = self.brush()  # 保存原始画刷
        # 高亮选中样式
        self.selected_pen = QPen(
            QColor(255, 215, 0), 3, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin
        )
        self.selected_brush = QBrush(QColor(173, 216, 230))  # 淡蓝色填充
        self.paired_rod = None  # 配对拉杆引用
        self.original_selected_center = None  # 存储原始选中坐标
        self.position = None  # 存储拉杆的绝对坐标（用于普通拉杆）

    def set_paired_rod(self, rod):
        """设置配对拉杆（双向绑定）"""
        self.paired_rod = rod
        if rod and rod.paired_rod != self:
            rod.paired_rod = self

    def mousePressEvent(self, event):
        if event.button() == Qt.LeftButton:
            try:
                print(
                    f"[ClickableCircleItem] mousePressEvent: is_side_rod={self.is_side_rod}, is_lagan={self.is_lagan}"
                )
            except Exception:
                pass
            if self.is_side_rod:
                # 切换选中状态
                self.is_selected = not self.is_selected
                # 更新边框样式
                self.setPen(
                    self.selected_pen if self.is_selected else self.original_pen
                )

                # 更新主窗口选中列表
                if self.editor:
                    # 确保 selected_side_rods 列表存在
                    if not hasattr(self.editor, "selected_side_rods"):
                        self.editor.selected_side_rods = []
                    if self.is_selected:
                        if self not in self.editor.selected_side_rods:
                            self.editor.selected_side_rods.append(self)
                            print(
                                f"[ClickableCircleItem] 添加拉杆到选中列表，当前选中数量: {len(self.editor.selected_side_rods)}"
                            )
                    else:
                        if self in self.editor.selected_side_rods:
                            self.editor.selected_side_rods.remove(self)
                            print(
                                f"[ClickableCircleItem] 从选中列表移除拉杆，当前选中数量: {len(self.editor.selected_side_rods)}"
                            )
                # 尝试提示自由拉杆-换热管的间距（仅在满足条件时）
                try:
                    if self.editor and hasattr(
                            self.editor, "check_and_show_lagan_tube_distance"
                    ):
                        self.editor.check_and_show_lagan_tube_distance()
                except Exception:
                    pass
                event.accept()
            elif self.is_lagan and self.editor:
                # 普通拉杆：行为与普通换热管一致
                # 1）通过 selected_centers 参与选管逻辑（如果能转换为相对坐标）
                # 2）自身显示淡蓝色实心选中效果
                # 3）即使无法转换为相对坐标，也能通过 selected_lagans 列表被选中
                try:
                    # 获取场景中的圆心坐标
                    try:
                        c = self.sceneBoundingRect().center()
                        cx, cy = float(c.x()), float(c.y())
                    except Exception:
                        c = self.rect().center()
                        pos = self.scenePos() + c
                        cx, cy = float(pos.x()), float(pos.y())

                    editor = self.editor
                    if not hasattr(editor, "selected_centers"):
                        editor.selected_centers = []
                    if not hasattr(editor, "selected_lagans"):
                        editor.selected_lagans = []
                    
                    # 尝试转换为相对坐标
                    rel_list = []
                    if hasattr(editor, "actual_to_selected_coords"):
                        rel = editor.actual_to_selected_coords((cx, cy))
                        # 规范化为[(row,col), ...]
                        if rel:
                            if (
                                    isinstance(rel, (list, tuple))
                                    and len(rel) == 2
                                    and isinstance(rel[0], int)
                            ):
                                rel_list.append(tuple(rel))
                            elif isinstance(rel, list):
                                for r in rel:
                                    if (
                                            isinstance(r, (list, tuple))
                                            and len(r) == 2
                                            and isinstance(r[0], int)
                                    ):
                                        rel_list.append(tuple(r))

                    # 如果能转换为相对坐标，使用 selected_centers 逻辑
                    if rel_list:
                        # 若已全部在 selected_centers 中，则视为取消选择；否则加入
                        cur = list(editor.selected_centers)
                        if all(coord in cur for coord in rel_list):
                            # 取消选中：移除坐标 + 移除与换热管一致的 marker 叠层
                            cur = [c for c in cur if c not in rel_list]
                            if hasattr(editor, "_remove_abs_selection_marker"):
                                editor._remove_abs_selection_marker(cx, cy)
                            # 同步普通拉杆选中列表
                            if self in editor.selected_lagans:
                                editor.selected_lagans.remove(self)
                        else:
                            # 选中：加入坐标 + 叠淡蓝 marker（与 eventFilter 换热管选中一致）
                            for coord in rel_list:
                                if coord not in cur:
                                    cur.append(coord)
                            if hasattr(editor, "_add_abs_selection_marker"):
                                editor._add_abs_selection_marker(cx, cy)
                            # 同步普通拉杆选中列表
                            if self not in editor.selected_lagans:
                                editor.selected_lagans.append(self)
                        editor.selected_centers = cur
                    else:
                        # 无法转换为相对坐标（例如从吊环螺钉转换来的拉杆）
                        # 直接使用 selected_lagans 列表进行选中/取消选中
                        if self in editor.selected_lagans:
                            # 取消选中：移除 marker
                            if hasattr(editor, "_remove_abs_selection_marker"):
                                editor._remove_abs_selection_marker(cx, cy)
                            editor.selected_lagans.remove(self)
                            print(f"[ClickableCircleItem] 普通拉杆取消选中（无法转换为相对坐标），坐标: ({cx:.3f}, {cy:.3f})")
                        else:
                            # 选中：叠淡蓝 marker
                            if hasattr(editor, "_add_abs_selection_marker"):
                                editor._add_abs_selection_marker(cx, cy)
                            editor.selected_lagans.append(self)
                            print(f"[ClickableCircleItem] 普通拉杆选中（无法转换为相对坐标），坐标: ({cx:.3f}, {cy:.3f})")
                except Exception as e:
                    print(f"[ClickableCircleItem] 普通拉杆选中处理出错: {e}")
                    import traceback
                    traceback.print_exc()
                event.accept()
            else:
                # 其他圆（普通换热管等）：使用父类默认行为
                super().mousePressEvent(event)
                return

    def mouseDoubleClickEvent(self, event):
        try:
            print(
                f"[ClickableCircleItem] mouseDoubleClickEvent: is_side_rod={getattr(self, 'is_side_rod', False)}, is_lagan={getattr(self, 'is_lagan', False)}"
            )
        except Exception:
            pass
        # 自由拉杆（最左最右拉杆）双击编辑已禁用
        if self.is_side_rod:
            try:
                print("[ClickableCircleItem] side_rod double-click ignored (popup disabled)")
                event.accept()
                return
            except Exception:
                pass
        # 普通拉杆双击编辑
        if self.is_lagan and self.editor:
            try:
                # 检查是否有编辑对话框函数
                if hasattr(self.editor, "edit_lagan_params_dialog_only"):
                    print(
                        "[ClickableCircleItem] lagan double-click -> edit_lagan_params_dialog_only()"
                    )
                    self.editor.edit_lagan_params_dialog_only()
                    event.accept()
                    return
            except Exception as e:
                print(f"[ClickableCircleItem] 普通拉杆双击处理出错: {e}")
                import traceback
                traceback.print_exc()
        # 其他情况（普通换热管等）：直接走父类默认行为
        super().mouseDoubleClickEvent(event)


class ClickableRadialHoleItem(QGraphicsEllipseItem):
    """可点击的径向开孔图形项"""
    def __init__(self, rect, center_coord, editor=None, parent=None):
        super().__init__(rect, parent)
        self.setAcceptHoverEvents(True)
        try:
            self.setAcceptedMouseButtons(Qt.LeftButton)
        except Exception:
            pass
        self.is_selected = False
        self.editor = editor
        self.center_coord = center_coord  # 存储径向开孔的坐标
        self.original_pen = self.pen()
        self.original_brush = self.brush()
        # 高亮选中样式：金色边框
        self.selected_pen = QPen(
            QColor(255, 215, 0), 3, Qt.SolidLine, Qt.RoundCap, Qt.RoundJoin
        )
        # 设置透明填充，只显示边框
        self.setBrush(QBrush(Qt.NoBrush))
        # 设置初始边框为透明，这样不会显示圆形
        self.setPen(QPen(Qt.NoPen))
        # 设置 Z 值，确保在径向开孔图形之上
        try:
            self.setZValue(130)
        except Exception:
            pass

    def mousePressEvent(self, event):
        """单击选中/取消选中"""
        if event.button() == Qt.LeftButton:
            # 切换选中状态
            self.is_selected = not self.is_selected
            # 更新边框样式
            if self.is_selected:
                self.setPen(self.selected_pen)
            else:
                self.setPen(QPen(Qt.NoPen))
            
            # 更新主窗口选中列表
            if self.editor:
                if not hasattr(self.editor, "selected_radial_holes"):
                    self.editor.selected_radial_holes = []
                
                if self.is_selected:
                    if self not in self.editor.selected_radial_holes:
                        self.editor.selected_radial_holes.append(self)
                else:
                    if self in self.editor.selected_radial_holes:
                        self.editor.selected_radial_holes.remove(self)
            
            event.accept()
        else:
            super().mousePressEvent(event)

    def mouseDoubleClickEvent(self, event):
        """双击编辑径向开孔参数"""
        if self.editor and hasattr(self.editor, "edit_radial_hole"):
            try:
                self.editor.edit_radial_hole(self)
                event.accept()
                return
            except Exception:
                pass
        super().mouseDoubleClickEvent(event)


# 预览对话框 -----------------------------------------------------
from PyQt5.QtWidgets import (
    QDialog,
    QVBoxLayout,
    QTableWidget,
    QTableWidgetItem,
    QDialogButtonBox,
    QLabel,
    QAbstractItemView,
)
from PyQt5.QtCore import Qt
from PyQt5.QtGui import QPixmap


class PreviewDialog(QDialog):
    def __init__(self, parameters, parent=None):
        super().__init__(parent)
        self.setWindowTitle("参数预览")
        self.setModal(True)
        self.resize(1000, 800)

        layout = QVBoxLayout()
        self.setLayout(layout)

        # 参数表格
        self.table = QTableWidget()
        self.table.setColumnCount(4)
        self.table.setHorizontalHeaderLabels(["序号", "参数名", "参数值", "单位"])
        self.table.verticalHeader().setVisible(False)
        self.table.setEditTriggers(QTableWidget.NoEditTriggers)

        # 强制设置表格样式
        self.table.setStyleSheet(
            """
            QTableWidget {
                gridline-color: #d0d0d0;
            }
            QTableWidget::item {
                padding: 5px;
            }
            /* 为不同列设置不同的对齐方式 */
            QTableWidget::item:first {
                text-align: center;  /* 第一列居中 */
            }
            QTableWidget::item:fourth {
                text-align: center;  /* 第四列居中 */
            }
            QTableWidget::item {
                text-align: left;    /* 其他列左对齐 */
            }
        """
        )

        # 填充数据
        self.table.setRowCount(len(parameters))
        for row, param in enumerate(parameters):
            num = param.get("序号", str(row + 1))
            name = param.get("参数名", "N/A")
            value = param.get("参数值", "N/A")
            unit = param.get("单位", "N/A")

            # 创建单元格项并设置数据
            num_item = QTableWidgetItem(num)
            name_item = QTableWidgetItem(name)
            unit_item = QTableWidgetItem(unit)

            # 设置单元格
            self.table.setItem(row, 0, num_item)
            self.table.setItem(row, 1, name_item)
            self.table.setItem(row, 3, unit_item)

            # 特殊处理管程分程形式，显示图片而非文本
            if name == "管程分程形式" and "image" in param:
                # 创建标签来显示图片
                img_label = QLabel()
                img_label.setAlignment(Qt.AlignLeft | Qt.AlignVCenter)
                # 设置图片并保持比例
                pixmap = param["image"]
                if not pixmap.isNull():
                    img_label.setPixmap(pixmap)
                # 将标签设置为单元格部件
                self.table.setCellWidget(row, 2, img_label)
            else:
                # 普通参数，使用文本
                value_item = QTableWidgetItem(value)
                self.table.setItem(row, 2, value_item)

        # 调整列宽后，重新设置对齐方式（确保生效）
        self.table.setColumnWidth(0, 50)
        self.table.setColumnWidth(1, 300)
        self.table.setColumnWidth(2, 250)
        self.table.setColumnWidth(3, 80)

        # 在数据填充完成后，强制设置对齐方式
        for row in range(self.table.rowCount()):
            # 第一列居中
            item = self.table.item(row, 0)
            if item:
                item.setTextAlignment(Qt.AlignCenter)
            mm_item = self.table.item(row, 3)
            if mm_item:
                mm_item.setTextAlignment(Qt.AlignCenter)

            # 其他列左对齐（参数名和单位）
            for col in [1, 2]:
                item = self.table.item(row, col)
                if item:
                    item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)

            # 处理参数值列的对齐方式（如果是文本项）
            if self.table.item(row, 2):
                self.table.item(row, 2).setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)

        layout.addWidget(self.table)

        # 按钮
        button_box = QDialogButtonBox(QDialogButtonBox.Ok)
        button_box.accepted.connect(self.accept)
        layout.addWidget(button_box)


