    def _schedule_cross_pipe_button_refresh(self):
        for _ms in (0, 50, 200, 400):
            QTimer.singleShot(_ms, self.update_cross_pipe_button_state)

    def _fetch_product_type_from_db(self):
        """产品设计活动表「产品型式」，与 sheet_form_page 一致。"""
        pid = getattr(self, "productID", None)
        if not pid:
            return ""
        conn = None
        try:
            conn = create_product_connection()
            if not conn:
                return ""
            with conn.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT 产品型式
                    FROM 产品设计活动表
                    WHERE 产品ID = %s
                    LIMIT 1
                    """,
                    (pid,),
                )
                row = cursor.fetchone()
                if row and isinstance(row, dict):
                    hx = row.get("产品型式")
                    if hx is not None and str(hx).strip():
                        return str(hx).strip().upper()
        except Exception as e:
            print(f"[_fetch_product_type_from_db] {e}")
        finally:
            if conn and getattr(conn, "open", False):
                try:
                    conn.close()
                except Exception:
                    pass
        return ""

    def _sync_current_centers_lagan(self, reason: str = ""):
        """
        维护 current_centers_lagan 的一致性：
        - 存“绝对坐标”
        - 内容 = current_centers(当前换热管孔) + lagan_info(普通拉杆)
        - 自由拉杆不会出现在 lagan_info 中（自由拉杆写入 red_dangban_abs）
        """

        try:
            tube_centers = list(getattr(self, "current_centers", []) or [])
        except Exception:
            tube_centers = []

        try:
            lagan_centers = list(getattr(self, "lagan_info", []) or [])
        except Exception:
            lagan_centers = []

        def key6(x, y):
            return (round(float(x), 6), round(float(y), 6))

        tube_keys = set()
        for x, y in tube_centers:
            try:
                tube_keys.add(key6(x, y))
            except Exception:
                pass

        # 先保留 tube 的原始顺序；再补齐 lagan_info 中 tube_centers 没有的点
        combined = list(tube_centers)
        for x, y in lagan_centers:
            try:
                k = key6(x, y)
            except Exception:
                continue
            if k not in tube_keys:
                combined.append((x, y))
                tube_keys.add(k)

        self.current_centers_lagan = combined

        # 调试输出：观察删除/添加换热管、拉杆后该变量是否同步刷新
        try:
            tube_count = len(tube_centers)
            lagan_count = len(lagan_centers)
            combined_count = len(self.current_centers_lagan)
            sizes = (tube_count, lagan_count, combined_count)
            last_sizes = getattr(self, "_debug_sync_last_sizes", None)
            if last_sizes != sizes:
                print(
                    f"[SYNC current_centers_lagan] reason={reason} "
                    f"tube={tube_count} lagan={lagan_count} current_centers_lagan={combined_count}",
                    flush=True,
                )
                self._debug_sync_last_sizes = sizes
        except Exception:
            pass

        # 同步缓存分组结果（后续定位/绘制用）
        try:
            (
                self.sorted_current_centers_lagan_up,
                self.sorted_current_centers_lagan_down,
            ) = self.group_centers_by_y(self.current_centers_lagan)
        except Exception:
            pass

    def handle_symmetric_layout(self, state):
        if state == Qt.Checked:
            self.isSymmetry = True
        else:
            self.isSymmetry = False

    @property
    def current_centers(self):
        return self._current_centers

    @current_centers.setter
    def current_centers(self, value):
        self._current_centers = value
        self.update_total_holes_count()

        # 每次 current_centers 变化时，更新 R 值和最小非0 R值
        # 确保 hole_distribution_table 已经创建（避免初始化时出错）
        if (
                hasattr(self, "hole_distribution_table")
                and self.hole_distribution_table is not None
        ):
            try:
                # 更新水平表的最小非0 R值（self.min_distance_row）
                self.get_current_tube_hole_data()
            except Exception as e:
                # 如果计算失败，不影响主流程，只记录日志
                print(f"【警告】更新水平表最小R值时出错: {e}")

            try:
                # 更新竖直表的最小非0 R值（self.min_distance_col）
                self.update_min_distance_col()
            except Exception as e:
                # 如果计算失败，不影响主流程，只记录日志
                print(f"【警告】更新竖直表最小R值时出错: {e}")

        # current_centers 整体赋值时，同步维护 current_centers_lagan
        try:
            if hasattr(self, "_sync_current_centers_lagan"):
                self._sync_current_centers_lagan()
        except Exception:
            pass

    @property
    def selected_centers(self):
        return self._selected_centers

    @selected_centers.setter
    def selected_centers(self, value):
        if self._selected_centers != value:
            self._selected_centers = value
            # print("self.selected_centers发生变化")
            if getattr(self, "is_arrange_by_row", True):
                self.highlight_right_table_row()
            else:
                self.highlight_right_table_col()
            self.show_distance()
            # 当选中换热管孔集合发生变化时，提示当前选中数量
            try:
                count = (
                    len(self.selected_centers)
                    if hasattr(self, "selected_centers")
                    else 0
                )
                # 当选中数量为2时，仅显示两孔间距提示，不再显示数量提示
                if count == 1:
                    # 只选中一个换热管孔：在底部提示该孔绝对坐标
                    # 绝对坐标取 self.selected_to_current_coords 的结果（与 global_centers 同源的当前坐标系）
                    abs_x = None
                    abs_y = None
                    try:
                        coords = self.selected_to_current_coords(self.selected_centers)
                        if isinstance(coords, tuple) and len(coords) == 2:
                            abs_x, abs_y = coords
                        elif (
                            isinstance(coords, list)
                            and len(coords) == 1
                            and isinstance(coords[0], (tuple, list))
                            and len(coords[0]) == 2
                        ):
                            abs_x, abs_y = coords[0]
                    except Exception:
                        abs_x = None
                        abs_y = None

                    if abs_x is not None and abs_y is not None:
                        # 说明：当前用于计算/绘制的坐标系与肉眼象限显示的 y 方向相反
                        # 所以这里做 y 取反，保证用户看到的“第一/第二/三/四象限”与提示一致。
                        try:
                            abs_y_display = -float(abs_y)
                        except Exception:
                            abs_y_display = abs_y
                        message = (
                            f"您当前选中的换热管孔坐标为 ({float(abs_x):.4f}, {abs_y_display:.4f})"
                        )
                    else:
                        # 坐标取不到时退回数量提示，避免无提示
                        message = f"您当前选中的换热管孔的数量为{count}个"

                    if hasattr(self, "line_tip") and self.line_tip is not None:
                        self.line_tip.setText(message)
                        self.line_tip.setStyleSheet("color: black;")
                        self.line_tip.setVisible(True)

                        from PyQt5.QtCore import QTimer

                        expected_text = message

                        def _clear_if_same():
                            try:
                                if self.line_tip and self.line_tip.text() == expected_text:
                                    self.line_tip.setText("")
                            except Exception:
                                pass

                        QTimer.singleShot(5000, _clear_if_same)
                    else:
                        print(message)
                elif count != 2:
                    message = f"您当前选中的换热管孔的数量为{count}个"
                    if hasattr(self, "line_tip") and self.line_tip is not None:
                        self.line_tip.setText(message)
                        self.line_tip.setStyleSheet("color: black;")
                        self.line_tip.setVisible(True)

                        from PyQt5.QtCore import QTimer

                        expected_text = message

                        def _clear_if_same():
                            try:
                                if self.line_tip and self.line_tip.text() == expected_text:
                                    self.line_tip.setText("")
                            except Exception:
                                pass

                        QTimer.singleShot(5000, _clear_if_same)
                    else:
                        print(message)
            except Exception:
                try:
                    count = (
                        len(self.selected_centers)
                        if hasattr(self, "selected_centers")
                        else 0
                    )
                    if count != 2:
                        message = f"您当前选中的换热管孔的数量为{count}个"
                        print(message)
                except Exception:
                    pass
            # 当换热管选中发生变化时，尝试显示“自由拉杆-换热管”间距
            try:
                if hasattr(self, "check_and_show_lagan_tube_distance"):
                    self.check_and_show_lagan_tube_distance()
            except Exception:
                pass
            for callback in self.selected_centers_changed_callbacks:
                callback(value)

    def register_selected_centers_callback(self, callback):
        """注册 selected_centers 变化的回调函数"""
        if callback not in self.selected_centers_changed_callbacks:
            self.selected_centers_changed_callbacks.append(callback)

    def unregister_selected_centers_callback(self, callback):
        """取消注册回调函数"""
        if callback in self.selected_centers_changed_callbacks:
            self.selected_centers_changed_callbacks.remove(callback)

    def show_distance(self):
        if len(self.selected_centers) == 2:
            distance = self.calculate_distance(self.selected_centers)
            message = f"您选中的两个换热管孔的间距为 {distance: .4f} mm。"

            try:
                self.line_tip.setText(message)
                self.line_tip.setStyleSheet("color: black;")
                self.line_tip.setVisible(True)
                from PyQt5.QtCore import QTimer

                expected_text = message

                def _clear_if_same():
                    try:
                        if self.line_tip and self.line_tip.text() == expected_text:
                            self.line_tip.setText("")
                    except Exception:
                        pass

                QTimer.singleShot(5000, _clear_if_same)
            except Exception:
                pass

    def highlight_right_table_row(self):
        # 1) 早返回：无选中则清除既有高亮并退出
        actual_centers = self.selected_to_current_coords(
            getattr(self, "selected_centers", None)
        )
        table = getattr(self, "hole_distribution_table", None)
        if table is None:
            return
        if not actual_centers:
            prev_set = getattr(self, "_hole_table_highlight_rows", set())
            if prev_set:
                try:
                    table.blockSignals(True)
                    table.setUpdatesEnabled(False)
                except Exception:
                    pass
                try:
                    numeric_cols = list(range(table.columnCount()))
                    for row_num in prev_set:
                        r = row_num - 1
                        if 0 <= r < table.rowCount():
                            for c in numeric_cols:
                                item = table.item(r, c)
                                if item:
                                    item.setBackground(QBrush(Qt.NoBrush))
                finally:
                    try:
                        table.setUpdatesEnabled(True)
                        table.blockSignals(False)
                    except Exception:
                        pass
                self._hole_table_highlight_rows = set()
            return

        # 2) 坐标→行号 映射使用缓存，避免每次全表重建
        def norm(p):
            try:
                return (round(float(p[0]), 6), round(float(p[1]), 6))
            except Exception:
                return None

        up = getattr(self, "full_sorted_current_centers_up", []) or []
        down = getattr(self, "full_sorted_current_centers_down", []) or []
        cache_key = (
            len(up),
            len(down),
            sum(len(r) for r in up),
            sum(len(r) for r in down),
        )
        coord_to_row = None
        if getattr(self, "_coord_to_row_cache_key", None) == cache_key and hasattr(
                self, "_coord_to_row_cache"
        ):
            coord_to_row = self._coord_to_row_cache
        else:
            coord_to_row = {}
            for i, row in enumerate(up):
                for pt in row:
                    k = norm(pt)
                    if k is not None:
                        coord_to_row[k] = i + 1
            for i, row in enumerate(down):
                for pt in row:
                    k = norm(pt)
                    if k is not None:
                        coord_to_row[k] = i + 1
            self._coord_to_row_cache = coord_to_row
            self._coord_to_row_cache_key = cache_key

        # 3) 只做精确匹配，跳过昂贵的近似全表扫描（允许个别未命中被忽略）
        rows = []
        for p in actual_centers:
            k = norm(p)
            if k is None:
                continue
            r = coord_to_row.get(k)
            if r is not None:
                rows.append(r)

        unique_rows = sorted(set(rows)) if rows else []

        # 4) 将对应行的“整行背景”设为淡黄色；不修改文本/选择
        numeric_cols = list(range(table.columnCount()))
        if not numeric_cols:
            return

        new_set = set(unique_rows)
        prev_set = getattr(self, "_hole_table_highlight_rows", set())
        if new_set == prev_set:
            return  # 无变化则不更新，避免多余重绘

        light_yellow = QColor(255, 225, 120)

        try:
            table.blockSignals(True)
            table.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            # 取消旧高亮（恢复默认背景）
            for row_num in prev_set - new_set:
                r = row_num - 1
                if 0 <= r < table.rowCount():
                    for c in numeric_cols:
                        item = table.item(r, c)
                        if item:
                            item.setBackground(QBrush(Qt.NoBrush))
            # 设置新高亮（整行淡黄色背景）
            for row_num in new_set - prev_set:
                r = row_num - 1
                if 0 <= r < table.rowCount():
                    for c in numeric_cols:
                        item = table.item(r, c)
                        if item:
                            item.setBackground(QBrush(light_yellow))
        finally:
            try:
                table.setUpdatesEnabled(True)
                table.blockSignals(False)
            except Exception:
                pass

        self._hole_table_highlight_rows = new_set

    def highlight_right_table_col(self):
        """根据选中圆心高亮竖向统计表（按列排列时使用）"""
        actual_centers = self.selected_to_current_coords(
            getattr(self, "selected_centers", None)
        )
        table = getattr(self, "hole_distribution_table", None)
        if table is None:
            return
        if not actual_centers:
            prev_set = getattr(self, "_hole_table_highlight_cols", set())
            if prev_set:
                try:
                    table.blockSignals(True)
                    table.setUpdatesEnabled(False)
                except Exception:
                    pass
                try:
                    numeric_cols = list(range(table.columnCount()))
                    for col_num in prev_set:
                        r = col_num - 1
                        if 0 <= r < table.rowCount():
                            for c in numeric_cols:
                                item = table.item(r, c)
                                if item:
                                    item.setBackground(QBrush(Qt.NoBrush))
                finally:
                    try:
                        table.setUpdatesEnabled(True)
                        table.blockSignals(False)
                    except Exception:
                        pass
                self._hole_table_highlight_cols = set()
            return

        def norm(p):
            try:
                return (round(float(p[0]), 6), round(float(p[1]), 6))
            except Exception:
                return None

        left = getattr(self, "full_sorted_current_centers_left", []) or []
        right = getattr(self, "full_sorted_current_centers_right", []) or []
        cache_key = (
            len(left),
            len(right),
            sum(len(c) for c in left),
            sum(len(c) for c in right),
        )
        coord_to_col = None
        if getattr(self, "_coord_to_col_cache_key", None) == cache_key and hasattr(
                self, "_coord_to_col_cache"
        ):
            coord_to_col = self._coord_to_col_cache
        else:
            coord_to_col = {}
            for i, col in enumerate(left):
                for pt in col:
                    k = norm(pt)
                    if k is not None:
                        coord_to_col[k] = i + 1
            for i, col in enumerate(right):
                for pt in col:
                    k = norm(pt)
                    if k is not None:
                        coord_to_col[k] = i + 1
            self._coord_to_col_cache = coord_to_col
            self._coord_to_col_cache_key = cache_key

        cols = []
        for p in actual_centers:
            k = norm(p)
            if k is None:
                continue
            c = coord_to_col.get(k)
            if c is not None:
                cols.append(c)

        unique_cols = sorted(set(cols)) if cols else []
        numeric_cols = list(range(table.columnCount()))
        if not numeric_cols:
            return

        new_set = set(unique_cols)
        prev_set = getattr(self, "_hole_table_highlight_cols", set())
        if new_set == prev_set:
            return

        light_yellow = QColor(255, 225, 120)

        try:
            table.blockSignals(True)
            table.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            for col_num in prev_set - new_set:
                r = col_num - 1
                if 0 <= r < table.rowCount():
                    for c in numeric_cols:
                        item = table.item(r, c)
                        if item:
                            item.setBackground(QBrush(Qt.NoBrush))
            for col_num in new_set - prev_set:
                r = col_num - 1
                if 0 <= r < table.rowCount():
                    for c in numeric_cols:
                        item = table.item(r, c)
                        if item:
                            item.setBackground(QBrush(light_yellow))
        finally:
            try:
                table.setUpdatesEnabled(True)
                table.blockSignals(False)
            except Exception:
                pass

        self._hole_table_highlight_cols = new_set

    def check_and_show_lagan_tube_distance(self):
        """当且仅当选中一个自由拉杆和一个换热管时，提示两者间距（四位小数）。其它情况不提示。"""
        try:
            import math

            # 优先判断自由拉杆（build_free_form_lagan 生成，标记为 is_side_rod）
            side_rods = [
                it
                for it in getattr(self, "selected_side_rods", [])
                if getattr(it, "is_selected", False)
            ]
            target_items = side_rods
            if len(target_items) != 1:
                # 兼容普通拉杆（is_lagan）
                lagans = [
                    it
                    for it in getattr(self, "selected_lagans", [])
                    if getattr(it, "is_selected", False)
                ]
                target_items = lagans
            if len(target_items) != 1:
                return

            # 2) 恰好一个换热管被选中
            if not hasattr(self, "selected_centers") or len(self.selected_centers) != 1:
                return

            # 自由拉杆圆心（场景坐标）
            lagan_item = target_items[0]
            p = lagan_item.sceneBoundingRect().center()
            x1, y1 = p.x(), p.y()

            # 换热管圆心（当前坐标系）
            coords = self.selected_to_current_coords(self.selected_centers)
            # 兼容函数返回单个元组或单元素列表
            if not coords:
                return
            if isinstance(coords, tuple) and len(coords) == 2:
                x2, y2 = coords
            elif (
                    isinstance(coords, list)
                    and len(coords) == 1
                    and isinstance(coords[0], (tuple, list))
                    and len(coords[0]) == 2
            ):
                x2, y2 = coords[0]
            else:
                return

            dist = math.hypot(x1 - x2, y1 - y2)
            message = f"您选中的换热管孔和自由拉杆的间距为  {dist:.4f} mm。"
            try:
                self.line_tip.setText(message)
                self.line_tip.setStyleSheet("color: black;")
                self.line_tip.setVisible(True)
                from PyQt5.QtCore import QTimer

                expected_text = message

                def _clear_if_same():
                    try:
                        if self.line_tip and self.line_tip.text() == expected_text:
                            self.line_tip.setText("")
                    except Exception:
                        pass

                QTimer.singleShot(5000, _clear_if_same)
            except AttributeError:
                print(message)
        except Exception:
            # 静默捕获
            pass

    def setup_param_listeners(self):
        """为参数表格添加变化监听，实时更新参数列表"""
        # 监听表格内容变化
        self.param_table.itemChanged.connect(self.update_leftpad_params)
        # 遍历表格，为下拉框添加监听
        row_count = self.param_table.rowCount()
        for row in range(row_count):
            widget = self.param_table.cellWidget(row, 2)
            if isinstance(widget, QComboBox):
                widget.currentIndexChanged.connect(self.update_leftpad_params)

    # TODO 获取选中的两个换热管的编号
    def get_selected_y_center_numbers(
            self, selected_centers, print_cross_y_left, print_cross_y_right, row
    ):
        # 仅按当前可交叉布管候选（print_cross_*）匹配，避免使用 full_* 导致已删除管孔误参与
        left_number = None
        right_number = None

        for center in selected_centers:
            for item in print_cross_y_left:
                # item格式：(编号, x, y)，center格式：(x, y)
                if (item[1], item[2]) == center:
                    left_number = item[0]
                    break
            for item in print_cross_y_right:
                if (item[1], item[2]) == center:
                    right_number = item[0]
                    break

        if left_number is None or right_number is None:
            raise ValueError(
                "selected_centers中的坐标未完全匹配到print_cross_y_left或print_cross_y_right"
            )

        return {"left_number": left_number, "right_number": right_number}

    def update_leftpad_params(self):
        """实时更新左侧参数为列表形式"""
        self.current_leftpad = []  # 清空现有列表
        row_count = self.param_table.rowCount()

        for row in range(row_count):
            # 跳过隐藏行
            if self.param_table.isRowHidden(row):
                continue

            # 序号（第0列）
            num_item = self.param_table.item(row, 0)
            num = num_item.text() if num_item else str(row + 1)

            # 参数名（第1列）
            name_item = self.param_table.item(row, 1)
            name = name_item.text() if name_item else "未知参数"

            # 参数值（第2列）
            if name == "管程分程形式":
                value = self.get_selected_tube_pass_form() or ""
            else:
                value = self._get_param_value_text(row)

            # 单位（第3列）
            unit_item = self.param_table.item(row, 3)
            unit = unit_item.text() if unit_item else ""

            # 添加到列表（每个元素是一个字典，方便后续取值）
            self.current_leftpad.append(
                {"序号": num, "参数名": name, "参数值": value, "单位": unit}
            )

    def _get_lagan_required_count(self):
        """按公称直径DN+拉杆直径查标准要求数量。"""
        try:
            dn = float(self.get_gongchengzhijing_count())
            lagan_d = float(self.get_laganzhijing_count())
        except (TypeError, ValueError):
            return None

        try:
            print(f"[lagan标准查表] DN={dn}, 拉杆直径={lagan_d}")
        except Exception:
            pass

        standard_table = {
            10.0: [(0, 400, 4), (400, 700, 6), (700, 900, 10), (900, 1300, 12), (1300, 1500, 16), (1500, 1800, 18), (1800, 2000, 24), (2000, 2300, 32), (2300, 2600, 40), (2600, 2800, 48), (2800, 3000, 56), (3000, 3200, 64), (3200, 3400, 72), (3400, 3600, 80), (3600, 3800, 88), (3800, 4000, 98), (4000, 5000, 136), (5000, 6000, 178)],
            12.0: [(0, 400, 4), (400, 700, 4), (700, 900, 8), (900, 1300, 10), (1300, 1500, 12), (1500, 1800, 14), (1800, 2000, 18), (2000, 2300, 24), (2300, 2600, 28), (2600, 2800, 32), (2800, 3000, 40), (3000, 3200, 44), (3200, 3400, 52), (3400, 3600, 56), (3600, 3800, 64), (3800, 4000, 68), (4000, 5000, 96), (5000, 6000, 124)],
            16.0: [(0, 400, 4), (400, 700, 4), (700, 900, 6), (900, 1300, 6), (1300, 1500, 8), (1500, 1800, 10), (1800, 2000, 12), (2000, 2300, 14), (2300, 2600, 16), (2600, 2800, 20), (2800, 3000, 24), (3000, 3200, 26), (3200, 3400, 28), (3400, 3600, 32), (3600, 3800, 36), (3800, 4000, 40), (4000, 5000, 56), (5000, 6000, 74)],
        }
        if lagan_d not in standard_table:
            try:
                print(f"[lagan标准查表] 拉杆直径={lagan_d} 不在标准表(10/12/16)中，返回None")
            except Exception:
                pass
            return None
        for low, high, required in standard_table[lagan_d]:
            if low <= dn < high:
                try:
                    print(f"[lagan标准查表] 命中区间: [{low},{high}) -> {required}")
                except Exception:
                    pass
                return required
        try:
            print("[lagan标准查表] 未命中任何DN区间，返回None")
        except Exception:
            pass
        return None

    def update_total_holes_count(self):
        """更新“总管孔数量”提示。

        统一按当前界面上的实际换热管数量（current_centers）更新，
        避免接口返回值与当前画面状态不一致。
        """
        total = None
        try:
            total = len(getattr(self, "current_centers", []) or [])
        except Exception:
            total = 0

        # 处理初始值：如果未布管且 current_centers 为空，显示 980
        if not getattr(self, "has_piped", False) and total == 0:
            total = 980

        self.total_holes_label.setText(f"总管孔数量: {total}")
        # 右侧管孔数量分布表必须随“当前数据”同步更新：
        # 许多操作会原地修改 self._current_centers（不触发 setter），但会调用 update_total_holes_count。
        try:
            if hasattr(self, "hole_distribution_table") and self.hole_distribution_table is not None:
                self.update_tube_nums()
        except Exception:
            pass

    def toggle_arrange_text(self):
        """切换按钮文字（按行排列 <-> 按列排列）并更新表格数据"""
        if hasattr(self, 'is_arrange_by_row'):
            self.is_arrange_by_row = not self.is_arrange_by_row
            if self.is_arrange_by_row:
                self.arrange_button.setText("按行")
            else:
                self.arrange_button.setText("按列")
            # 切换后同步切换右侧表头
            self.update_hole_distribution_headers()
            # 切换后更新表格数据
            self.update_tube_nums()
            # 重新绑定表格选中逻辑
            self.bind_table_selection_handler()

    def update_hole_distribution_headers(self):
        """根据按钮状态切换右侧管孔数量分布表的表头"""
        if not hasattr(self, "hole_distribution_table"):
            return

        if hasattr(self, "is_arrange_by_row") and self.is_arrange_by_row:
            headers = ["至水平中心线行号", "管孔数量(上)", "管孔数量(下)"]
        else:
            headers = ["至竖直中心线列号", "管孔数量(左)", "管孔数量(右)"]

        self.hole_distribution_table.setHorizontalHeaderLabels(headers)
        self._apply_bold_table_header(self.hole_distribution_table, point_size=10)
        for i, header_text in enumerate(headers):
            header_item = self.hole_distribution_table.horizontalHeaderItem(i)
            if header_item:
                header_item.setToolTip(header_text)

    def update_total_lagan_count(self):
        """更新拉杆要求/已有数量显示。"""
        lagan_list = getattr(self, "lagan_info", []) or []
        red_list = getattr(self, "red_dangban", []) or []
        total = len(lagan_list) + len(red_list)
        std = self._get_lagan_required_count()
        self.current_lagan_standard_required = std
        if hasattr(self, "lagan_required_label"):
            if isinstance(std, (int, float)):
                std_num = int(std) if float(std).is_integer() else std
                if total < std:
                    text = f"拉杆标准要求数量{std_num}/已有数量<span style='color:red;'>{total}</span>"
                else:
                    text = f"拉杆标准要求数量{std_num}/已有数量{total}"
            else:
                text = f"拉杆标准要求数量-/已有数量{total}"
            self.lagan_required_label.setText(text)

