    def cal_di(self, user_Di, user_DN, user_Dit):
        import modules.buguan.buguan_ziyong.qiaotineizhijing as qtzj

        # 调用接口获取壳体内直径数据
        print(user_DN)
        print("当前获取的公称直径")
        print(self.isDN_change)
        print("这是DN更新标志")
        print(self.isDi_change)
        print("这是Di更新标志")
        # 若布管操作记录表中已存在当前产品记录，则强制置位 isDi_change
        # （用于后续接口按“已发生Di相关操作”分支处理）
        record_conn = None
        record_cursor = None
        try:
            record_conn = pymysql.connect(
                host="localhost",
                user="root",
                password="123456",
                database="产品设计活动库",
                charset="utf8mb4",
                cursorclass=pymysql.cursors.DictCursor,
            )
            record_cursor = record_conn.cursor()
            record_cursor.execute(
                "SELECT `是否调过接口` FROM 产品设计活动表_布管操作记录表 WHERE 产品ID = %s LIMIT 1",
                (self.productID,),
            )
            record_row = record_cursor.fetchone()
            if record_row and str(record_row.get("是否调过接口", "")).strip() == "1":
                self.isDi_change = True
        except Exception as e:
            print(f"[cal_di] 查询布管操作记录表失败: {e}")
        finally:
            try:
                if record_cursor:
                    record_cursor.close()
            except Exception:
                pass
            try:
                if record_conn:
                    record_conn.close()
            except Exception:
                pass

        di_result = None  # 先初始化，避免未赋值引用
        if self.heat_exchanger in ["AEU", "BEU"]:
            di_result = qtzj.cal_qiaotineizhijing_U(
                self.productID, self.isDi_change, self.isDN_change, user_Di, user_DN, user_Dit
            )
        elif self.heat_exchanger in ["AKU", "BKU"]:
            di_result = qtzj.cal_qiaotineizhijing_KU(
                self.productID, self.isDi_change, self.isDN_change, user_Di, user_DN, user_Dit
            )
        elif self.heat_exchanger in ["AES", "BES"]:
            di_result = qtzj.cal_qiaotineizhijing_S(
                self.productID, self.isDi_change, self.isDN_change, user_Di, user_DN, user_Dit
            )
        elif self.heat_exchanger in ["NEN", "BEM", "NEN(Head)"]:
            print(1111111111111111111111111)
            di_result = qtzj.cal_qiaotineizhijing_NEN(
                self.productID, self.isDi_change, self.isDN_change, user_Di, user_DN, user_Dit
            )
        elif self.heat_exchanger in ["AEM"]:
            di_result = qtzj.cal_qiaotineizhijing_AEM(
                self.productID, self.isDi_change, self.isDN_change, user_Di, user_DN, user_Dit
            )
        else:
            # 未覆盖的换热器类型，直接返回 None
            print(f"未知换热器型式: {self.heat_exchanger}")
            return None, None  # 返回两个None值

        conn = pymysql.connect(
            host="localhost", user="root", password="123456",
            database="产品设计活动库", charset="utf8mb4", cursorclass=pymysql.cursors.DictCursor
        )
        cursor = conn.cursor()

        # 获取产品ID
        product_id = self.productID

        cursor.execute("""
            SELECT 数值 FROM 产品设计活动表_通用数据表
            WHERE 产品ID = %s AND 参数名称 = '是否以外径为基准*'
        """, (product_id,))
        row = cursor.fetchone()

        waijing_bool = ""
        waijing = "0"
        if row and "数值" in row:
            waijing_bool = "1" if row["数值"] == "是" else "0"

        if waijing_bool == "1":
            cursor.execute("""
                SELECT 数值 FROM 产品设计活动表_通用数据表
                WHERE 产品ID = %s AND 参数名称 = '外径'
            """, (product_id,))
            row_waijing = cursor.fetchone()
            waijing = row_waijing["数值"]

        # 关闭数据库连接
        cursor.close()
        conn.close()

        # 验证壳体内直径是否超过外径
        if float(user_DN) > float(waijing):
            message = f"壳体内直径无法超过用户选定外径数值"
            try:
                self.line_tip.setText(message)
                self.line_tip.setStyleSheet("color: black;")
                self.line_tip.setVisible(True)
            except Exception as e:
                print(f"[WARN] 设置提示信息失败: {e}")

            from PyQt5.QtCore import QTimer
            try:
                def clear_tip_safely():
                    try:
                        if hasattr(self, 'line_tip') and self.line_tip is not None:
                            self.line_tip.setText("")
                    except Exception as e:
                        print(f"[WARN] 清除提示信息失败: {e}")

                QTimer.singleShot(5000, clear_tip_safely)
            except Exception as e:
                print(f"[WARN] 设置定时器失败: {e}")

        import json

        try:
            if di_result is None:
                print("未获取到圆筒内径计算结果")
                return None, None  # 返回两个None值

            # 处理数据，可能是字符串或已解析的对象
            data = di_result

            # 如果是字符串则进行解析
            if isinstance(data, str):
                data = json.loads(data)

            # 循环解析直到得到字典类型（处理可能的多层嵌套）
            while isinstance(data, str):
                data = json.loads(data)

            # 验证数据结构是否正确
            if not isinstance(data, dict):
                raise TypeError("解析后的数据不是字典类型")

            # 初始化两个返回值
            shell_di = None  # 壳体内直径
            tube_box_di = None  # 管箱内直径

            # 1. 查找壳体内直径（AKU/BKU 从小端壳体圆筒取数，其余从壳体圆筒取数）
            _hx = getattr(self, "heat_exchanger", None) or ""
            if isinstance(_hx, str):
                _hx = _hx.strip().upper()
            _shell_cylinder_key = (
                "管箱圆筒" if _hx in ("AKU", "BKU") else "壳体圆筒"
            )
            if (
                    "DictOutDatas" in data
                    and _shell_cylinder_key in data["DictOutDatas"]
                    and "Datas" in data["DictOutDatas"][_shell_cylinder_key]
            ):
                for item in data["DictOutDatas"][_shell_cylinder_key]["Datas"]:
                    if item.get("Name") == "圆筒内径":
                        value = item.get("Value")
                        # 可以根据需要将字符串转换为数值类型
                        try:
                            # 如果值是字符串类型的数字，尝试转换为float
                            if isinstance(value, str):
                                shell_di = float(value)
                            else:
                                shell_di = value
                        except (ValueError, TypeError):
                            shell_di = value  # 返回原始值如果转换失败

            # 2. 查找管箱内直径
            if (
                    "DictOutDatas" in data
                    and "管箱圆筒" in data["DictOutDatas"]
                    and "Datas" in data["DictOutDatas"]["管箱圆筒"]
            ):
                for item in data["DictOutDatas"]["管箱圆筒"]["Datas"]:
                    if item.get("Name") == "圆筒内径":
                        value = item.get("Value")
                        # 可以根据需要将字符串转换为数值类型
                        try:
                            # 如果值是字符串类型的数字，尝试转换为float
                            if isinstance(value, str):
                                tube_box_di = float(value)
                            else:
                                tube_box_di = value
                        except (ValueError, TypeError):
                            tube_box_di = value  # 返回原始值如果转换失败

            # 打印调试信息
            print(f"壳体内直径: {shell_di}")
            print(f"管箱内直径: {tube_box_di}")

            # 如果两个值都未找到，打印提示信息
            if shell_di is None and tube_box_di is None:
                print("未找到壳体和管箱的圆筒内径数据")
            elif shell_di is None:
                print("未找到壳体的圆筒内径数据")
            elif tube_box_di is None:
                print("未找到管箱的圆筒内径数据")

            # 返回两个值：壳体内直径, 管箱内直径
            return shell_di, tube_box_di

        except json.JSONDecodeError as e:
            print(f"JSON解析错误: {str(e)}")
            return None, None  # 返回两个None值
        except TypeError as e:
            print(f"数据类型错误: {str(e)}")
            return None, None  # 返回两个None值
        except Exception as e:
            print(f"处理数据时发生错误: {str(e)}")
            return None, None  # 返回两个None值

    def _commit_param_table_open_editor(self):
        """正在编辑参数表时，先把委托编辑器内容写入模型再读取表格。

        全局 Enter 绑在布管上会先于 Qt 结束单元格编辑；否则会读到 item 里的旧值
        （例如编辑框已是 610，item 仍为 577，一布管又写回 577）。"""
        from PyQt5.QtWidgets import QAbstractItemView, QApplication, QComboBox

        table = getattr(self, "param_table", None)
        if table is None or table.state() != QAbstractItemView.EditingState:
            return
        idx = table.currentIndex()
        if not idx.isValid():
            return
        editor = table.indexWidget(idx)
        if editor is None:
            editor = QApplication.focusWidget()
        if editor is None or not table.isAncestorOf(editor):
            return
        delegate = table.itemDelegate(idx)
        if delegate is not None:
            delegate.setModelData(editor, table.model(), idx)
        # 对可编辑下拉框，额外把 lineEdit 文本写回 currentText，避免“回车未失焦”时仍读到旧值
        try:
            w = table.cellWidget(idx.row(), idx.column())
            if isinstance(w, QComboBox) and w.isEditable() and w.lineEdit() is not None:
                txt = w.lineEdit().text().strip()
                if txt != "":
                    w.setCurrentText(txt)
        except Exception:
            pass

    def _safe_disconnect_param_table_item_changed(self):
        """断开 param_table.itemChanged 的全部连接。

        PyQt5：当前无任何连接时调用 disconnect() 会抛 TypeError（勿记入布管异常）。
        """
        table = getattr(self, "param_table", None)
        if table is None:
            return
        try:
            table.itemChanged.disconnect()
        except TypeError:
            pass

    # TODO 布管函数
    def calculate_piping_layout(self):
        self.is_x_line1 = False
        self.is_x_line2 = False
        self.is_x_line3 = False
        self.is_y_line1 = False
        self.is_y_line2 = False
        self.is_y_line3 = False
        self.coord_x_line1_2 = []
        self.coord_x_line2_2 = []
        self.coord_x_line3_2 = []
        self.coord_x_line1_4 = []
        self.coord_x_line2_4 = []
        self.coord_x_line3_4 = []
        self.coord_y_line1_2 = []
        self.coord_y_line2_2 = []
        self.coord_y_line3_2 = []
        self.coord_y_line1_4 = []
        self.coord_y_line2_4 = []
        self.coord_y_line3_4 = []

        # 方法1：使用blockSignals禁用场景信号
        was_blocked = self.graphics_scene.blockSignals(True)

        try:
            # 清除圆心连线/标记（勿误删主坐标轴）
            if hasattr(self, "clear_connection_lines"):
                self.clear_connection_lines(self.graphics_scene)
            if hasattr(self, "clear_markers"):
                self.clear_markers(self.graphics_scene)
            elif self.graphics_scene is not None:
                items_to_remove = []
                for item in self.graphics_scene.items():
                    try:
                        role = item.data(Qt.UserRole)
                    except Exception:
                        role = None
                    if role in (_BUGUAN_AXIS_ITEM_ROLE, _BUGUAN_AXIS_LABEL_ROLE):
                        continue
                    if isinstance(item, (QGraphicsLineItem, QGraphicsEllipseItem)) and (
                            item in getattr(self, "connection_lines", [])
                            or item.data(0) == "marker"
                    ):
                        items_to_remove.append(item)
                for item in items_to_remove:
                    self.graphics_scene.removeItem(item)
                if hasattr(self, "connection_lines"):
                    self.connection_lines.clear()
                if hasattr(self, "cross_pipe_lines"):
                    self.cross_pipe_lines.clear()

        finally:
            # 恢复场景的信号状态
            self.graphics_scene.blockSignals(was_blocked)
            # 强制更新场景
            self.graphics_scene.update()

        self.has_piped = True
        self.left_data_pd = []

        self._commit_param_table_open_editor()

        # 每次布管前，强制按“do+排列方式→S 对应表(2.10.1.1)”刷新一次 S，
        # 防止历史流程（如旧 output_data 回写）遗留的 S 被带入本次接口入参。
        try:
            self.update_tube_center_distance()
        except Exception as _us_e:
            print(f"[calculate_piping_layout] update_tube_center_distance: {_us_e}")

        # 初始加载后可能出现：DN 已由设计数据表覆盖，Dis 才由 update_DN_Di 对齐；若此处不先同步则下面读到的仍是旧 Dis
        try:
            self.update_DN_Di()
        except Exception as _ud_e:
            print(f"[calculate_piping_layout] update_DN_Di: {_ud_e}")

        # 布管前保险：管箱内直径 Dit 与壳体内直径 Dis 一致（如仅回车提交 Dis、未走 itemChanged 联动）
        try:
            self._sync_dis_dit_peer_from_source("壳体内直径 Dis")
        except Exception as _dit_guard_e:
            print(f"[calculate_piping_layout] Dis→Dit 同步: {_dit_guard_e}")

        # 1. 读取参数
        DL = None
        do = None
        height_0_180 = None
        height_90_270 = None
        DN = None
        Di = None
        table = self.param_table

        for row in range(table.rowCount()):
            param_name = table.item(row, 1).text() if table.item(row, 1) else ""
            param_value = table.cellWidget(row, 2)

            if param_value and isinstance(param_value, QComboBox):
                param_value = param_value.currentText()
            else:
                item = table.item(row, 2)
                param_value = item.text() if item else ""

            self.left_data_pd.append({"参数名": param_name, "参数值": param_value})

            # 提取关键参数
            if param_name == "壳体内直径 Dis":
                Di = float(param_value) if param_value else None
            elif param_name == "公称直径 DN":
                DN = float(param_value) if param_value else None
            elif param_name == "换热管外径 do":
                do = float(param_value) if param_value else None
                self.r = float(do / 2) if do else 0
            elif param_name == "非布管区域弦高（0°/180°）":
                height_0_180 = float(param_value) if param_value else 0
            elif param_name == "非布管区域弦高（90°/270°）":
                height_90_270 = float(param_value) if param_value else 0
            elif param_name == "布管限定圆 DL":
                DL = float(param_value) if param_value else None

        # 参数验证
        if Di is None or do is None:
            QMessageBox.warning(
                self, "提示", "请先输入壳体内直径 Dis 和换热管外径 do 两个参数。"
            )
            return None

        # 获取换热器型号
        heat_exchanger_type = (
            self.heat_exchanger if hasattr(self, "heat_exchanger") else ""
        )
        if not heat_exchanger_type and self.productID:

            conn = None
            try:
                conn = create_product_connection()
                if conn:
                    with conn.cursor() as cursor:
                        query = "SELECT 产品型式 FROM 产品设计活动表 WHERE 产品ID = %s"
                        cursor.execute(query, (self.productID,))
                        result = cursor.fetchone()
                        if result and "产品型式" in result:
                            heat_exchanger_type = result["产品型式"].strip().upper()
                            self.heat_exchanger = heat_exchanger_type
                            if hasattr(self, "update_screw_ring_button_state"):
                                self.update_screw_ring_button_state()
                            self.update_cross_pipe_button_state(heat_exchanger_type)
            except pymysql.MySQLError as e:
                print(f"数据库查询产品型式失败: {e}")
            finally:
                if conn and conn.open:
                    conn.close()

        # 仅当 布管限定圆 DL > 壳体内直径 Dis 时调用 update_tube_layout_circle_dl 重算并回写；
        # DL <= Dis 时不重算，布管入参沿用参数表当前值。
        try:
            if (
                    Di is not None
                    and do is not None
                    and DL is not None
                    and float(DL) > float(Di)
            ):
                self._suppress_open_s_dl_autoupdate = False
                self.update_tube_layout_circle_dl()
        except Exception as _dl_sync_e:
            print(f"[calculate_piping_layout] update_tube_layout_circle_dl: {_dl_sync_e}")

        dl_text_after_sync = None
        for row in range(table.rowCount()):
            pname = table.item(row, 1).text() if table.item(row, 1) else ""
            if pname != "布管限定圆 DL":
                continue
            pv = table.cellWidget(row, 2)
            if pv and isinstance(pv, QComboBox):
                dl_text_after_sync = pv.currentText().strip()
            else:
                it = table.item(row, 2)
                dl_text_after_sync = (it.text().strip() if it else "") or None
            if dl_text_after_sync:
                try:
                    DL = float(dl_text_after_sync)
                except (ValueError, TypeError):
                    pass
            break

        for rec in self.left_data_pd:
            if isinstance(rec, dict) and rec.get("参数名") == "布管限定圆 DL":
                if dl_text_after_sync:
                    rec["参数值"] = dl_text_after_sync
                break

        # 更新参数表中的DL值
        dl_row = -1
        row_count = self.param_table.rowCount()
        for row in range(row_count):
            param_name_item = self.param_table.item(row, 1)
            if param_name_item and param_name_item.text() == "布管限定圆 DL":
                dl_row = row
                break

        if dl_row != -1 and DL is not None:
            # 临时断开信号避免循环触发
            original_handler = None
            if hasattr(self, "handle_param_change"):
                try:
                    self.param_table.itemChanged.disconnect(self.handle_param_change)
                    original_handler = self.handle_param_change
                except:
                    pass

            # 与 input_json / draw_layout 使用的 DL 数值对齐写回表格（格式统一）
            dl_item = self.param_table.item(dl_row, 2)
            if dl_item:
                dl_item.setText(f"{DL: .1f}")
            else:
                self.param_table.setItem(dl_row, 2, QTableWidgetItem(f"{DL: .1f}"))
            print(f"已更新布管限定圆 DL: {DL: .1f}")

            # 重新连接信号
            if original_handler:
                try:
                    self.param_table.itemChanged.connect(original_handler)
                except:
                    pass

        # ==========================
        # DN/Dis/DL 临时回滚基准（temp1）
        # 每次布管（calculate_piping_layout）开始新一轮基准：后续用户修改会生成 temp2 做校验
        # 校验通过：temp2 -> temp1；不通过：回写到 temp1（只回写被改参数）
        # ==========================
        try:
            if DN is not None and Di is not None and DL is not None and DN >= Di >= DL:
                self._dn_di_dl_temp1 = {"DN": float(DN), "Di": float(Di), "DL": float(DL)}
                self._dn_di_dl_temp2 = None
                # 同步旧机制（如果有依赖）
                self._last_valid_values = dict(self._dn_di_dl_temp1)
                self._dn_di_dl_no_history_warned = False
                print(f"[DN/Di/DL temp] 初始化 temp1（来源：calculate_piping_layout）: {self._dn_di_dl_temp1}")
            else:
                # 若当前三值不合法，则保留上一轮 temp1（避免基准被污染）
                print(
                    f"[DN/Di/DL temp WARN] 本轮布管未初始化 temp1（当前 DN/Di/DL 不满足约束）：DN={DN}, Di={Di}, DL={DL}"
                )
        except Exception as e:
            print(f"[DN/Di/DL temp ERROR] 初始化 temp1 失败: {e}")

        # 转换为DataFrame
        self.left_data_pd = pd.DataFrame(self.left_data_pd)

        # 同步部分关键参数到全局变量，供轴向设计页面等使用
        try:
            basic_params = {}
            params_to_fetch = [
                "换热管公称长度 LN",
                "折流/支持板外径",
                "折流板切口方向",
                "折流板要求切口率",
                "公称直径 DN",
                "壳体内直径 Dis",
                "管箱内直径 Dit",
                "换热管外径 do",
            ]
            for name in params_to_fetch:
                try:
                    subset = self.left_data_pd[self.left_data_pd["参数名"] == name]
                    if not subset.empty:
                        value = subset.iloc[0]["参数值"]
                        basic_params[name] = "" if value is None else str(value)
                except Exception:
                    continue
            print(
                "[DEBUG calculate_piping_layout] basic_params from left_data_pd:",
                basic_params,
            )
            update_axial_basic_params(basic_params)
            print(
                "[DEBUG calculate_piping_layout] axial_basic_params after update:",
                axial_basic_params,
            )
        except Exception as e:
            print(
                "[DEBUG calculate_piping_layout] update_axial_basic_params failed:", e
            )

        # 2. 构造JSON映射
        param_mapping = {
            "换热管布置方式": (
                "LB_IsRangeCenter",
                {"对中": "0", "跨中": "1", "任意": "2"},
            ),
            "旁路挡板厚度": ("LB_BPBThick", None),
            "分程隔板放置型式": ("LB_ClapboardType", None),
            "管程分程形式": ("LB_Tubeform", None),
            "滑道高度": ("LB_SlipWayHeight", None),
            # 与 calculate_piping 一致：不向布管接口传 滑道形式/导轨类型/圆钢规格（行在 hidden_params 中，
            # 从隐藏行读入会混入与 calculate_piping 不同的多余字段，接口以精简 input 为准）
            "拉杆直径": ("LB_TieRodD", None),
            "管程程数": ("LB_TubePassCount", None),
            "壳程程数": ("Shell_NumberOfPasses", None),
            "公称直径 DN": ("LB_DN", None),
            "壳体内直径 Dis": ("LB_Di", None),
            "布管限定圆 DL": ("LB_DL", None),
            "换热管孔需求数量": ("LB_TotalTubesCountNeed", None),
            "换热管外径 do": ("LB_TubeD", None),
            "换热管壁厚 δ": ("LB_TubeThick", None),
            "换热管排列方式": (
                "LB_RangeType",
                {
                    "正三角形": "1",
                    "转角正三角形": "0",
                    "正方形": "2",
                    "转角正方形": "3",
                },
            ),
            "换热管公称长度 LN": ("LB_TubeLong", None),
            "换热管中心距 S": ("LB_S", None),
            "折流板切口方向": (
                "LB_BaffleDirection",
                {"水平上下": "1", "垂直左右": "2"},
            ),
            "折流板要求切口率": ("LB_BafflePerStr", None),
            "切口距垂直中心线间距": ("LB_BaffleToODistance", None),
            "折流/支持板间距": ("BaffleSpacing", None),
            "折流/支持板外径": ("LB_BaffleOD", None),
            "分程隔板两侧相邻管中心距（竖直）": ("LB_SN", None),
            "分程隔板两侧相邻管中心距（水平）": ("LB_SNH", None),
            "隔条位置尺寸 W": ("LB_W", None),
            "滑道厚度": ("LB_SlipWayThick", None),
            "滑道与竖直中心线夹角": ("LB_SlipWayAngle", None),
            "防冲板厚度": ("LB_BaffleThick", None),
            "防冲板折边角度": ("LB_BaffleA", None),
            "与圆筒连接防冲板方位": ("LB_BafflePosition", None),
            "与圆筒连接防冲板宽度": ("LB_BaffleW", None),
            "与圆筒连接防冲板至圆筒内壁最大距离": ("LB_BaffleDis", None),
            "热交换器类型": (
                "LB_HEType",
                {
                    "未选择": "2",
                    "浮头式热交换器": "0",
                    "固定管板式热交换器": "1",
                    "U型管式热交换器": "2",
                },
            ),
        }

        input_json = {}
        for _, row in self.left_data_pd.iterrows():
            param_name = row["参数名"]
            param_value = str(row["参数值"]).strip()
            if param_name == "中间挡板厚度":
                self.block_thickness = param_value

            if param_name in param_mapping:
                json_key, value_map = param_mapping[param_name]

                if json_key == "SlipWays":
                    try:
                        input_json[json_key] = json.loads(param_value)
                    except Exception as e:
                        print("滑道坐标 JSON 格式错误，无法解析：", param_value)
                        input_json[json_key] = []
                elif value_map:
                    input_json[json_key] = value_map.get(param_value, "0")
                else:
                    # 特殊处理隔条位置尺寸W参数：当值为"程序推荐"时传递0
                    if param_name == "隔条位置尺寸 W" and param_value == "程序推荐":
                        input_json[json_key] = "0"
                    else:
                        input_json[json_key] = param_value

        # 请求前按 do+排列方式映射修正 LB_S（仅在用户未手动覆盖 S 时），避免异步联动时带入历史值
        try:
            if getattr(self, "_user_override_tube_center_distance", False):
                raise RuntimeError("skip_force_S_due_to_user_override")
            global _TUBE_CENTER_DISTANCE_MAP_CACHE
            if _TUBE_CENTER_DISTANCE_MAP_CACHE is None:
                _TUBE_CENTER_DISTANCE_MAP_CACHE = {}
                config_value = self.get_config_value("2.10.1.1")
                if config_value:
                    try:
                        config_rows = (
                            ast.literal_eval(config_value)
                            if isinstance(config_value, str)
                            else config_value
                        )
                        do_row_cfg = None
                        tri_s_row_cfg = None
                        sq_s_row_cfg = None
                        for r_cfg in (config_rows or []):
                            if not r_cfg or len(r_cfg) < 2:
                                continue
                            name_cfg = str(r_cfg[0]).strip()
                            if name_cfg == "换热管外径d":
                                do_row_cfg = r_cfg
                            elif name_cfg == "换热管中心距S（三角形排列）":
                                tri_s_row_cfg = r_cfg
                            elif name_cfg == "换热管中心距S（正方形排列）":
                                sq_s_row_cfg = r_cfg
                        if do_row_cfg and tri_s_row_cfg and sq_s_row_cfg:
                            do_values_cfg = [
                                float(x) for x in do_row_cfg[1:] if str(x).strip() != ""
                            ]
                            tri_values_cfg = [
                                float(x) for x in tri_s_row_cfg[1:] if str(x).strip() != ""
                            ]
                            sq_values_cfg = [
                                float(x) for x in sq_s_row_cfg[1:] if str(x).strip() != ""
                            ]
                            for i_cfg, d_cfg in enumerate(do_values_cfg):
                                if i_cfg < len(tri_values_cfg):
                                    _TUBE_CENTER_DISTANCE_MAP_CACHE[(d_cfg, "三角形排列")] = tri_values_cfg[i_cfg]
                                if i_cfg < len(sq_values_cfg):
                                    _TUBE_CENTER_DISTANCE_MAP_CACHE[(d_cfg, "正方形排列")] = sq_values_cfg[i_cfg]
                    except Exception as _s_cfg_e:
                        print(f"[calculate_piping_layout] 解析S映射配置失败: {_s_cfg_e}")

            do_for_s = None
            try:
                do_for_s = float(str(input_json.get("LB_TubeD", "")).strip())
            except Exception:
                do_for_s = None
            range_code = str(input_json.get("LB_RangeType", "")).strip()
            range_type_for_s = None
            if range_code in ("0", "1"):
                range_type_for_s = "三角形排列"
            elif range_code in ("2", "3"):
                range_type_for_s = "正方形排列"

            if do_for_s is not None and range_type_for_s:
                mapped_s = _TUBE_CENTER_DISTANCE_MAP_CACHE.get((do_for_s, range_type_for_s))
                if mapped_s is not None:
                    mapped_s_text = f"{float(mapped_s):.1f}"
                    # 只有在用户未手动覆盖 S 时，才用推荐值填充入参（不再强制回写界面）
                    input_json["LB_S"] = mapped_s_text
                    print(
                        f"[calculate_piping_layout] 强制修正LB_S: do={do_for_s}, range={range_code}({range_type_for_s}) -> {mapped_s_text}"
                    )
        except Exception as _force_s_e:
            # 用户手动覆盖时会主动跳过
            if str(_force_s_e) != "skip_force_S_due_to_user_override":
                print(f"[calculate_piping_layout] 强制修正LB_S失败: {_force_s_e}")

        # 确保使用计算后的DL值
        input_json["LB_DL"] = f"{DL: .1f}"
        input_json["LB_Di"] = f"{Di: .1f}" if Di else ""

        # 处理隔条位置尺寸W：如果映射关系中没有找到，则LB_W取0
        # if 'LB_W' in input_json:
        #     try:
        #         # 从input_json中读取所需参数
        #         dn_value = float(input_json.get('LB_DN', 0)) if input_json.get('LB_DN') else None
        #         do_value = float(input_json.get('LB_TubeD', 0)) if input_json.get('LB_TubeD') else None
        #         tube_pass_form = self.tube_pass_form_value if hasattr(self, 'tube_pass_form_value') else None
        #
        #         # 如果参数齐全，尝试从映射关系查找
        #         if dn_value and do_value and tube_pass_form:
        #             from modules.buguan.buguan_ziyong.divider_position_mapping import get_divider_position_w
        #             w_value = get_divider_position_w(dn_value, tube_pass_form, do_value)
        #
        #             # 如果映射关系中没有找到，设置LB_W为0
        #             if w_value is None:
        #                 print(
        #                     f"映射关系中未找到W值（DN={dn_value}, 分程形式={tube_pass_form}, 外径={do_value}），LB_W设置为0")
        #                 input_json['LB_W'] = "0"
        #             else:
        #                 # 如果找到了，维持原逻辑（不修改）
        #                 print(f"映射关系中找到W值：{w_value}，维持原逻辑")
        #         else:
        #             # 参数不齐全，无法查找映射关系，设置为0
        #             print(f"参数不齐全（DN={dn_value}, do={do_value}, 分程形式={tube_pass_form}），LB_W设置为0")
        #             input_json['LB_W'] = "0"
        #     except Exception as e:
        #         print(f"处理LB_W时发生错误：{e}，LB_W设置为0")
        #         input_json['LB_W'] = "0"

        # 补充默认值
        connection = pymysql.connect(
            host="localhost",
            user="root",
            password="123456",
            database="产品设计活动库",
            charset="utf8mb4",
            cursorclass=pymysql.cursors.DictCursor,
        )

        cursor = connection.cursor()
        sql = """
            SELECT 参数值 
            FROM 产品设计活动表_元件附加参数表
            WHERE 产品ID = %s
              AND 元件名称 = %s
              AND 参数名称 = %s
            LIMIT 1
        """
        cursor.execute(sql, (product_id, "拉杆", "拉杆型式"))
        result = cursor.fetchone()
        cursor.close()

        if result and result["参数值"] == "焊接拉杆":
            # 焊接拉杆 → 直接取换热管外径
            input_json["LB_TieRodD"] = input_json.get("LB_TubeD", "")
        else:
            # 螺纹拉杆：按换热管外径 do 选取拉杆直径
            od_val = (
                float(input_json.get("LB_TubeD", 0))
                if input_json.get("LB_TubeD")
                else (
                    float(input_json.get("LB_TieRodD", 0))
                    if input_json.get("LB_TieRodD")
                    else 0
                )
            )
            if 10 <= od_val <= 14:
                input_json["LB_TieRodD"] = "10"
            elif 14 < od_val < 25:
                input_json["LB_TieRodD"] = "12"
            elif 25 <= od_val <= 32:
                input_json["LB_TieRodD"] = "16"
            elif 32 < od_val <= 57:
                input_json["LB_TieRodD"] = "20"
            else:
                input_json["LB_TieRodD"] = "12"
        input_json["LB_ClapboardType"] = "2"

        # 3. 根据产品ID从数据库获取产品型式并设置热交换器类型
        he_type = "2"  # 默认U型管式
        product_type_str = heat_exchanger_type  # 用于存储产品型式字符串
        self.heat_exchanger = product_type_str
        # 根据产品型式判断热交换器类型
        if product_type_str in ["AEU", "BEU", "AKU", "BKU"]:
            he_type = "2"  # U型管式
        elif product_type_str in ["NEN", "BEM", "AEM", "NEN(Head)"]:
            he_type = "1"  # 固定管板式
        elif product_type_str in ["AES", "BES"]:
            he_type = "0"  # 浮头式
        if self.productID and not product_type_str:
            conn = None
            try:
                conn = create_product_connection()
                if conn:
                    with conn.cursor() as cursor:
                        query = "SELECT 产品型式 FROM 产品设计活动表 WHERE 产品ID = %s"
                        cursor.execute(query, (self.productID,))
                        result = cursor.fetchone()

                        if result and "产品型式" in result:
                            product_type_str = (
                                result["产品型式"].strip().upper()
                            )  # 标准化处理并保存
                            self.heat_exchanger = product_type_str

                            # 根据产品型式判断热交换器类型
                            if product_type_str in ["AEU", "BEU", "AKU", "BKU"]:
                                he_type = "2"  # U型管式
                            elif product_type_str in ["NEN", "BEM", "AEM", "NEN(Head)"]:
                                he_type = "1"  # 固定管板式
                            elif product_type_str in ["AES", "BES"]:
                                he_type = "0"  # 浮头式
            except pymysql.MySQLError as e:
                print(f"数据库查询产品型式失败: {e}")
            finally:
                if conn and conn.open:
                    conn.close()

        input_json["LB_HEType"] = he_type
        # 4.1 为平行，传"2"
        # 4.2，6.2为double，传"0"
        # 4.3,6.1为H，传"1"

        LB_ClapboardType = "0"
        if self.tube_pass_form_value == "4.1":
            LB_ClapboardType = "2"
        elif self.tube_pass_form_value == "4.2" or self.tube_pass_form_value == "6.2":
            LB_ClapboardType = "0"
        else:
            LB_ClapboardType = "1"
        input_json["LB_ClapboardType"] = LB_ClapboardType
        if input_json["LB_TubePassCount"] == "2":
            input_json["LB_SNH"] = "0"
        if self.tube_pass_form_value == "4.1":
            input_json["LB_SNH"] = "0"

        param_mapping2 = {
            "LB_IsRangeCenter": "换热管布置方式",
            "LB_BPBThick": "旁路挡板厚度",
            "LB_Tubeform": "管程分程形式",
            "LB_SlipWayHeight": "滑道高度",
            "LB_TieRodD": "拉杆直径",
            "LB_DN": "公称直径 DN",
            "LB_TubePassCount": "管程程数",
            "Shell_NumberOfPasses": "壳程程数",
            "LB_Di": "壳体内直径 Dis",
            "LB_DL": "布管限定圆 DL",
            # "LB_TotalTubesCountNeed": "换热管孔需求数量",
            "LB_TubeD": "换热管外径 do",
            "LB_TubeThick": "换热管壁厚 δ",
            "LB_RangeType": "换热管排列方式",
            "LB_TubeLong": "换热管公称长度 LN",
            "LB_S": "换热管中心距 S",
            "LB_BaffleDirection": "折流板切口方向",
            "LB_BafflePerStr": "折流板要求切口率",
            "LB_BaffleToODistance": "切口距垂直中心线间距",
            "BaffleSpacing": "折流/支持板间距",
            "LB_BaffleOD": "折流/支持板外径",
            "LB_SN": "分程隔板两侧相邻管中心距（竖直）",
            "LB_SNH": "分程隔板两侧相邻管中心距（水平）",
            "LB_W": "隔条位置尺寸 W",
            "LB_SlipWayThick": "滑道厚度",
            "LB_SlipWayAngle": "滑道与竖直中心线夹角",
            "LB_BaffleThick": "防冲板厚度",
            "LB_BaffleA": "防冲板折边角度",
            "LB_BafflePosition": "与圆筒连接防冲板方位",
            "LB_BaffleW": "与圆筒连接防冲板宽度",
            "LB_BaffleDis": "与圆筒连接防冲板至圆筒内壁最大距离",
            "LB_ClapboardType": "分程隔板放置型式",
            "LB_HEType": "热交换器类型",
        }

        defaults = {}
        conn = None
        try:
            conn = create_component_connection()
            if conn:
                with conn.cursor() as cursor:
                    if self.heat_exchanger in ["AEU", "BEU", "AKU", "BKU"]:
                        cursor.execute(
                            "SELECT 参数名, 参数值 FROM 布管参数默认表_U型管"
                        )
                        rows = cursor.fetchall()
                        for row in rows:
                            param_name = row["参数名"].strip()
                            param_value = row["参数值"]
                            defaults[param_name] = param_value
                    elif self.heat_exchanger in ["AES", "BES"]:
                        cursor.execute(
                            "SELECT 参数名, 参数值 FROM 布管参数默认表_浮头式"
                        )
                        rows = cursor.fetchall()
                        for row in rows:
                            param_name = row["参数名"].strip()
                            param_value = row["参数值"]
                            defaults[param_name] = param_value
                    else:
                        cursor.execute(
                            "SELECT 参数名, 参数值 FROM 布管参数默认表_浮头式"
                        )
                        rows = cursor.fetchall()
                        for row in rows:
                            param_name = row["参数名"].strip()
                            param_value = row["参数值"]
                            defaults[param_name] = param_value
        except pymysql.MySQLError as e:
            print(f"查询布管默认参数表失败: {e}")
        finally:
            if conn and conn.open:
                conn.close()

        for eng_key, cn_key in param_mapping2.items():
            if eng_key not in input_json or input_json[eng_key] in [None, ""]:
                if cn_key in defaults:
                    input_json[eng_key] = defaults[cn_key]
        input_json["LB_TotalTubesCountNeed"] = 10000

        self.input_json = input_json
        print(self.input_json)
        self.save_layout_input(product_id, self.input_json)

        # 4. 执行布管计算
        try:
            json_str = run_layout_tube_calculate(
                json.dumps(input_json, indent=2, ensure_ascii=False)
            )
            self.output_data = json_str
            # print(self.output_data)
            self.update_pipe_parameters()

            # 打印接口返回(output_data)里的 S（兼容不同字段名）
            try:
                _out = json.loads(json_str) if isinstance(json_str, str) else json_str
                if isinstance(_out, dict):
                    _s_val = _out.get("S", None)
                    if _s_val in (None, ""):
                        _s_val = _out.get("LB_S", None)
                    print(f"[output_data] S = {_s_val}")
            except Exception as _e_print_s:
                print(f"[output_data] 解析并打印S失败: {_e_print_s}")

            # 关键：接口返回的 json 可能缺少 parse_heat_exchanger_json() 需要的 DNs/DLs 结构。
            # 从界面参数表补齐，再用“补全后的 json”去解析绘图。
            json_str_for_parse = json_str
            try:
                output_dict = json.loads(json_str) if isinstance(json_str, str) else json_str
                if isinstance(output_dict, dict):
                    # parse_heat_exchanger_json 期望：
                    #   data["DNs"]["R"] -> 大圆外半径依据
                    #   data["DLs"]["R"] -> 大圆内半径依据
                    if "DNs" not in output_dict:
                        if DN is not None:
                            output_dict["DNs"] = {"R": float(DN)}
                        elif "BaffleOD" in output_dict:
                            # 兜底：接口有外径字段时，尽量让 parse 能成功
                            output_dict["DNs"] = {"R": float(output_dict["BaffleOD"])}
                    # 限定圆半径：以布管前本程序算出的 DL 为准，避免接口返回的 DLs/DL 与参数表不一致
                    if DL is not None:
                        output_dict["DLs"] = {"R": float(DL)}
                    elif "DLs" not in output_dict and "DL" in output_dict:
                        output_dict["DLs"] = {"R": float(output_dict["DL"])}
                    json_str_for_parse = json.dumps(
                        output_dict, indent=None, ensure_ascii=False
                    )
            except Exception:
                # 补齐失败则退回原 json_str；让上层异常处理逻辑继续工作
                json_str_for_parse = json_str

            result = parse_heat_exchanger_json(json_str_for_parse)
            self.save_layout_result(product_id, result)
            # 处理计算结果
            target_list = []
            for tube_param in result["raw"]["TubesParam"]:
                for item in tube_param["ScriptItem"]:
                    # 检查R值是否存在
                    r_value = item.get("R", None)
                    if r_value is None or r_value == "":
                        # 如果R值为空，尝试设置默认值或跳过
                        r_value = 0.0  # 设置默认值为0

                    flat_dict = {
                        "X": item["CenterPt"]["X"],
                        "Y": item["CenterPt"]["Y"],
                        "R": r_value,
                    }
                    target_list.append(flat_dict)

            self.target_list = target_list
            self.global_centers = result["centers"]
            centers = self.global_centers

            # 计算非布管区域
            current_centers = none_tube_centers(
                height_0_180, height_90_270, Di, do, centers
            )
            # 给现有圆心赋值
            self.current_centers = current_centers
            self.current_centers_lagan = current_centers
            self._sync_current_centers_lagan()

            # 更新管数量和绘制布局（确保小圆绘制在最上层）
            self.draw_layout(DN, Di, DL, do, result["centers"])

            # 重新创建场景并连接中心，确保层级正确
            if self.create_scene():
                self.connect_center(self.scene, self.current_centers, self.small_D)

            # 重新计算并绘制非布管区域和挡板
            self.global_centers = result["centers"]
            centers = self.global_centers
            self.none_tube(height_0_180, height_90_270, Di, do, centers)
            # self.draw_baffle_plates()

            self.ensure_main_axes(self.graphics_scene, force=True)

            # 强制刷新场景
            self.graphics_scene.update()
            QApplication.processEvents()
            tube_pass = self.get_tube_pass_count()

            self.update_SN()
            (
                self.full_sorted_current_centers_up,
                self.full_sorted_current_centers_down,
            ) = self.group_centers_by_y(self.global_centers)
            self.update_tube_nums()

            self.update_cross_pipe_button_state(product_type_str)
            self.update_total_lagan_count()

            return result

        except Exception as e:
            print(f"布管计算失败: {e}")
            return None

    # 该方法只调用接口，主要是为了看W返回值
    def calculate_piping(self):
        self.left_data_pd = []

        self._commit_param_table_open_editor()

        # 布管前保险：管箱内直径 Dit 与壳体内直径 Dis 一致
        try:
            self._sync_dis_dit_peer_from_source("壳体内直径 Dis")
        except Exception as _dit_guard_e:
            print(f"[calculate_piping] Dis→Dit 同步: {_dit_guard_e}")

        # 1. 读取参数
        DL = None
        do = None
        height_0_180 = None
        height_90_270 = None
        DN = None
        Di = None
        table = self.param_table

        for row in range(table.rowCount()):
            param_name = table.item(row, 1).text() if table.item(row, 1) else ""
            param_value = table.cellWidget(row, 2)

            if param_value and isinstance(param_value, QComboBox):
                param_value = param_value.currentText()
            else:
                item = table.item(row, 2)
                param_value = item.text() if item else ""

            self.left_data_pd.append({"参数名": param_name, "参数值": param_value})

            # 提取关键参数
            if param_name == "壳体内直径 Dis":
                Di = float(param_value) if param_value else None
            elif param_name == "公称直径 DN":
                DN = float(param_value) if param_value else None
            elif param_name == "换热管外径 do":
                do = float(param_value) if param_value else None
                self.r = float(do / 2) if do else 0
            elif param_name == "非布管区域弦高（0°/180°）":
                height_0_180 = float(param_value) if param_value else 0
            elif param_name == "非布管区域弦高（90°/270°）":
                height_90_270 = float(param_value) if param_value else 0
            elif param_name == "布管限定圆 DL":
                DL = float(param_value) if param_value else None

        # 参数验证
        if Di is None or do is None:
            QMessageBox.warning(
                self, "提示", "请先输入壳体内直径 Dis 和换热管外径 do 两个参数。"
            )
            return None

        # 获取换热器型号
        heat_exchanger_type = (
            self.heat_exchanger if hasattr(self, "heat_exchanger") else ""
        )
        if not heat_exchanger_type and self.productID:

            conn = None
            try:
                conn = create_product_connection()
                if conn:
                    with conn.cursor() as cursor:
                        query = "SELECT 产品型式 FROM 产品设计活动表 WHERE 产品ID = %s"
                        cursor.execute(query, (self.productID,))
                        result = cursor.fetchone()
                        if result and "产品型式" in result:
                            heat_exchanger_type = result["产品型式"].strip().upper()
                            self.heat_exchanger = heat_exchanger_type
            except pymysql.MySQLError as e:
                print(f"数据库查询产品型式失败: {e}")
            finally:
                if conn and conn.open:
                    conn.close()

        try:
            if (
                    Di is not None
                    and do is not None
                    and DL is not None
                    and float(DL) > float(Di)
            ):
                self._suppress_open_s_dl_autoupdate = False
                self.update_tube_layout_circle_dl()
        except Exception as _dl_sync_e:
            print(f"[calculate_piping] update_tube_layout_circle_dl: {_dl_sync_e}")

        dl_text_after = None
        for row in range(table.rowCount()):
            pname = table.item(row, 1).text() if table.item(row, 1) else ""
            if pname != "布管限定圆 DL":
                continue
            pv = table.cellWidget(row, 2)
            if pv and isinstance(pv, QComboBox):
                dl_text_after = pv.currentText().strip()
            else:
                it = table.item(row, 2)
                dl_text_after = (it.text().strip() if it else "") or None
            if dl_text_after:
                try:
                    DL = float(dl_text_after)
                except (ValueError, TypeError):
                    pass
            break
        for rec in self.left_data_pd:
            if isinstance(rec, dict) and rec.get("参数名") == "布管限定圆 DL":
                if dl_text_after:
                    rec["参数值"] = dl_text_after
                break

        # 转换为DataFrame
        self.left_data_pd = pd.DataFrame(self.left_data_pd)

        # 2. 构造JSON映射
        param_mapping = {
            "换热管布置方式": (
                "LB_IsRangeCenter",
                {"对中": "0", "跨中": "1", "任意": "2"},
            ),
            "旁路挡板厚度": ("LB_BPBThick", None),
            "分程隔板放置型式": ("LB_ClapboardType", None),
            "管程分程形式": ("LB_Tubeform", None),
            "滑道高度": ("LB_SlipWayHeight", None),
            "拉杆直径": ("LB_TieRodD", None),
            "管程程数": ("LB_TubePassCount", None),
            "壳程程数": ("Shell_NumberOfPasses", None),
            "公称直径 DN": ("LB_DN", None),
            "壳体内直径 Dis": ("LB_Di", None),
            "布管限定圆 DL": ("LB_DL", None),
            "换热管孔需求数量": ("LB_TotalTubesCountNeed", None),
            "换热管外径 do": ("LB_TubeD", None),
            "换热管壁厚 δ": ("LB_TubeThick", None),
            "换热管排列方式": (
                "LB_RangeType",
                {
                    "正三角形": "1",
                    "转角正三角形": "0",
                    "正方形": "2",
                    "转角正方形": "3",
                },
            ),
            "换热管公称长度 LN": ("LB_TubeLong", None),
            "换热管中心距 S": ("LB_S", None),
            "折流板切口方向": (
                "LB_BaffleDirection",
                {"水平上下": "1", "垂直左右": "2"},
            ),
            "折流板要求切口率": ("LB_BafflePerStr", None),
            "切口距垂直中心线间距": ("LB_BaffleToODistance", None),
            "折流/支持板间距": ("BaffleSpacing", None),
            "折流/支持板外径": ("LB_BaffleOD", None),
            "分程隔板两侧相邻管中心距（竖直）": ("LB_SN", None),
            "分程隔板两侧相邻管中心距（水平）": ("LB_SNH", None),
            "隔条位置尺寸 W": ("LB_W", None),
            "滑道厚度": ("LB_SlipWayThick", None),
            "滑道与竖直中心线夹角": ("LB_SlipWayAngle", None),
            "防冲板厚度": ("LB_BaffleThick", None),
            "防冲板折边角度": ("LB_BaffleA", None),
            "与圆筒连接防冲板方位": ("LB_BafflePosition", None),
            "与圆筒连接防冲板宽度": ("LB_BaffleW", None),
            "与圆筒连接防冲板至圆筒内壁最大距离": ("LB_BaffleDis", None),
            "热交换器类型": (
                "LB_HEType",
                {
                    "未选择": "2",
                    "浮头式热交换器": "0",
                    "固定管板式热交换器": "1",
                    "U型管式热交换器": "2",
                },
            ),
        }

        input_json = {}
        for _, row in self.left_data_pd.iterrows():
            param_name = row["参数名"]
            param_value = str(row["参数值"]).strip()
            if param_name == "中间挡板厚度":
                self.block_thickness = param_value

            if param_name in param_mapping:
                json_key, value_map = param_mapping[param_name]

                if json_key == "SlipWays":
                    try:
                        input_json[json_key] = json.loads(param_value)
                    except Exception as e:
                        print("滑道坐标 JSON 格式错误，无法解析：", param_value)
                        input_json[json_key] = []
                elif value_map:
                    input_json[json_key] = value_map.get(param_value, "0")
                else:
                    # 特殊处理隔条位置尺寸W参数：当值为"程序推荐"时传递0
                    if param_name == "隔条位置尺寸 W" and param_value == "程序推荐":
                        input_json[json_key] = "0"
                    else:
                        input_json[json_key] = param_value

        # 请求前按 do+排列方式映射修正 LB_S（仅在用户未手动覆盖 S 时），避免异步联动时带入历史值
        try:
            if getattr(self, "_user_override_tube_center_distance", False):
                raise RuntimeError("skip_force_S_due_to_user_override")
            global _TUBE_CENTER_DISTANCE_MAP_CACHE
            if _TUBE_CENTER_DISTANCE_MAP_CACHE is None:
                _TUBE_CENTER_DISTANCE_MAP_CACHE = {}
                config_value = self.get_config_value("2.10.1.1")
                if config_value:
                    try:
                        config_rows = (
                            ast.literal_eval(config_value)
                            if isinstance(config_value, str)
                            else config_value
                        )
                        do_row_cfg = None
                        tri_s_row_cfg = None
                        sq_s_row_cfg = None
                        for r_cfg in (config_rows or []):
                            if not r_cfg or len(r_cfg) < 2:
                                continue
                            name_cfg = str(r_cfg[0]).strip()
                            if name_cfg == "换热管外径d":
                                do_row_cfg = r_cfg
                            elif name_cfg == "换热管中心距S（三角形排列）":
                                tri_s_row_cfg = r_cfg
                            elif name_cfg == "换热管中心距S（正方形排列）":
                                sq_s_row_cfg = r_cfg
                        if do_row_cfg and tri_s_row_cfg and sq_s_row_cfg:
                            do_values_cfg = [
                                float(x) for x in do_row_cfg[1:] if str(x).strip() != ""
                            ]
                            tri_values_cfg = [
                                float(x) for x in tri_s_row_cfg[1:] if str(x).strip() != ""
                            ]
                            sq_values_cfg = [
                                float(x) for x in sq_s_row_cfg[1:] if str(x).strip() != ""
                            ]
                            for i_cfg, d_cfg in enumerate(do_values_cfg):
                                if i_cfg < len(tri_values_cfg):
                                    _TUBE_CENTER_DISTANCE_MAP_CACHE[(d_cfg, "三角形排列")] = tri_values_cfg[i_cfg]
                                if i_cfg < len(sq_values_cfg):
                                    _TUBE_CENTER_DISTANCE_MAP_CACHE[(d_cfg, "正方形排列")] = sq_values_cfg[i_cfg]
                    except Exception as _s_cfg_e:
                        print(f"[calculate_piping] 解析S映射配置失败: {_s_cfg_e}")

            do_for_s = None
            try:
                do_for_s = float(str(input_json.get("LB_TubeD", "")).strip())
            except Exception:
                do_for_s = None
            range_code = str(input_json.get("LB_RangeType", "")).strip()
            range_type_for_s = None
            if range_code in ("0", "1"):
                range_type_for_s = "三角形排列"
            elif range_code in ("2", "3"):
                range_type_for_s = "正方形排列"

            if do_for_s is not None and range_type_for_s:
                mapped_s = _TUBE_CENTER_DISTANCE_MAP_CACHE.get((do_for_s, range_type_for_s))
                if mapped_s is not None:
                    mapped_s_text = f"{float(mapped_s):.1f}"
                    input_json["LB_S"] = mapped_s_text
                    print(
                        f"[calculate_piping] 强制修正LB_S: do={do_for_s}, range={range_code}({range_type_for_s}) -> {mapped_s_text}"
                    )
        except Exception as _force_s_e:
            if str(_force_s_e) != "skip_force_S_due_to_user_override":
                print(f"[calculate_piping] 强制修正LB_S失败: {_force_s_e}")

        # 确保使用计算后的DL值
        input_json["LB_DL"] = f"{DL: .1f}"
        input_json["LB_Di"] = f"{Di: .1f}" if Di else ""

        # 处理隔条位置尺寸W：如果映射关系中没有找到，判断是用户修改还是程序更新
        if "LB_W" in input_json:
            try:
                # 从input_json中读取所需参数
                dn_value = (
                    float(input_json.get("LB_DN", 0))
                    if input_json.get("LB_DN")
                    else None
                )
                do_value = (
                    float(input_json.get("LB_TubeD", 0))
                    if input_json.get("LB_TubeD")
                    else None
                )
                tube_pass_form = (
                    self.tube_pass_form_value
                    if hasattr(self, "tube_pass_form_value")
                    else None
                )

                # 如果参数齐全，尝试从映射关系查找
                if dn_value and do_value and tube_pass_form:
                    from modules.buguan.buguan_ziyong.divider_position_mapping import (
                        get_divider_position_w,
                    )

                    w_value = get_divider_position_w(dn_value, tube_pass_form, do_value)

                    # 如果映射关系中没有找到，判断是用户修改还是程序更新
                    if w_value is None:
                        # 查找隔条位置尺寸W在表格中的行号
                        w_row = -1
                        for row in range(self.param_table.rowCount()):
                            param_name_item = self.param_table.item(row, 1)
                            if (
                                    param_name_item
                                    and param_name_item.text().strip() == "隔条位置尺寸 W"
                            ):
                                w_row = row
                                break

                        # 获取当前W值
                        current_w_value = None
                        if w_row != -1:
                            w_widget = self.param_table.cellWidget(w_row, 2)
                            if isinstance(w_widget, QComboBox):
                                current_w_value = w_widget.currentText().strip()
                            else:
                                w_item = self.param_table.item(w_row, 2)
                                current_w_value = (
                                    w_item.text().strip() if w_item else None
                                )

                        # 判断是否是用户修改的
                        is_user_modified = False
                        if w_row != -1:
                            # 方法1：检查是否在modified_rows中
                            if (
                                    hasattr(self, "modified_rows")
                                    and w_row in self.modified_rows
                            ):
                                is_user_modified = True
                            # 方法2：检查当前值是否和原始值不同
                            elif hasattr(self, "original_param_values"):
                                original_value = self.original_param_values.get(
                                    (w_row, 2), ""
                                )
                                if (
                                        current_w_value
                                        and current_w_value != original_value
                                ):
                                    is_user_modified = True

                        if is_user_modified:
                            # 用户修改的，使用当前W值
                            if current_w_value:
                                try:
                                    # 如果是数字，转换为字符串；如果是"程序推荐"等，保持原样
                                    float(current_w_value)  # 检查是否为数字
                                    input_json["LB_W"] = current_w_value
                                except (ValueError, TypeError):
                                    # 如果不是数字（如"程序推荐"），传0
                                    input_json["LB_W"] = "0"
                                print(
                                    f"映射关系中未找到W值，但当前W值({current_w_value})是用户修改的，LB_W使用当前值：{input_json['LB_W']}"
                                )
                            else:
                                input_json["LB_W"] = "0"
                                print(f"映射关系中未找到W值，当前W值为空，LB_W设置为0")
                        else:
                            # 程序更新的，设置为0
                            input_json["LB_W"] = "0"
                            print(
                                f"映射关系中未找到W值（DN={dn_value}, 分程形式={tube_pass_form}, 外径={do_value}），且当前W值是程序更新的，LB_W设置为0"
                            )
                    else:
                        # 如果找到了，维持原逻辑（不修改）
                        print(f"映射关系中找到W值：{w_value}，维持原逻辑")
                else:
                    # 参数不齐全，无法查找映射关系
                    # 同样需要判断是用户修改还是程序更新
                    w_row = -1
                    for row in range(self.param_table.rowCount()):
                        param_name_item = self.param_table.item(row, 1)
                        if (
                                param_name_item
                                and param_name_item.text().strip() == "隔条位置尺寸 W"
                        ):
                            w_row = row
                            break

                    current_w_value = None
                    if w_row != -1:
                        w_widget = self.param_table.cellWidget(w_row, 2)
                        if isinstance(w_widget, QComboBox):
                            current_w_value = w_widget.currentText().strip()
                        else:
                            w_item = self.param_table.item(w_row, 2)
                            current_w_value = w_item.text().strip() if w_item else None

                    is_user_modified = False
                    if w_row != -1:
                        if (
                                hasattr(self, "modified_rows")
                                and w_row in self.modified_rows
                        ):
                            is_user_modified = True
                        elif hasattr(self, "original_param_values"):
                            original_value = self.original_param_values.get(
                                (w_row, 2), ""
                            )
                            if current_w_value and current_w_value != original_value:
                                is_user_modified = True

                    if is_user_modified and current_w_value:
                        try:
                            float(current_w_value)
                            input_json["LB_W"] = current_w_value
                        except (ValueError, TypeError):
                            input_json["LB_W"] = "0"
                        print(
                            f"参数不齐全，但当前W值({current_w_value})是用户修改的，LB_W使用当前值：{input_json['LB_W']}"
                        )
                    else:
                        input_json["LB_W"] = "0"
                        print(
                            f"参数不齐全（DN={dn_value}, do={do_value}, 分程形式={tube_pass_form}），且当前W值是程序更新的，LB_W设置为0"
                        )
            except Exception as e:
                print(f"处理LB_W时发生错误：{e}，LB_W设置为0")
                input_json["LB_W"] = "0"

