    def resizeEvent(self, event):
        """窗口大小变化时的自适应调整"""
        super().resizeEvent(event)

        # 自动调整表格列宽（仅左侧 param_table）
        if hasattr(self, "param_table"):
            table_width = self.param_table.viewport().width()
            if table_width > 0:
                col0_width = 80  # 序号
                col3_width = 80  # 单位
                remaining = max(0, table_width - col0_width - col3_width)
                # 缩小“参数名”列宽占比，让“参数值”列更宽一些
                col1_width = int(remaining * 0.55)  # 参数名
                col2_width = remaining - col1_width  # 参数值

                self.param_table.setColumnWidth(0, col0_width)
                self.param_table.setColumnWidth(1, col1_width)
                self.param_table.setColumnWidth(2, col2_width)
                self.param_table.setColumnWidth(3, col3_width)

        # 保持你原来的右侧表策略不变
        if hasattr(self, "hole_distribution_table"):
            self.hole_distribution_table.horizontalHeader().setSectionResizeMode(
                QHeaderView.Stretch
            )

        # 调整图形视图
        if hasattr(self, "graphics_view") and hasattr(self, "graphics_scene"):
            self.graphics_view.fitInView(
                self.graphics_scene.sceneRect(), Qt.KeepAspectRatio
            )
            
        # 调整工具栏图片的大小
        if hasattr(self, "toolbar_label"):
            window_width = self.width()
            max_width = int(window_width * 0.8)
            self.toolbar_label.setMaximumWidth(max_width)

        # 根据窗口状态动态调整工具栏按钮布局
        if (
            hasattr(self, "toolbar_layout")
            and hasattr(self, "toolbar_row1_layout")
            and hasattr(self, "toolbar_row2_layout")
        ):
            self.update_toolbar_layout_mode()
    
    # 简单的方案：移除原来的退出全屏恢复逻辑，让列宽始终自适应
    # 这样无论在什么状态下，列宽都会根据当前窗口大小重新计算
    def update_toolbar_layout_mode(self):
        """根据窗口状态（全屏 / 最大化）动态调整工具栏布局。"""
        # 如果还没有创建工具栏按钮，直接返回
        if not hasattr(self, "toolbar_buttons"):
            return

        # 判断是否最大化
        is_maximized = bool(self.windowState() & Qt.WindowMaximized)
        # 非全屏且非最大化时使用两行布局，其余情况使用一行布局
        use_two_rows = (not getattr(self, "is_fullscreen", False)) and (
            not is_maximized
        )

        # 先清空两行布局中的所有项（包括按钮和伸缩项）
        for layout in (self.toolbar_row1_layout, self.toolbar_row2_layout):
            while layout.count():
                item = layout.takeAt(0)
                # 对于包含控件的项，不需要额外处理，控件稍后会重新加入到布局中
                widget = item.widget()
                if widget is not None:
                    widget.setVisible(True)

        if use_two_rows:
            # 第一行 7 个按钮
            for btn in self.toolbar_buttons[:7]:
                self.toolbar_row1_layout.addWidget(btn)

            # 第二行 4 个按钮：前三个在左侧，最后一个（删除）紧贴右侧
            row2_buttons = self.toolbar_buttons[7:]
            if row2_buttons:
                # 前 n-1 个按钮依次添加在左侧
                for btn in row2_buttons[:-1]:
                    self.toolbar_row2_layout.addWidget(btn)
                # 伸缩项占据中间空白，把最后一个按钮推到最右
                self.toolbar_row2_layout.addStretch()
                # 最后一个按钮（删除）紧贴右侧
                self.toolbar_row2_layout.addWidget(row2_buttons[-1])

            self.toolbar_row1_layout.addStretch()
        else:
            # 全屏或最大化：所有按钮放在第一行，第二行为空
            for btn in self.toolbar_buttons:
                self.toolbar_row1_layout.addWidget(btn)

            self.toolbar_row1_layout.addStretch()
            self.toolbar_row2_layout.addStretch()

    def _apply_bold_table_header(self, table, point_size=10):
        """表头文字加粗（样式表 + QFont 双保险）。"""
        if table is None:
            return
        try:
            from PyQt5.QtGui import QFont

            header_font = QFont()
            header_font.setBold(True)
            header_font.setWeight(QFont.Bold)
            header_font.setPointSize(point_size)
            hdr = table.horizontalHeader()
            hdr.setFont(header_font)
            hdr.setDefaultAlignment(Qt.AlignCenter)
            for col in range(table.columnCount()):
                item = table.horizontalHeaderItem(col)
                if item is not None:
                    item.setFont(header_font)
                    item.setTextAlignment(Qt.AlignCenter)
        except Exception:
            pass

    def _param_combo_extra_stylesheet(self):
        """已由 get_param_combo_stylesheet 统一提供。"""
        return ""

    def _apply_param_combo_widget_style(self, combo, disabled=False):
        """统一参数表下拉框样式与调色板，避免行选中后文字变白。"""
        apply_param_combo_widget_style(combo, disabled=disabled)

    def _param_value_widget_stylesheet(self, disabled=False):
        """参数值列内嵌 QComboBox 样式（与元件定义下拉框一致）。"""
        return get_param_combo_stylesheet(disabled=disabled)

    def _refresh_param_table_value_widgets_style(self):
        """为参数值列已嵌入的下拉框应用圆角输入框样式。"""
        if not hasattr(self, "param_table") or self.param_table is None:
            return
        try:
            for row in range(self.param_table.rowCount()):
                widget = self.param_table.cellWidget(row, 2)
                if isinstance(widget, QComboBox):
                    self._apply_param_combo_widget_style(
                        widget, disabled=not widget.isEnabled()
                    )
        except Exception:
            pass

    def _apply_param_table_edit_triggers(self):
        """普通数值格双击编辑；下拉行由 delegate.editorEvent 单击整格打开。"""
        if not hasattr(self, "param_table") or self.param_table is None:
            return
        try:
            self.param_table.setEditTriggers(
                QAbstractItemView.DoubleClicked | QAbstractItemView.EditKeyPressed
            )
        except Exception:
            pass

    def _apply_param_table_style(self):
        """左侧布管参数表样式（对照示例：浅灰表头、网格线、交替行）。"""
        if not hasattr(self, "param_table") or self.param_table is None:
            return
        try:
            self._apply_param_table_edit_triggers()
            self.param_table.setAlternatingRowColors(True)
            self.param_table.setShowGrid(True)
            try:
                self.param_table.verticalHeader().setDefaultSectionSize(34)
            except Exception:
                pass
            if not getattr(self, "_param_value_cell_delegate", None):
                self._param_value_cell_delegate = _ParamValueCellDelegate(
                    owner=self, parent=self.param_table
                )
            self.param_table.setItemDelegateForColumn(
                2, self._param_value_cell_delegate
            )
            self.param_table.setStyleSheet(PARAM_TABLE_STYLE_SHEET)
            self._apply_bold_table_header(self.param_table, point_size=10)
            self._refresh_param_table_value_widgets_style()
        except Exception:
            pass

    def _buguan_tube_pen(self):
        pen = QPen(_BUGUAN_TUBE_OUTLINE)
        pen.setWidth(_BUGUAN_TUBE_LINE_WIDTH)
        pen.setCapStyle(Qt.RoundCap)
        return pen

    def _buguan_tube_brush(self):
        return QBrush(Qt.NoBrush)

    def _add_annulus_fill(self, scene, r_outer, r_inner, color, z=2):
        """两圆之间的环形区域填充（r_outer > r_inner）。"""
        if r_outer <= r_inner or r_outer <= 0:
            return
        path = QPainterPath()
        path.addEllipse(-r_outer, -r_outer, 2 * r_outer, 2 * r_outer)
        hole = QPainterPath()
        hole.addEllipse(-r_inner, -r_inner, 2 * r_inner, 2 * r_inner)
        path = path.subtracted(hole)
        item = QGraphicsPathItem(path)
        item.setBrush(QBrush(color))
        item.setPen(QPen(Qt.NoPen))
        item.setZValue(z)
        scene.addItem(item)

    def _draw_shell_circles_and_ring(
            self, scene, R_wai, R_Di, R_nei, z_outline=100, z_ring=2
    ):
        """壳体：最大与次大半径之间绿环 + 三个大圆描边。"""
        r_wai = float(R_wai) if R_wai else 0.0
        r_di = float(R_Di) if R_Di else 0.0
        r_nei = float(R_nei) if R_nei else 0.0
        radii = sorted([r for r in (r_wai, r_di, r_nei) if r > 0], reverse=True)
        if len(radii) >= 2:
            self._add_annulus_fill(
                scene, radii[0], radii[1], _BUGUAN_SHELL_RING_GREEN, z=z_ring
            )
        pen_gray = QPen(Qt.gray)
        pen_gray.setWidth(2)
        pen_black = QPen(Qt.black)
        pen_black.setWidth(2)
        brush_no = QBrush(Qt.NoBrush)
        if r_nei > 0:
            c = scene.addEllipse(-r_nei, -r_nei, 2 * r_nei, 2 * r_nei, pen_gray, brush_no)
            c.setZValue(z_outline)
        if r_di > 0:
            c = scene.addEllipse(-r_di, -r_di, 2 * r_di, 2 * r_di, pen_black, brush_no)
            c.setZValue(z_outline)
        if r_wai > 0:
            c = scene.addEllipse(-r_wai, -r_wai, 2 * r_wai, 2 * r_wai, pen_black, brush_no)
            c.setZValue(z_outline)

    def _draw_tube_circles(self, scene, centers, r, z=1):
        """绘制换热管小圆（空心、略亮的蓝色描边）。"""
        pen_t = self._buguan_tube_pen()
        brush_t = self._buguan_tube_brush()
        for x, y in centers or []:
            tube = scene.addEllipse(x - r, y - r, 2 * r, 2 * r, pen_t, brush_t)
            tube.setZValue(z)

    def _axis_reference_radius(self):
        """主坐标轴长度：取各壳体半径最大值，避免 DN 为空时轴消失。"""
        r_wai = float(getattr(self, "R_wai", 0) or 0)
        r_di = float(getattr(self, "R_Di", 0) or 0)
        r_nei = float(getattr(self, "R_nei", 0) or 0)
        return max(r_wai, r_di, r_nei, 1.0)

    def _is_axis_scene_item(self, item):
        try:
            return item.data(Qt.UserRole) in (
                _BUGUAN_AXIS_ITEM_ROLE,
                _BUGUAN_AXIS_LABEL_ROLE,
            )
        except Exception:
            return False

    def _clear_scene_preserve_axes(self, scene):
        """清空布管图元，保留主坐标轴（禁止 scene.clear 删掉坐标轴）。"""
        for item in list(scene.items()):
            if self._is_axis_scene_item(item):
                continue
            scene.removeItem(item)

    def _remove_main_axes(self, scene):
        for item in list(scene.items()):
            if self._is_axis_scene_item(item):
                scene.removeItem(item)

    def _count_main_axis_parts(self, scene):
        """返回 (轴线数, 箭头数)。"""
        line_n = arrow_n = 0
        for item in scene.items():
            if not self._is_axis_scene_item(item):
                continue
            if item.data(Qt.UserRole) != _BUGUAN_AXIS_ITEM_ROLE:
                continue
            if isinstance(item, QGraphicsLineItem):
                line_n += 1
            elif isinstance(item, QGraphicsPolygonItem):
                arrow_n += 1
        return line_n, arrow_n

    def _tag_axis_item(self, item, label=False):
        item.setData(
            Qt.UserRole,
            _BUGUAN_AXIS_LABEL_ROLE if label else _BUGUAN_AXIS_ITEM_ROLE,
        )
        item.setZValue(_BUGUAN_AXIS_Z)
        item.setFlag(QGraphicsItem.ItemStacksBehindParent, False)

    def _add_solid_arrow_head(self, scene, tip_x, tip_y, ux, uy, color, head=18, wing=9):
        """在尖端绘制实心三角箭头。"""
        px, py = -uy, ux
        base_x = tip_x - ux * head
        base_y = tip_y - uy * head
        poly = QPolygonF(
            [
                QPointF(tip_x, tip_y),
                QPointF(base_x + px * wing, base_y + py * wing),
                QPointF(base_x - px * wing, base_y - py * wing),
            ]
        )
        head_item = QGraphicsPolygonItem(poly)
        head_item.setBrush(QBrush(color))
        head_item.setPen(QPen(Qt.NoPen))
        self._tag_axis_item(head_item)
        scene.addItem(head_item)

    def draw_axes(self, scene: QGraphicsScene, R: float):
        from PyQt5.QtGui import QFont
        from PyQt5.QtWidgets import QGraphicsTextItem

        R = max(float(R or 0), self._axis_reference_radius(), 1.0)
        extension = R * 0.1
        total_length = R + extension
        arrow_head = 18
        wing = 9
        font = QFont("Arial", 12, QFont.Bold)

        pen_x = QPen(_BUGUAN_AXIS_X)
        pen_x.setWidth(4)
        pen_x.setCapStyle(Qt.RoundCap)
        x_axis_line = QGraphicsLineItem(-total_length, 0, total_length, 0)
        x_axis_line.setPen(pen_x)

        pen_y = QPen(_BUGUAN_AXIS_Y)
        pen_y.setWidth(4)
        pen_y.setCapStyle(Qt.RoundCap)
        y_axis_line = QGraphicsLineItem(0, -total_length, 0, total_length)
        y_axis_line.setPen(pen_y)

        geom_items = [x_axis_line, y_axis_line]
        for tip_x, tip_y, ux, uy, color in (
                (total_length + arrow_head, 0, 1, 0, _BUGUAN_AXIS_X),
                (-total_length - arrow_head, 0, -1, 0, _BUGUAN_AXIS_X),
                (0, -total_length - arrow_head, 0, -1, _BUGUAN_AXIS_Y),
                (0, total_length + arrow_head, 0, 1, _BUGUAN_AXIS_Y),
        ):
            px, py = -uy, ux
            base_x = tip_x - ux * arrow_head
            base_y = tip_y - uy * arrow_head
            poly = QPolygonF(
                [
                    QPointF(tip_x, tip_y),
                    QPointF(base_x + px * wing, base_y + py * wing),
                    QPointF(base_x - px * wing, base_y - py * wing),
                ]
            )
            head_item = QGraphicsPolygonItem(poly)
            head_item.setBrush(QBrush(color))
            head_item.setPen(QPen(Qt.NoPen))
            geom_items.append(head_item)

        label_items = []
        text_offset = 80
        texts = [
            ("0°", -10, -total_length - text_offset),
            ("90°", total_length + text_offset / 2, -30),
            ("180°", -20, total_length + 5),
            ("270°", -total_length - text_offset, -30),
        ]
        for label, x, y in texts:
            text_item = QGraphicsTextItem(label)
            text_item.setFont(font)
            text_item.setPos(x, y)
            text_item.setFlag(QGraphicsItem.ItemIgnoresTransformations)
            label_items.append(text_item)

        self._remove_main_axes(scene)
        for item in geom_items:
            self._tag_axis_item(item, label=False)
            scene.addItem(item)
        for item in label_items:
            self._tag_axis_item(item, label=True)
            scene.addItem(item)

    def ensure_main_axes(self, scene=None, force=False):
        """布管后校验主坐标轴；不完整或 force 时强制重绘并置顶。"""
        scene = scene or self.graphics_scene
        if scene is None:
            return
        line_n, arrow_n = self._count_main_axis_parts(scene)
        if force or line_n < 2 or arrow_n < 4:
            self.draw_axes(scene, self._axis_reference_radius())
        else:
            for item in scene.items():
                if self._is_axis_scene_item(item):
                    item.setZValue(_BUGUAN_AXIS_Z)
        if hasattr(self, "corner_axis_widget") and self.corner_axis_widget:
            self.corner_axis_widget.raise_()

    # TODO 圆心连线
    def connect_center(self, scene, centers: List[Tuple[float, float]], do: float):
        """
        根据换热管排列方式，连接相邻圆心
        """
        import math
        from PyQt5.QtGui import QPen, QColor
        from PyQt5.QtWidgets import QGraphicsLineItem, QGraphicsItem

        # 先清除已有的连线
        self.clear_connection_lines(scene)
        # 更新需求，所有圆心都要有连线，后续如有需求再修改这句
        centers = self.global_centers
        # 获取排列方式和中心距
        layout_type = None
        S = do  # 默认 fallback
        if hasattr(self, "left_data_pd"):
            df = self.left_data_pd
            # 获取排列方式
            res_type = df[df["参数名"] == "换热管排列方式"]
            if not res_type.empty:
                layout_type = res_type.iloc[0]["参数值"].strip()
            # 获取中心距 S
            res_s = df[df["参数名"] == "换热管中心距 S"]
            if not res_s.empty:
                try:
                    S = float(res_s.iloc[0]["参数值"])
                except:
                    pass

        # 网格索引设置
        grid_size = S * 1.2
        grid = dict()

        for idx, (x, y) in enumerate(centers):
            key = (round(x / grid_size), round(y / grid_size))
            grid.setdefault(key, []).append((idx, x, y))

        # 绘制准备
        pen = QPen(QColor(0, 0, 255))
        pen.setWidth(1)
        connected = set()

        # 遍历所有圆心找邻居
        for idx0, (x0, y0) in enumerate(centers):
            base_key = (round(x0 / grid_size), round(y0 / grid_size))
            candidates = []
            for dx in [-1, 0, 1]:
                for dy in [-1, 0, 1]:
                    key = (base_key[0] + dx, base_key[1] + dy)
                    if key in grid:
                        candidates.extend(grid[key])

            # 直接计算两个圆心之间的实际距离，判断是否在 S ± 1 范围内
            for idx1, x1, y1 in candidates:
                if idx0 == idx1:
                    continue
                # 计算实际距离
                actual_dist = math.hypot(x1 - x0, y1 - y0)
                # 判断是否在 S ± 1 范围内
                if S - 1 <= actual_dist <= S + 1:
                    key = tuple(sorted((idx0, idx1)))
                    if key not in connected:
                        connected.add(key)
                        # 创建连线
                        line = QGraphicsLineItem(x0, y0, x1, y1)
                        line.setPen(pen)
                        line.setZValue(3)  # 在绿环之上、大圆轮廓之下，保留圆心连线可见
                        scene.addItem(line)
                        # 如果有存储连线的列表，添加进去
                        if hasattr(self, "connection_lines"):
                            self.connection_lines.append(line)

    def draw_layout(
            self,
            big_D_wai,
            Di,
            big_D_nei: float,
            small_D: float,
            centers: List[Tuple[float, float]],
    ):
        #     """
        #     在 self.graphics_scene 上：
        #      - 画坐标轴
        #      - 画大圆（big_D_wai、Di、big_D_nei）
        #      - 画所有小圆
        #     """
        # 清空self.graphics_scene
        scene = self.graphics_scene

        self._clear_scene_preserve_axes(scene)
        # 计算大小半径
        self.R_wai = (big_D_wai or 0) / 2.0
        self.R_nei = (big_D_nei or 0) / 2.0
        self.R_Di = (Di or 0) / 2.0
        self.r = small_D / 2.0
        layout_r = max(self.R_wai, self.R_Di, self.R_nei, 1.0)
        # 设置坐标系：在原点上方多留空间、下方少留空间，避免 0° 位置贴到顶部工具栏
        padding = layout_r * 0.2
        base = layout_r + padding
        top = -(layout_r + padding * 1.5)
        height = 2 * base
        left = -base
        scene.setSceneRect(left, top, 2 * base, height)
        # 坐标轴（最高层级）、壳体绿环与大圆、换热管小圆
        self.draw_axes(scene, layout_r)
        self._draw_shell_circles_and_ring(scene, self.R_wai, self.R_Di, self.R_nei)
        self._draw_tube_circles(scene, centers, self.r, z=1)
        self.ensure_main_axes(scene, force=True)
        if hasattr(self, "corner_axis_widget") and self.corner_axis_widget:
            self.corner_axis_widget.raise_()
        self.graphics_view.fitInView(scene.sceneRect(), Qt.KeepAspectRatio)

    def can_place_lagan_without_intersect(self, selected_centers, lagan_length) -> bool:
        """
        判断以 selected_centers 中的绝对坐标为圆心、以 lagan_length 为直径的小圆，
        是否与折流/支持板外径对应的大圆相交（或发生相切视为不相交）。

        Args:
            selected_centers: 包含绝对坐标的列表/元组，如 [(x, y)]。
            lagan_length: 小圆的直径。

        Returns:
            bool: True 表示不会相交/相切（安全），False 表示会相交或无法判定。
        """
        # 基础校验
        if not selected_centers or lagan_length is None:
            return False

        # 提取首个有效坐标（绝对坐标）
        candidate_coord = None
        if isinstance(selected_centers, (list, tuple)):
            for item in selected_centers:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    try:
                        x_val = float(item[0])
                        y_val = float(item[1])
                        candidate_coord = (x_val, y_val)
                        break
                    except (TypeError, ValueError):
                        continue
        if candidate_coord is None:
            return False

        # 获取折流/支持板外径（作为大圆直径）
        try:
            baffle_od_raw = self.get_Baffle_OD()
            baffle_od = float(baffle_od_raw)
        except (TypeError, ValueError):
            return False
        if baffle_od <= 0:
            return False

        # 处理 lagan_length
        try:
            lagan_length = float(lagan_length)
        except (TypeError, ValueError):
            return False
        if lagan_length <= 0:
            return False

        # 计算半径、圆心距
        R = baffle_od / 2.0  # 大圆半径（折流/支持板外径的半径）
        r = lagan_length / 2.0  # 小圆半径（拉杆的半径）
        x0, y0 = candidate_coord
        distance = math.hypot(x0, y0)  # 拉杆圆心到原点的距离
        epsilon = 1e-9

        # 判断拉杆是否在折流/支持板外径内部（安全）
        # 拉杆在折流板内部的条件：拉杆的最外边缘（圆心距离 + 拉杆半径）不超过折流板半径
        # 即：distance + r <= R + epsilon

        # 情况1：拉杆完全在折流板内部（包含内切）=> 安全
        if distance + r <= R + epsilon:
            return True

        # 情况2：拉杆超出折流/支持板外径或与折流板相交 => 不安全
        # 如果 distance + r > R，说明拉杆至少有一部分超出折流/支持板外径
        return False

    from typing import List, Tuple

    # 绘制折流板
    def draw_baffle_plates(self):

        from PyQt5.QtGui import QPen, QColor
        import math

        if len(self.baffle_lines) != 0:
            self.clear_baffle_plates()
            self.baffle_lines = []

        _hx = str(getattr(self, "heat_exchanger", "") or "").strip().upper()
        if _hx in ("AKU", "BKU"):
            return

        # 获取折流板相关参数
        baffle_type = None  # 折流板类型
        cut_direction = None  # 折流板切口方向
        cut_rate = None  # 折流板要求切口率
        shell_inner_diameter = None  # 壳体内直径
        baffle_outer_diameter = None  # 折流/支持板外径
        a_distance = None  # A型板切口与中心线间距a
        b_distance = None  # B型板切口与中心线间距b

        # 遍历参数表格查找所需参数
        for row in range(self.param_table.rowCount()):
            param_name_item = self.param_table.item(row, 1)
            if not param_name_item:
                continue
            param_name = param_name_item.text()

            # 获取参数值（区分QComboBox和普通文本项）
            cell_widget = self.param_table.cellWidget(row, 2)
            if isinstance(cell_widget, QComboBox):
                param_value = cell_widget.currentText()
            else:
                value_item = self.param_table.item(row, 2)
                param_value = value_item.text() if value_item else ""

            # 记录参数值
            if param_name == "折流板类型":
                baffle_type = param_value
            elif param_name == "折流板切口方向":
                cut_direction = param_value
            elif param_name == "折流板要求切口率":
                try:
                    cut_rate = float(param_value)
                except ValueError:
                    # QMessageBox.warning(self, "参数错误", "折流板要求切口率必须为数值")
                    return
            elif param_name == "壳体内直径 Dis":
                try:
                    shell_inner_diameter = float(param_value)
                except ValueError:
                    # QMessageBox.warning(self, "参数错误", "壳体内直径必须为数值")
                    return
            elif param_name == "折流/支持板外径":
                try:
                    baffle_outer_diameter = float(param_value)
                except ValueError:
                    return
            elif param_name == "A型板切口与中心线间距a":
                try:
                    a_distance = float(param_value)
                except ValueError:
                    return
            elif param_name == "B型板切口与中心线间距b":
                try:
                    b_distance = float(param_value)
                except ValueError:
                    return

        baffle_type_text = (baffle_type or "").strip()
        # 支持板：不绘制切口线（黄线）
        if baffle_type_text == "支持板":
            return
        if baffle_type_text in ["双弓型", "双弓形"]:
            # 双弓型：根据 a/b 画竖向弦线
            # 优先使用折流/支持板外径作为大圆直径；若缺失则退回壳体内直径
            circle_diameter = baffle_outer_diameter or shell_inner_diameter
            if circle_diameter is None:
                return
            if a_distance is None or b_distance is None:
                return
            if circle_diameter <= 0:
                return

            R = circle_diameter / 2.0

            def draw_vertical_chord(
                    x_level: float, color: QColor, tag: str, line_width=3
            ):
                if x_level is None:
                    return
                if abs(x_level) > R:
                    return
                half_len = math.sqrt(max(0.0, R * R - x_level * x_level))
                pen_local = QPen(color)
                pen_local.setWidth(line_width)
                line_item = self.graphics_scene.addLine(
                    x_level,
                    -half_len,
                    x_level,
                    half_len,
                    pen_local,
                )
                self.baffle_lines.append(
                    {
                        "type": "vertical",
                        "x_level": x_level,
                        "y_range": (-half_len, half_len),
                        "line_item": line_item,
                        "baffle_subtype": tag,
                    }
                )

            # 折流板线条宽度（可调参数，值越大线越粗）
            baffle_line_width = (
                5  # 默认值，可根据需要调整（例如：1=细线，3=中等，5=粗线）
            )

            # 浅蓝色：A 型板（±a）
            light_blue = QColor(150, 200, 255)  # 更浅的蓝色
            draw_vertical_chord(
                a_distance, light_blue, "A", line_width=baffle_line_width
            )
            draw_vertical_chord(
                -a_distance, light_blue, "A", line_width=baffle_line_width
            )

            # 浅红色：B 型板（±b）
            light_red = QColor(255, 150, 150)  # 浅红色
            draw_vertical_chord(
                b_distance, light_red, "B", line_width=baffle_line_width
            )
            draw_vertical_chord(
                -b_distance, light_red, "B", line_width=baffle_line_width
            )

            self.operations.append(
                {
                    "type": "baffle_plate",
                    "direction": "double_bow_vertical",
                    "a": a_distance,
                    "b": b_distance,
                    "circle_diameter": circle_diameter,
                }
            )
            return

        # 验证必要参数是否存在
        if not all(
                [cut_direction, cut_rate is not None, shell_inner_diameter is not None]
        ):
            # QMessageBox.warning(self, "参数缺失", "请确保折流板相关参数已正确设置")
            return

        # 验证切口率范围 (0-50%)
        if not (0 <= cut_rate <= 50):
            # QMessageBox.warning(self, "参数错误", "折流板要求切口率必须在0%到50%范围内")
            return

        # 计算壳体半径 - 保持您的原有逻辑
        shell_radius = shell_inner_diameter

        # 根据您的公式计算折流板到圆心的距离
        # 距离圆心 = 壳体内直径 × 0.5 × (0.5 - 切口率/100)
        # 0.5 × 壳体内直径 等于 壳体半径，所以可简化为：
        distance_from_center = shell_radius * (0.5 - cut_rate / 100)

        # 验证计算结果是否合理（距离不能为负且不能超过半径）
        if distance_from_center < 0 or distance_from_center > shell_radius:
            # QMessageBox.warning(self, "参数错误", f"根据当前切口率计算出的折流板位置不合理: {distance_from_center}")
            return

        # 绘制黄色线段（折流板）
        pen = QPen(QColor(204, 204, 0))  # 黄色
        pen.setWidth(3)

        try:
            if cut_direction == "水平上下":
                # 计算弦长的一半 - 保持您的原有计算公式
                chord_half_length = math.sqrt(
                    (shell_radius / 2) ** 2 - distance_from_center ** 2
                )

                # 上侧线段（y=distance_from_center）并存储信息
                upper_line = self.graphics_scene.addLine(
                    -chord_half_length,
                    distance_from_center,
                    chord_half_length,
                    distance_from_center,
                    pen,
                )
                self.baffle_lines.append(
                    {
                        "type": "horizontal",
                        "y_level": distance_from_center,
                        "x_range": (-chord_half_length, chord_half_length),
                        "line_item": upper_line,
                    }
                )

                # 下侧线段（y=-distance_from_center）并存储信息
                lower_line = self.graphics_scene.addLine(
                    -chord_half_length,
                    -distance_from_center,
                    chord_half_length,
                    -distance_from_center,
                    pen,
                )
                self.baffle_lines.append(
                    {
                        "type": "horizontal",
                        "y_level": -distance_from_center,
                        "x_range": (-chord_half_length, chord_half_length),
                        "line_item": lower_line,
                    }
                )

                # 记录操作
                self.operations.append(
                    {
                        "type": "baffle_plate",
                        "direction": "horizontal",
                        "cut_rate": cut_rate,
                        "distance_from_center": distance_from_center,
                        "length": chord_half_length * 2,
                    }
                )

            elif cut_direction == "垂直左右":

                chord_half_length = math.sqrt(
                    (shell_radius / 2) ** 2 - distance_from_center ** 2
                )

                # 右侧线段（x=distance_from_center）并存储信息
                right_line = self.graphics_scene.addLine(
                    distance_from_center,
                    -chord_half_length,
                    distance_from_center,
                    chord_half_length,
                    pen,
                )
                self.baffle_lines.append(
                    {
                        "type": "vertical",
                        "x_level": distance_from_center,
                        "y_range": (-chord_half_length, chord_half_length),
                        "line_item": right_line,
                    }
                )

                # 左侧线段（x=-distance_from_center）并存储信息
                left_line = self.graphics_scene.addLine(
                    -distance_from_center,
                    -chord_half_length,
                    -distance_from_center,
                    chord_half_length,
                    pen,
                )
                self.baffle_lines.append(
                    {
                        "type": "vertical",
                        "x_level": -distance_from_center,
                        "y_range": (-chord_half_length, chord_half_length),
                        "line_item": left_line,
                    }
                )

                # 记录操作
                self.operations.append(
                    {
                        "type": "baffle_plate",
                        "direction": "vertical",
                        "cut_rate": cut_rate,
                        "distance_from_center": distance_from_center,
                        "length": chord_half_length * 2,
                    }
                )

        except Exception as e:
            print(f"绘制折流板时出错: {e}")
            # 如果绘制过程中出错，确保清除已创建的内容
            self.clear_baffle_plates()

    def clear_baffle_plates(self):
        """安全地清除所有折流板线段"""
        # 确保baffle_lines列表存在
        if not hasattr(self, "baffle_lines"):
            self.baffle_lines = []
            return

        try:
            # 首先从操作记录中移除折流板相关的操作
            if hasattr(self, "operations"):
                self.operations = [
                    op for op in self.operations if op.get("type") != "baffle_plate"
                ]

            # 然后从图形场景中移除所有折流板线段
            # 先收集所有要移除的项，避免在迭代中操作
            items_to_remove = []
            for baffle_info in self.baffle_lines:
                line_item = baffle_info.get("line_item")
                if line_item and self.graphics_scene:
                    items_to_remove.append(line_item)

            # 批量移除项目
            if self.graphics_scene:
                for item in items_to_remove:
                    try:
                        # 更安全的检查方式
                        if item and item in self.graphics_scene.items():
                            self.graphics_scene.removeItem(item)
                    except RuntimeError as e:
                        print(f"移除折流板线段时发生运行时错误: {e}")
                    except Exception as e:
                        print(f"移除折流板线段时出错: {e}")

            # 最后清空列表
            self.baffle_lines = []

        except Exception as e:
            print(f"清除折流板时出错: {e}")
            # 如果出错，重新初始化列表
            self.baffle_lines = []

    def create_scene(self):
        """
        创建场景并设置相关参数，通过类属性存储scene和small_D
        返回值：布尔值，表示场景是否创建成功
        """
        self.left_data_list = []
        self.left_data_pd = None

        # 初始化参数
        DL = None
        DN = None
        do = None
        height_0_180 = None
        height_90_270 = None
        table = self.param_table

        # 读取参数并填充
        for row in range(table.rowCount()):
            param_name = table.item(row, 1).text()
            param_value_widget = table.cellWidget(row, 2)

            # 根据控件类型获取参数值
            if param_value_widget and isinstance(param_value_widget, QComboBox):
                param_value = param_value_widget.currentText()
            else:
                item = table.item(row, 2)
                param_value = item.text() if item else ""

            # 存入列表
            self.left_data_list.append({"参数名": param_name, "参数值": param_value})

            # 提取关键参数
            if param_name == "壳体内直径 Dis":
                DL = float(param_value) if param_value else None
            elif param_name == "公称直径 DN":
                DN = float(param_value) if param_value else None
            elif param_name == "换热管外径 do":
                do = float(param_value) if param_value else None
                if do:
                    self.r = do / 2
            elif param_name == "非布管区域弦高（0°/180°）":
                height_0_180 = float(param_value) if param_value else None
            elif param_name == "非布管区域弦高（90°/270°）":
                height_90_270 = float(param_value) if param_value else None

        # 验证关键参数
        if DL is None or do is None:
            QMessageBox.warning(self, "提示", "请先输入 DL 和 do 两个参数。")
            return False

        # 转换为DataFrame
        self.left_data_pd = pd.DataFrame(self.left_data_list)

        # 存储需要在外部使用的参数
        self.small_D = do  # 将small_D设为类属性
        current_centers = self.current_centers
        big_D_wai = DN
        big_D_nei = DL

        # 获取场景
        scene = self.graphics_scene
        # 计算半径
        R_wai = big_D_wai / 2.0 if big_D_wai else 0
        R_nei = big_D_nei / 2.0 if big_D_nei else 0
        r = self.small_D / 2.0

        # 设置坐标系：在原点上方多留空间、下方少留空间，避免 0° 位置贴到顶部工具栏
        padding = R_wai * 0.2  # 基础边距
        base = R_wai + padding
        top = -(R_wai + padding * 1.5)
        height = 2 * base
        left = -base
        scene.setSceneRect(left, top, 2 * base, height)

        # 仅同步参数数据；图形由 draw_layout 统一绘制，避免重复叠画换热管
        self.ensure_main_axes(scene)

        # 存储场景到类属性
        self.scene = scene
        return True

    # TODO 更新返回值
    def update_pipe_parameters(self):
        # 首先确保output_data是字典类型
        if isinstance(self.output_data, str):
            try:
                # 尝试将字符串解析为JSON字典
                self.output_data = json.loads(self.output_data)
            except json.JSONDecodeError:
                print("无法解析output_data为JSON格式")
                return
        elif not isinstance(self.output_data, dict):
            print("output_data不是有效的字典或JSON字符串")
            return
        # 不在这里更新隔条了
        param_mapping = {
            # "SN": "分程隔板两侧相邻管中心距（竖直）",
            # "SNH": "分程隔板两侧相邻管中心距（水平）",
            # "BaffleOD": "折流/支持板外径",
            # "SlipWayThick": "滑道厚度",
            # "SlipWayAngle": "滑道与竖直中心线夹角",
            # "SlipWayHeight": "滑道高度",
            # "DNs": "公称直径 DN",
            # "DL": "布管限定圆 DL",
            # "BPBThick": "旁路挡板厚度",
            # 按需求：S 仅按 do+排列方式 对应表联动，不使用后端 output_data 回写覆盖
            "S": "换热管中心距 S",
            # "W": "隔条位置尺寸 W"
        }

        # 遍历所有需要更新的参数
        for param_key, param_name in param_mapping.items():
            # 获取参数值，特殊处理DNs参数
            try:
                if param_key == "DNs":
                    param_value = self.output_data["DNs"]["R"]
                elif param_key == "DLs":
                    param_value = self.output_data["DLs"]["R"]
                else:
                    # 检查参数是否存在
                    param_value = self.output_data[param_key]
            except (KeyError, TypeError):
                # 如果参数不存在或结构不符合预期，跳过该参数
                print(f"参数{param_key}不存在或格式错误，已跳过")
                continue

            # 遍历参数表格的所有行，查找对应的参数
            for row in range(self.param_table.rowCount()):
                # 获取当前行的参数名
                param_name_item = self.param_table.item(row, 1)
                if param_name_item and param_name_item.text() == param_name:
                    # 检查该单元格是普通文本项还是下拉框组件
                    cell_widget = self.param_table.cellWidget(row, 2)

                    # 将参数值转换为字符串
                    # 特殊处理：隔条位置尺寸W保留两位小数
                    if param_key == "W":
                        try:
                            float_value = float(param_value)
                            value_str = f"{float_value:.2f}"
                        except (ValueError, TypeError):
                            value_str = str(param_value)
                    else:
                        value_str = str(param_value)

                    if isinstance(cell_widget, QComboBox):
                        # 如果是下拉框，尝试找到匹配的选项并设置
                        index = cell_widget.findText(value_str)
                        if index >= 0:
                            cell_widget.setCurrentIndex(index)
                        else:
                            # 如果没有匹配项，直接添加并选中
                            cell_widget.addItem(value_str)
                            cell_widget.setCurrentText(value_str)
                    else:
                        # 如果是普通文本项，直接设置文本
                        value_item = self.param_table.item(row, 2)
                        if value_item:
                            value_item.setText(value_str)
                        else:
                            # 如果单元格不存在，创建新项
                            self.param_table.setItem(
                                row, 2, QTableWidgetItem(value_str)
                            )

                    # 找到并更新后退出当前参数的行循环
                    break

    def on_buguan_bt_click(self):
        """
        布管按钮点击入口。
        该函数容易因 UI/图元/信号链路导致异常从 slot 泄漏而“闪退”，因此在关键步骤加细粒度 try/except。
        """
        import traceback

        # 防止重复点击/重入导致状态交错（常见闪退源）
        if getattr(self, "_buguan_in_progress", False):
            return
        self._buguan_in_progress = True

        step_errors = []
        # 回车触发布管时，也要与失焦一致：先走完整预检弹窗逻辑，再决定是否继续布管。
        suppress_precheck_dialogs = False

        def _safe_step(step_name, fn, *args, **kwargs):
            try:
                return fn(*args, **kwargs)
            except Exception as e:
                msg = f"[on_buguan_bt_click ERROR] {step_name} 出错: {e}"
                print(msg)
                traceback.print_exc()
                step_errors.append(msg)
                return None

        def _commit_param_table_edits_before_run():
            """
            回车触发布管时，编辑器（尤其是可编辑 QComboBox）可能还没把文本提交到表格模型。
            这里强制把“换热管中心距 S”等正在编辑的值写回 param_table，确保后续校验读取到最新输入。
            """
            try:
                from PyQt5.QtWidgets import QComboBox, QLineEdit, QApplication
                from PyQt5.QtCore import QCoreApplication
            except Exception:
                return

            # 1) 先让当前焦点控件失焦，触发提交（对 QLineEdit/Combo 的 lineEdit 有帮助）
            try:
                fw = QApplication.focusWidget()
                if fw is not None and isinstance(fw, (QLineEdit, QComboBox)):
                    fw.clearFocus()
            except Exception:
                pass

            # 2) 对“换热管中心距 S”这一行：若是可编辑下拉框，显式 interpretText 提交 lineEdit 文本
            try:
                s_row = -1
                for r in range(self.param_table.rowCount()):
                    name_item = self.param_table.item(r, 1)
                    if name_item and name_item.text().strip() == "换热管中心距 S":
                        s_row = r
                        break
                if s_row >= 0:
                    w = self.param_table.cellWidget(s_row, 2)
                    if isinstance(w, QComboBox) and w.isEditable():
                        try:
                            w.interpretText()
                            if w.lineEdit() is not None:
                                txt = w.lineEdit().text().strip()
                                if txt != "":
                                    w.setCurrentText(txt)
                        except Exception:
                            pass
            except Exception:
                pass

            # 2.5) 对“隔条位置尺寸 W”这一行：若是可编辑下拉框，显式 interpretText 提交 lineEdit 文本
            try:
                w_row = -1
                for r in range(self.param_table.rowCount()):
                    name_item = self.param_table.item(r, 1)
                    if name_item and name_item.text().strip() == "隔条位置尺寸 W":
                        w_row = r
                        break
                if w_row >= 0:
                    w_widget = self.param_table.cellWidget(w_row, 2)
                    if isinstance(w_widget, QComboBox) and w_widget.isEditable():
                        try:
                            w_widget.interpretText()
                            if w_widget.lineEdit() is not None:
                                txt = w_widget.lineEdit().text().strip()
                                if txt != "":
                                    w_widget.setCurrentText(txt)
                        except Exception:
                            pass
            except Exception:
                pass

            # 3) 跑一轮事件循环，让模型/委托有机会落盘
            try:
                QCoreApplication.processEvents()
            except Exception:
                pass

        def _precheck_tube_center_distance_S():
            """
            Enter/Return 直接布管时，itemChanged 可能没触发。
            因此在真正开始 calculate_piping_layout 之前，先做一次 S 的合规校验。
            """
            try:
                from PyQt5.QtWidgets import QMessageBox, QComboBox, QTableWidgetItem
            except Exception:
                return True

            # 读取 do
            do_val = None
            try:
                do_raw = self.get_tube_do()
                do_val = float(str(do_raw).strip()) if do_raw not in (None, "") else None
            except Exception:
                do_val = None

            if do_val is None or do_val <= 0:
                return True

            # 读取当前表格中 "换热管中心距 S"
            s_val = None
            s_text_debug = ""
            s_row = -1
            row_count = self.param_table.rowCount()
            for r in range(row_count):
                name_item = self.param_table.item(r, 1)
                if not name_item:
                    continue
                if name_item.text().strip() == "换热管中心距 S":
                    s_row = r
                    # 1) 优先：若该单元格是可编辑 QComboBox，直接读取 lineEdit 文本
                    w = self.param_table.cellWidget(r, 2)
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable() and w.lineEdit() is not None:
                                s_text_debug = w.lineEdit().text().strip()
                            else:
                                s_text_debug = w.currentText().strip()
                        except Exception:
                            try:
                                s_text_debug = w.currentText().strip()
                            except Exception:
                                s_text_debug = ""
                        if s_text_debug != "":
                            try:
                                s_val = float(s_text_debug)
                            except Exception:
                                s_val = None
                    else:
                        # 2) 普通文本单元格
                        it = self.param_table.item(r, 2)
                        s_text_debug = it.text().strip() if it else ""
                        if s_text_debug != "":
                            try:
                                s_val = float(s_text_debug)
                            except Exception:
                                s_val = None
                    break

            # 调试输出：确认 on_buguan_bt_click 中实际拿到的 S 与 do
            try:
                print(
                    f"[on_buguan_bt_click S 预检] 读取到换热管中心距 S 文本='{s_text_debug}', 数值={s_val}, do={do_val}"
                )
            except Exception:
                pass

            # 回车直触发时，可能不会走到常规 itemChanged/currentTextChanged 高亮链路。
            # 这里补一次“已修改”标记，确保与“先失焦再回车”的蓝色显示一致。
            try:
                if s_row >= 0 and s_text_debug != "":
                    _orig = str(self.original_param_values.get((s_row, 2), "")).strip()
                    if s_text_debug != _orig:
                        self.modified_rows.add(s_row)
                        self.highlight_modified_row(s_row)
                    else:
                        if s_row in self.modified_rows:
                            self.modified_rows.remove(s_row)
                            self.reset_row_background(s_row)
            except Exception:
                pass

            if s_val is None:
                # 读不到时跳过本次 S 校验，由其他逻辑兜底
                return True

            # 硬限制：S 不能小于 do（与 itemChanged 逻辑保持一致）
            if s_val < do_val:
                if s_row >= 0:
                    w = self.param_table.cellWidget(s_row, 2)
                    rollback_text = ""
                    try:
                        rollback_text = str(self.original_param_values.get((s_row, 2), "")).strip()
                    except Exception:
                        rollback_text = ""
                    if rollback_text == "":
                        rollback_text = f"{do_val:g}"
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable() and w.lineEdit() is not None:
                                w.lineEdit().setText(rollback_text)
                            idx = w.findText(rollback_text)
                            if idx >= 0:
                                w.setCurrentIndex(idx)
                            else:
                                w.setCurrentText(rollback_text)
                        except Exception:
                            pass
                    else:
                        it = self.param_table.item(s_row, 2)
                        if it:
                            it.setText(rollback_text)
                        else:
                            try:
                                self.param_table.setItem(s_row, 2, QTableWidgetItem(rollback_text))
                            except Exception:
                                pass
                return False

            # 读取到了有效 S，视为本次用户手动输入应被保留（避免回车直接布管被推荐值覆盖）
            try:
                self._user_override_tube_center_distance = True
            except Exception:
                pass

            # 触发确认逻辑：S < 1.25 * do
            if s_val < 1.25 * do_val:
                # 全局 bool 逻辑：仅当“用户输入了新的违规值”时才允许弹窗
                try:
                    cur_text = (s_text_debug or "").strip()
                    prev_text = getattr(self, "_s_center_warn_last_text", None)
                    if prev_text != cur_text:
                        self._s_center_warn_last_text = cur_text
                        self._s_center_warn_pending = True
                except Exception:
                    pass

                if not getattr(self, "_s_center_warn_pending", False):
                    return True

                if suppress_precheck_dialogs:
                    # 静默：不弹对话框，直接允许继续布管
                    try:
                        self._s_center_warn_pending = False
                    except Exception:
                        pass
                    return True

                reply = QMessageBox.question(
                    self,
                    "提示",
                    "标准推荐换热管中心距不宜小于1.25倍的换热管外径，是否继续？",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                try:
                    print(
                        "[POPUP] type=question title=提示 msg=标准推荐换热管中心距不宜小于1.25倍的换热管外径，是否继续？ "
                        f"param=换热管中心距 S(回车预检) input='{s_text_debug}' parsed={s_val} do={do_val} threshold(1.25*do)={1.25 * do_val} "
                        f"result={'Yes' if reply == QMessageBox.Yes else 'No'}"
                    )
                except Exception:
                    pass
                # 用户已确认一次：进入全局静默
                try:
                    self._s_center_warn_pending = False
                except Exception:
                    pass
                if reply == QMessageBox.No and s_row >= 0:
                    # 清空输入：S 无论是 combobox 还是普通文本，都尽力清空
                    w = self.param_table.cellWidget(s_row, 2)
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable():
                                if w.lineEdit() is not None:
                                    w.lineEdit().setText("")
                                w.setCurrentText("")
                            else:
                                w.setCurrentText("")
                        except Exception:
                            pass
                    else:
                        it = self.param_table.item(s_row, 2)
                        if it:
                            it.setText("")
                        else:
                            try:
                                self.param_table.setItem(s_row, 2, QTableWidgetItem(""))
                            except Exception:
                                pass
                    try:
                        self._s_center_warn_last_text = ""
                    except Exception:
                        pass
                return reply == QMessageBox.Yes

            return True

        def _precheck_tube_wall_thickness_delta():
            """
            Enter/Return 直接布管时，确保“换热管壁厚 δ”也按与 S 相同机制先校验。
            规则：0 < δ <= do/2
            """
            try:
                from PyQt5.QtWidgets import QMessageBox, QComboBox, QTableWidgetItem
            except Exception:
                return True

            do_val = None
            try:
                do_raw = self.get_tube_do()
                do_val = float(str(do_raw).strip()) if do_raw not in (None, "") else None
            except Exception:
                do_val = None

            delta_val = None
            delta_text_debug = ""
            delta_row = -1
            row_count = self.param_table.rowCount()
            for r in range(row_count):
                name_item = self.param_table.item(r, 1)
                if not name_item:
                    continue
                if name_item.text().strip() == "换热管壁厚 δ":
                    delta_row = r
                    w = self.param_table.cellWidget(r, 2)
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable() and w.lineEdit() is not None:
                                delta_text_debug = w.lineEdit().text().strip()
                            else:
                                delta_text_debug = w.currentText().strip()
                        except Exception:
                            try:
                                delta_text_debug = w.currentText().strip()
                            except Exception:
                                delta_text_debug = ""
                    else:
                        it = self.param_table.item(r, 2)
                        delta_text_debug = it.text().strip() if it else ""
                    if delta_text_debug != "":
                        try:
                            delta_val = float(delta_text_debug)
                        except Exception:
                            delta_val = None
                    break

            try:
                print(
                    f"[on_buguan_bt_click δ预检] 读取到换热管壁厚δ 文本='{delta_text_debug}', 数值={delta_val}, do={do_val}"
                )
            except Exception:
                pass

            invalid = False
            if delta_val is None:
                invalid = True
            elif delta_val <= 0:
                invalid = True
            elif do_val is not None and do_val > 0 and delta_val > (do_val / 2.0):
                invalid = True

            if not invalid:
                try:
                    self._last_valid_tube_wall_thickness_text = delta_text_debug
                    self._tube_wall_warn_pending = False
                except Exception:
                    pass
                return True

            if suppress_precheck_dialogs:
                # 静默：跳过弹窗，直接回滚到最后合法值（或默认 2），继续布管
                try:
                    self._tube_wall_warn_pending = False
                except Exception:
                    pass

                if delta_row >= 0:
                    rollback_text = str(
                        getattr(self, "_last_valid_tube_wall_thickness_text", "2")
                    ).strip() or "2"
                    w = self.param_table.cellWidget(delta_row, 2)
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable() and w.lineEdit() is not None:
                                w.lineEdit().setText(rollback_text)
                            w.setCurrentText(rollback_text)
                        except Exception:
                            pass
                    else:
                        it = self.param_table.item(delta_row, 2)
                        if it:
                            it.setText(rollback_text)
                        else:
                            try:
                                self.param_table.setItem(
                                    delta_row, 2, QTableWidgetItem(rollback_text)
                                )
                            except Exception:
                                pass
                return True

            # 全局 bool 逻辑：仅当输入了“新的违规值”时才弹
            try:
                cur_text = (delta_text_debug or "").strip()
                prev_text = getattr(self, "_tube_wall_warn_last_text", None)
                if prev_text != cur_text:
                    self._tube_wall_warn_last_text = cur_text
                    self._tube_wall_warn_pending = True
            except Exception:
                pass

            if not getattr(self, "_tube_wall_warn_pending", False):
                return False

            QMessageBox.warning(
                self, "输入错误", "您输入的数值小于0或者过大，请重新输入!"
            )
            try:
                self._tube_wall_warn_pending = False
            except Exception:
                pass

            if delta_row >= 0:
                rollback_text = str(
                    getattr(self, "_last_valid_tube_wall_thickness_text", "2")
                ).strip() or "2"
                w = self.param_table.cellWidget(delta_row, 2)
                if isinstance(w, QComboBox):
                    try:
                        if w.isEditable() and w.lineEdit() is not None:
                            w.lineEdit().setText(rollback_text)
                        w.setCurrentText(rollback_text)
                    except Exception:
                        pass
                else:
                    it = self.param_table.item(delta_row, 2)
                    if it:
                        it.setText(rollback_text)
                    else:
                        try:
                            self.param_table.setItem(
                                delta_row, 2, QTableWidgetItem(rollback_text)
                            )
                        except Exception:
                            pass
            return False

        def _precheck_partition_side_center_distance_Sn_horizontal():
            """
            Enter/Return 直接布管时，itemChanged 可能没触发。
            因此在真正开始 calculate_piping_layout 之前，先做一次 Sn(水平) 的确认校验。
            """
            try:
                from PyQt5.QtWidgets import QMessageBox, QComboBox, QTableWidgetItem
            except Exception:
                return True

            expected_min = self._get_predefined_sn_horizontal_min_value()
            if expected_min is None or expected_min <= 0:
                return True

            # 读取 Sn(水平)
            sn_row = -1
            sn_text_debug = ""
            sn_val = None
            for r in range(self.param_table.rowCount()):
                name_item = self.param_table.item(r, 1)
                if name_item and name_item.text().strip() == "分程隔板两侧相邻管中心距（水平）":
                    sn_row = r
                    # 参数行被隐藏时（界面不显示），不应参与回车预检校验
                    try:
                        if hasattr(self, "param_table") and self.param_table.isRowHidden(r):
                            return True
                    except Exception:
                        pass
                    w = self.param_table.cellWidget(r, 2)
                    if isinstance(w, QComboBox):
                        try:
                            if w.isEditable() and w.lineEdit() is not None:
                                sn_text_debug = w.lineEdit().text().strip()
                            else:
                                sn_text_debug = w.currentText().strip()
                        except Exception:
                            try:
                                sn_text_debug = w.currentText().strip()
                            except Exception:
                                sn_text_debug = ""
                    else:
                        it = self.param_table.item(r, 2)
                        sn_text_debug = it.text().strip() if it else ""

                    if sn_text_debug != "":
                        try:
                            sn_val = float(sn_text_debug)
                        except Exception:
                            sn_val = None
                    break

            if sn_val is None:
                return True

            if sn_val < expected_min:
                # 全局 bool：仅当“新的违规输入值”才允许弹窗
                cur_text = (sn_text_debug or "").strip()
                prev_text = getattr(self, "_sn_horizontal_warn_last_text", None)
                if prev_text != cur_text:
                    self._sn_horizontal_warn_last_text = cur_text
                    self._sn_horizontal_warn_pending = True

                if not getattr(self, "_sn_horizontal_warn_pending", False):
                    return True

                if suppress_precheck_dialogs:
                    # 静默：不弹对话框，直接允许继续布管
                    try:
                        self._sn_horizontal_warn_pending = False
                    except Exception:
                        pass
                    return True

                reply = QMessageBox.question(
                    self,
                    "提示",
                    "您输入的数值小于预定义的规定，是否继续？",
                    QMessageBox.Yes | QMessageBox.No,
                    QMessageBox.No,
                )
                try:
                    print(
                        "[POPUP] type=question title=提示 msg=您输入的数值小于预定义的规定，是否继续？ "
                        f"param=分程隔板两侧相邻管中心距（水平）(回车预检) input='{cur_text}' parsed={sn_val} "
                        f"expected_min={expected_min} result={'Yes' if reply == QMessageBox.Yes else 'No'}",
                        flush=True,
                    )
                except Exception:
                    pass

                # 用户完成一次交互后全局静默
                try:
                    self._sn_horizontal_warn_pending = False
                except Exception:
                    pass

                if reply == QMessageBox.No and sn_row >= 0:
                    try:
                        self._sn_horizontal_warn_in_progress = True
                        self._suppress_sn_horizontal_warn = True
                    except Exception:
                        pass

                    try:
                        w = self.param_table.cellWidget(sn_row, 2)
                        if isinstance(w, QComboBox):
                            try:
                                if w.isEditable() and w.lineEdit() is not None:
                                    w.lineEdit().setText("")
                                w.setCurrentText("")
                            except Exception:
                                pass
                        else:
                            it = self.param_table.item(sn_row, 2)
                            if it:
                                it.setText("")
                            else:
                                try:
                                    self.param_table.setItem(sn_row, 2, QTableWidgetItem(""))
                                except Exception:
                                    pass
                    finally:
                        try:
                            QTimer.singleShot(
                                600,
                                lambda: (
                                    setattr(self, "_suppress_sn_horizontal_warn", False),
                                    setattr(self, "_sn_horizontal_warn_in_progress", False),
                                ),
                            )
                        except Exception:
                            try:
                                self._suppress_sn_horizontal_warn = False
                                self._sn_horizontal_warn_in_progress = False
                            except Exception:
                                pass

                    try:
                        self._sn_horizontal_warn_last_text = ""
                    except Exception:
                        pass

                    return False

            return True

        def _precheck_divider_position_size_W():
            """
            Enter/Return 直接布管时，确保“隔条位置尺寸 W”也按范围校验：
            0 < W < DL/2
            """
            try:
                from PyQt5.QtWidgets import QMessageBox, QComboBox, QTableWidgetItem
            except Exception:
                return True

            # 读取 DL（布管限定圆 DL）
            dl_val = None
            for r in range(self.param_table.rowCount()):
                name_item = self.param_table.item(r, 1)
                if name_item and name_item.text().strip() == "布管限定圆 DL":
                    w = self.param_table.cellWidget(r, 2)
                    dl_text = ""
                    if isinstance(w, QComboBox):
                        try:
                            dl_text = w.currentText().strip()
                        except Exception:
                            dl_text = ""
                    else:
                        it_dl = self.param_table.item(r, 2)
                        dl_text = it_dl.text().strip() if it_dl else ""
                    if dl_text != "":
                        try:
                            dl_val = float(dl_text)
                        except Exception:
                            dl_val = None
                    break

            if dl_val is None or dl_val <= 0:
                return True

            upper = dl_val / 2.0

            # 读取 W
            w_row = -1
            w_text_debug = ""
            w_val = None
            for r in range(self.param_table.rowCount()):
                name_item = self.param_table.item(r, 1)
                if name_item and name_item.text().strip() == "隔条位置尺寸 W":
                    w_row = r
                    # 参数行被隐藏时（界面不显示），不应参与回车预检校验
                    try:
                        if hasattr(self, "param_table") and self.param_table.isRowHidden(r):
                            return True
                    except Exception:
                        pass
                    widget = self.param_table.cellWidget(r, 2)
                    if isinstance(widget, QComboBox):
                        try:
                            if widget.isEditable() and widget.lineEdit() is not None:
                                w_text_debug = widget.lineEdit().text().strip()
                            else:
                                w_text_debug = widget.currentText().strip()
                        except Exception:
                            try:
                                w_text_debug = widget.currentText().strip()
                            except Exception:
                                w_text_debug = ""
                    else:
                        it_w = self.param_table.item(r, 2)
                        w_text_debug = it_w.text().strip() if it_w else ""

                    if w_text_debug != "":
                        try:
                            w_val = float(w_text_debug)
                        except Exception:
                            w_val = None
                    break

            if w_val is None:
                return True

            invalid = (w_val <= 0) or (w_val >= upper)
            if not invalid:
                # 更新最近合法值（供回滚使用）
                try:
                    self._last_valid_divider_W_text = w_text_debug
                except Exception:
                    pass
                return True

            # 非法：弹窗 + 回滚/重新输入
            if not suppress_precheck_dialogs:
                try:
                    print(
                        "[POPUP] type=warning title=输入错误 msg=您输入的数值小于0或已超限，请重新输入！ "
                        f"param=隔条位置尺寸W(回车预检) input='{w_text_debug}' parsed={w_val} "
                        f"upper(DL/2)={upper} rule=(0,DL/2) reason=<=0或>=上限 rollback='{str(getattr(self, '_last_valid_divider_W_text', '')).strip()}'"
                    )
                except Exception:
                    pass
                QMessageBox.warning(
                    self,
                    "输入错误",
                    "您输入的数值小于0或已超限，请重新输入！",
                )

            rollback_text = str(getattr(self, "_last_valid_divider_W_text", "")).strip()
            if rollback_text == "":
                # 兜底：尝试回退到 original_param_values
                try:
                    rollback_text = str(self.original_param_values.get((w_row, 2), "")).strip()
                except Exception:
                    rollback_text = ""

            if w_row >= 0:
                widget = self.param_table.cellWidget(w_row, 2)
                if isinstance(widget, QComboBox):
                    try:
                        if widget.isEditable() and widget.lineEdit() is not None:
                            widget.lineEdit().setText(rollback_text)
                        widget.setCurrentText(rollback_text)
                    except Exception:
                        pass
                else:
                    it = self.param_table.item(w_row, 2)
                    if it:
                        it.setText(rollback_text)
                    else:
                        try:
                            self.param_table.setItem(w_row, 2, QTableWidgetItem(rollback_text))
                        except Exception:
                            pass

            # 静默模式：跳过弹窗后仍允许继续布管（因为已回滚到最近合法值）
            return suppress_precheck_dialogs

        def _precheck_nonbaffle_chord_heights():
            """
            Enter/Return 直接布管时，确保非布管区域弦高满足：
            0 <= 值 <= DL/2
            """
            try:
                from PyQt5.QtWidgets import QMessageBox, QComboBox, QTableWidgetItem
            except Exception:
                return True

            # 读取 DL
            dl_val = None
            for r in range(self.param_table.rowCount()):
                it_dl_name = self.param_table.item(r, 1)
                if it_dl_name and it_dl_name.text().strip() == "布管限定圆 DL":
                    w_dl = self.param_table.cellWidget(r, 2)
                    dl_txt = ""
                    if isinstance(w_dl, QComboBox):
                        try:
                            dl_txt = w_dl.currentText().strip()
                        except Exception:
                            dl_txt = ""
                    else:
                        it_dl = self.param_table.item(r, 2)
                        dl_txt = it_dl.text().strip() if it_dl else ""
                    if dl_txt != "":
                        try:
                            dl_val = float(dl_txt)
                        except Exception:
                            dl_val = None
                    break

            if dl_val is None or dl_val <= 0:
                return True

            upper = dl_val / 2.0

            checks = [
                ("非布管区域弦高（0°/180°）", "_last_valid_chord_0_180_text"),
                ("非布管区域弦高（90°/270°）", "_last_valid_chord_90_270_text"),
            ]

            for pname, last_attr in checks:
                p_row = -1
                p_text = ""
                for r in range(self.param_table.rowCount()):
                    it_name = self.param_table.item(r, 1)
                    if it_name and it_name.text().strip() == pname:
                        p_row = r
                        w_p = self.param_table.cellWidget(r, 2)
                        if isinstance(w_p, QComboBox):
                            try:
                                if w_p.isEditable() and w_p.lineEdit() is not None:
                                    p_text = w_p.lineEdit().text().strip()
                                else:
                                    p_text = w_p.currentText().strip()
                            except Exception:
                                p_text = ""
                        else:
                            it_p = self.param_table.item(r, 2)
                            p_text = it_p.text().strip() if it_p else ""
                        break

                if p_row < 0 or p_text == "":
                    continue

                try:
                    p_val = float(p_text)
                except Exception:
                    p_val = None

                if p_val is None or p_val < 0 or p_val > upper:
                    if not suppress_precheck_dialogs:
                        try:
                            print(
                                "[POPUP] type=warning title=输入错误 msg=您输入的数值小于0或已超限，请重新输入！ "
                                f"param=非布管弦高(回车预检) param_name='{pname}' input='{p_text}' parsed={p_val} "
                                f"upper(DL/2)={upper} rule=[0,DL/2] reason=解析失败/小于0/超上限 rollback='{str(getattr(self, last_attr, '') or '').strip()}'"
                            )
                        except Exception:
                            pass
                        QMessageBox.warning(
                            self,
                            "输入错误",
                            "您输入的数值小于0或已超限，请重新输入！",
                        )

                    rollback_text = str(getattr(self, last_attr, "") or "").strip()
                    if rollback_text == "":
                        try:
                            rollback_text = str(
                                self.original_param_values.get((p_row, 2), "")
                            ).strip()
                        except Exception:
                            rollback_text = ""
                    if rollback_text == "":
                        rollback_text = "0"

                    w_p = self.param_table.cellWidget(p_row, 2)
                    if isinstance(w_p, QComboBox):
                        try:
                            w_p.setCurrentText(rollback_text)
                        except Exception:
                            try:
                                w_p.setEditText(rollback_text)
                            except Exception:
                                pass
                    else:
                        it_p = self.param_table.item(p_row, 2)
                        if it_p:
                            it_p.setText(rollback_text)
                        else:
                            try:
                                self.param_table.setItem(
                                    p_row, 2, QTableWidgetItem(rollback_text)
                                )
                            except Exception:
                                pass

                    return True

            return True

        # 0) 必须在断开 itemChanged 之前：提交正在编辑的单元格并派发事件，让
        #    itemChanged → setup_parameter_listeners（含 Dis/Dit 联动、校验等）先跑完，再进入布管。
        #    原顺序若先 disconnect 再 _commit，则监听永远不会收到本次回车提交。
        try:
            self._commit_param_table_open_editor()
        except Exception as _fe_open:
            try:
                print(f"[on_buguan_bt_click] _commit_param_table_open_editor: {_fe_open}")
            except Exception:
                pass
        try:
            _commit_param_table_edits_before_run()
        except Exception as _fe_run:
            try:
                print(f"[on_buguan_bt_click] _commit_param_table_edits_before_run: {_fe_run}")
            except Exception:
                pass
        try:
            from PyQt5.QtCore import QCoreApplication
            QCoreApplication.processEvents()
        except Exception:
            pass

        # 1) 临时断开所有 itemChanged 监听，避免布管时触发参数修改逻辑
        self._safe_disconnect_param_table_item_changed()

        try:
            # 提交与事件派发已在上文（0）完成，这里不再重复

            # Enter/Return 直接布管：先校验 S（避免 itemChanged 未触发导致少弹窗）
            if not _precheck_tube_center_distance_S():
                return
            # Enter/Return 直接布管：也先校验换热管壁厚 δ（与 S 同机制）
            if not _precheck_tube_wall_thickness_delta():
                return

            # Enter/Return 直接布管：也先校验 Sn(水平) 预定义下限
            if not _precheck_partition_side_center_distance_Sn_horizontal():
                return

            # Enter/Return 直接布管：也先校验 隔条位置尺寸 W 范围（0 < W < DL/2）
            if not _precheck_divider_position_size_W():
                return

            # Enter/Return 直接布管：也先校验 非布管区域弦高范围（0 <= 值 <= DL/2）
            if not _precheck_nonbaffle_chord_heights():
                return

            # 布管前强制清理：场景中残留的“中间挡板”图形项 + 相关缓存
            # 仅清理 is_center_dangban 的项，避免误删其他图元
            def _clear_center_dangban_graphics_and_cache_before_buguan():
                try:
                    if hasattr(self, "graphics_scene") and self.graphics_scene is not None:
                        for item in list(self.graphics_scene.items()):
                            try:
                                if not getattr(item, "is_center_dangban", False):
                                    continue
                                # 先删附属临时图元
                                try:
                                    temp_items = getattr(item, "related_temp_items", None) or []
                                    if isinstance(temp_items, list):
                                        for t in list(temp_items):
                                            try:
                                                if t is not None and t.scene() == self.graphics_scene:
                                                    self.graphics_scene.removeItem(t)
                                            except Exception:
                                                continue
                                except Exception:
                                    pass
                                # 再删本体
                                try:
                                    if item.scene() == self.graphics_scene:
                                        self.graphics_scene.removeItem(item)
                                except Exception:
                                    pass
                            except Exception:
                                continue
                        try:
                            self.graphics_scene.update()
                            if hasattr(self, "graphics_view") and self.graphics_view:
                                self.graphics_view.viewport().update()
                        except Exception:
                            pass
                except Exception:
                    pass

                # 同步清空缓存，避免“干涉检测/重建”继续引用旧挡板
                try:
                    self.selected_center_dangban = []
                except Exception:
                    pass
                try:
                    self.center_dangban = []
                except Exception:
                    pass
                try:
                    self.all_center_dangban = []
                except Exception:
                    pass
                try:
                    self.center_dangban_dic = {}
                except Exception:
                    pass
                try:
                    self.center_dangban_lines = []
                except Exception:
                    pass

            _safe_step(
                "clear center dangban graphics/cache",
                _clear_center_dangban_graphics_and_cache_before_buguan,
            )

            # 布管前强制清理交叉布管缓存：
            # 点击“布管”会重算全新布局，旧交叉布管坐标（尤其第一/二/三排绝对坐标对）必须清空，
            # 否则后续“保存”会把残留数据重新写回数据库。
            def _clear_cross_pipe_cache_before_buguan():
                try:
                    if hasattr(self, "cross_pipe_lines") and self.cross_pipe_lines:
                        for line in list(self.cross_pipe_lines):
                            try:
                                if line and line.scene() == self.graphics_scene:
                                    self.graphics_scene.removeItem(line)
                            except Exception:
                                continue
                except Exception:
                    pass
                try:
                    self.cross_pipe_lines = []
                except Exception:
                    pass

                for attr in [
                    "coord_x_line1_2",
                    "coord_x_line2_2",
                    "coord_x_line3_2",
                    "coord_y_line1_2",
                    "coord_y_line2_2",
                    "coord_y_line3_2",
                    "coord_x_line1_4",
                    "coord_x_line2_4",
                    "coord_x_line3_4",
                    "coord_y_line1_4",
                    "coord_y_line2_4",
                    "coord_y_line3_4",
                    "abs_coords_line1",
                    "abs_coords_line2",
                    "abs_coords_line3",
                    "_current_abs_coords",
                ]:
                    try:
                        setattr(self, attr, [])
                    except Exception:
                        pass

                for attr in [
                    "is_x_line1",
                    "is_x_line2",
                    "is_x_line3",
                    "is_y_line1",
                    "is_y_line2",
                    "is_y_line3",
                ]:
                    try:
                        setattr(self, attr, False)
                    except Exception:
                        pass

            _safe_step(
                "clear cross pipe cache before buguan",
                _clear_cross_pipe_cache_before_buguan,
            )

            # 2) 计算布管（核心）
            result = _safe_step("calculate_piping_layout", self.calculate_piping_layout)

            # 2.5) 布管完成后，在下方 line_tip 提示一次当前状态总换热管数量
            try:
                total_tubes = len(getattr(self, "current_centers", []) or [])
                try:
                    print(f"[on_buguan_bt_click] current_centers count = {total_tubes}")
                except Exception:
                    pass
                try:
                    import json

                    output_obj = getattr(self, "output_data", None)
                    if output_obj is None:
                        output_obj = getattr(self, "outputdata", None)
                    if isinstance(output_obj, str):
                        output_obj = json.loads(output_obj)
                    if isinstance(output_obj, dict):
                        dl_val = output_obj.get("DL", None)
                        print(f"[on_buguan_bt_click] output_data DL = {dl_val}")
                        s_val = output_obj.get("S", None)
                        print(f"[on_buguan_bt_click] output_data S = {s_val}")
                except Exception:
                    pass

                if (
                    total_tubes is not None
                    and hasattr(self, "line_tip")
                    and self.line_tip is not None
                ):
                    message = f"当前状态总换热管孔数量为 {total_tubes} 个"
                    self.line_tip.setText(message)
                    self.line_tip.setStyleSheet("color: black;")
                    self.line_tip.setVisible(True)

                    expected_text = message

                    def _clear_if_same():
                        try:
                            if self.line_tip and self.line_tip.text() == expected_text:
                                self.line_tip.setText("")
                        except Exception:
                            pass

                    QTimer.singleShot(5000, _clear_if_same)
            except Exception:
                # 读取/提示失败不影响布管主流程
                pass

            # 3) 绘制折流板（可能依赖 result/参数齐全）
            # AKU/BKU 不绘制切口黄线
            if str(getattr(self, "heat_exchanger", "") or "").strip().upper() not in ("AKU", "BKU"):
                _safe_step("draw_baffle_plates", self.draw_baffle_plates)

            # 4) 更新满布行分组缓存（供后续点击/框选/表格使用）
            if result and getattr(self, "global_centers", None):
                def _rebuild_full_rows():
                    (
                        self.full_sorted_current_centers_up,
                        self.full_sorted_current_centers_down,
                    ) = self.group_centers_by_y(self.global_centers)
                _safe_step("group_centers_by_y(global_centers)", _rebuild_full_rows)

            # 5) 更新左下角拉杆统计（依赖 UI 组件存在）
            _safe_step("update_total_lagan_count(1)", self.update_total_lagan_count)

            # 6) 重置大量状态（这些字段会影响后续交互；逐块保护）
            _safe_step("reset selected_centers", setattr, self, "selected_centers", [])

            # 6.1) 先清理场景中普通拉杆图元（包括可视区外“幽灵拉杆”），避免后续保存误写回数据库
            def _clear_lagan_items_from_scene():
                if not hasattr(self, "graphics_scene") or self.graphics_scene is None:
                    return
                to_remove = []
                for it in list(self.graphics_scene.items()):
                    try:
                        if getattr(it, "is_lagan", False) and not getattr(it, "is_side_rod", False):
                            to_remove.append(it)
                    except Exception:
                        continue
                for it in to_remove:
                    try:
                        self.graphics_scene.removeItem(it)
                    except Exception:
                        pass
            _safe_step("clear lagan items from scene", _clear_lagan_items_from_scene)

            # 其余状态清零（尽量不触发 setter）
            for attr, default in [
                ("lagan_info", []),
                ("red_dangban", []),
                ("center_dangban", []),
                ("center_dangguan", []),
                ("center_dangguan_num", 0),
                ("del_centers", []),
                ("side_dangban", []),
                ("impingement_plate_1", []),
                ("impingement_plate_2", []),
                ("impingement_plate_del_centers", []),
                ("isHuadao", False),
                ("slide_selected_centers", []),
                ("interfering_tubes1", []),
                ("interfering_tubes2", []),
                ("coord_x_line1_2", []),
                ("coord_y_line1_2", []),
                ("coord_x_line2_2", []),
                ("coord_y_line2_2", []),
                ("coord_x_line3_2", []),
                ("coord_y_line3_2", []),
                ("coord_x_line1_4", []),
                ("coord_y_line1_4", []),
                ("coord_x_line2_4", []),
                ("coord_y_line2_4", []),
                ("coord_x_line3_4", []),
                ("coord_y_line3_4", []),
                ("side_dangban_dic", {}),
                ("_side_dangban_auto_id", 0),
                ("center_dangban_dic", {}),
                ("_center_dangban_auto_id", 0),
                ("operation_order", 0),
                ("impingement_plate_dic", {}),
                ("_impingement_plate_auto_id", 0),
            ]:
                _safe_step(f"reset {attr}", setattr, self, attr, default)

            # 7) 径向开孔字典：只清空字典，不清除图形项（避免访问已销毁的Qt对象导致崩溃）
            # 图形项会在后续重新绘制时自动替换
            def _reset_radial_holes():
                # 只清空字典中的坐标和图形项引用字典，不删除图形项本身
                # 这样可以避免访问已销毁的Qt对象导致的访问冲突
                if hasattr(self, "radial_hole_dict") and isinstance(self.radial_hole_dict, dict):
                    for v in self.radial_hole_dict.values():
                        if isinstance(v, dict) and "换热管坐标" in v:
                            v["换热管坐标"] = None
                else:
                    self.radial_hole_dict = {}
                # 清空图形项引用字典，但不删除图形项（让它们自然被后续绘制覆盖）
                if hasattr(self, "_radial_hole_tangent_items_by_coord"):
                    self._radial_hole_tangent_items_by_coord = {}
            _safe_step("reset radial_hole_dict", _reset_radial_holes)

            # 8) 吊环螺钉相关：初始化
            _safe_step("reset screw_ring_dic", setattr, self, "screw_ring_dic", {})
            _safe_step("reset _screw_ring_auto_id", setattr, self, "_screw_ring_auto_id", 0)
            _safe_step("reset selected_screw_ring_ids", setattr, self, "selected_screw_ring_ids", set())

        finally:
            # 9) 恢复监听（无论成功与否都必须做）
            _safe_step("setup_parameter_listeners", self.setup_parameter_listeners)
            _safe_step("setup_param_listeners", self.setup_param_listeners)
            _safe_step("update_total_lagan_count(2)", self.update_total_lagan_count)

            def _finalize_axes():
                self.ensure_main_axes(self.graphics_scene, force=True)
                if hasattr(self, "graphics_scene") and self.graphics_scene:
                    self.graphics_scene.update()

            _safe_step("ensure_main_axes finally", _finalize_axes)
            QTimer.singleShot(0, _finalize_axes)

            self._buguan_in_progress = False

            if step_errors:
                print("[on_buguan_bt_click] 本次布管步骤出现异常（已捕获，避免闪退）：")
                for m in step_errors:
                    print("  -", m)

    def find_nearest_circle_index(
            self,
            sorted_centers_up: List[List[Tuple[float, float]]],
            sorted_centers_down: List[List[Tuple[float, float]]],
            mouse_x: float,
            mouse_y: float,
            r: float,
    ) -> Tuple[int, int]:
        """
        从上下两组圆心坐标中查找距离 (mouse_x, mouse_y) 最近的圆心，
        如果该点与圆心距离小于半径 r，则返回 (行索引, 列索引)；否则返回 None。

        参数:
            sorted_centers_up: List[List[Tuple[x, y]]]，正 y 坐标分组，每组按 x 升序排列。
            sorted_centers_down: List[List[Tuple[x, y]]]，负 y 坐标分组，每组按 x 升序排列。
            mouse_x: 鼠标点击的 x 坐标
            mouse_y: 鼠标点击的 y 坐标
            r: 小圆半径
        返回:
            (行索引, 列索引) 或 None
        """
        import math

        # 检查上半圆 (y >= 0)
        for row_idx, row in enumerate(sorted_centers_up):
            for col_idx, (x, y_pos) in enumerate(row):
                dist = math.hypot(mouse_x - x, mouse_y - y_pos)
                if dist < r:
                    return (row_idx, col_idx)

        # 检查下半圆 (y <= 0)
        for row_idx, row in enumerate(sorted_centers_down):
            for col_idx, (x, y_neg) in enumerate(row):
                dist = math.hypot(mouse_x - x, mouse_y - y_neg)
                if dist < r:
                    return (row_idx, col_idx)

        return None

    def group_centers_by_y(
            self, centers: List[Tuple[float, float]], tol: float = 1e-3
    ) -> Tuple[List[List[Tuple[float, float]]], List[List[Tuple[float, float]]]]:
        """
        将 centers 分别按 y>0 和 y<0 分组，y 相近（在 tol 范围内）视为同一组，并对每组按 x 坐标升序排列。
        返回一个元组：(positive_groups, negative_groups)
        始终保持与满布状态相同的行数结构，缺失的行用空列表填充
        特殊处理：当管程分程形式为4.3或6.2时，最中间一行只有正行，没有对称的负行
        """
        from collections import defaultdict

        # 获取当前管程分程形式
        is_special_layout = hasattr(
            self, "tube_pass_form_value"
        ) and self.tube_pass_form_value in ["4.3", "6.2", "1.1"]

        # 获取满布状态的行键作为参考
        full_pos_keys = set()
        full_neg_keys = set()

        # 如果存在满布状态数据，获取其行键
        if hasattr(self, "full_sorted_current_centers_up") and hasattr(
                self, "full_sorted_current_centers_down"
        ):
            # 获取满布状态的行键
            for row in self.full_sorted_current_centers_up:
                if row:  # 确保行不为空
                    y = row[0][1]  # 取该行第一个点的y坐标
                    full_pos_keys.add(int(round(abs(y) / tol)))

            for row in self.full_sorted_current_centers_down:
                if row:  # 确保行不为空
                    y = row[0][1]  # 取该行第一个点的y坐标
                    full_neg_keys.add(int(round(abs(y) / tol)))

        # 处理当前传入的圆心
        pos_groups = defaultdict(list)
        neg_groups = defaultdict(list)

        for x, y in centers:
            y_key = int(round(abs(y) / tol))
            if y >= 0:
                pos_groups[y_key].append((x, y))
            else:
                neg_groups[y_key].append((x, y))

        # 合并满布状态的行键和当前行键
        all_pos_keys = (
            full_pos_keys.union(pos_groups.keys())
            if full_pos_keys
            else sorted(pos_groups.keys())
        )
        all_neg_keys = (
            full_neg_keys.union(neg_groups.keys())
            if full_neg_keys
            else sorted(neg_groups.keys())
        )

        # 对每组按 x 坐标排序，并按 y 绝对值从小到大排列
        sorted_pos_keys = sorted(all_pos_keys)
        sorted_neg_keys = sorted(all_neg_keys)

        # 构建初始结果
        pos_grouped = [sorted(pos_groups.get(key, [])) for key in sorted_pos_keys]
        neg_grouped = [sorted(neg_groups.get(key, [])) for key in sorted_neg_keys]

        # 特殊布局处理：4.3或6.2分程形式
        if is_special_layout:
            # 确保第一行（最中间行）只有正行，负行对应位置为空
            # 1. 找到最中间行（y绝对值最小的正行）
            if pos_grouped:
                # 2. 调整负行结构：
                #    - 如果负行数量与正行相同，第一行置为空列表
                #    - 如果负行数量比正行少，在开头添加空列表
                if len(neg_grouped) == len(pos_grouped):
                    neg_grouped[0] = []  # 第一行负组强制为空
                elif len(neg_grouped) < len(pos_grouped):
                    # 在负行开头插入空列表，确保第一行为空
                    neg_grouped.insert(0, [])

                # 3. 确保剩余行是偶数且正负对称
                #    从第二行开始，只保留成对的行
                max_paired_rows = min(len(pos_grouped) - 1, len(neg_grouped) - 1)
                pos_grouped = [pos_grouped[0]] + pos_grouped[1: 1 + max_paired_rows]
                neg_grouped = [neg_grouped[0]] + neg_grouped[1: 1 + max_paired_rows]

        return pos_grouped, neg_grouped

    def find_edge_tube(self) -> List[Tuple[float, float]]:
        global edge_centers

        # if not hasattr(self, "sorted_current_centers_up") or not hasattr(
        #         self, "sorted_current_centers_down"
        # ):
        #     # 获取 current_centers 和 lagan_info 的并集
        #     current_centers = getattr(self, "current_centers", [])
        #     lagan_info = getattr(self, "lagan_info", [])
        #     merged_centers = list(current_centers) + list(lagan_info)
            
        self.sorted_current_centers_up, self.sorted_current_centers_down = (
                self.group_centers_by_y(self.global_centers)
        )

        rows = []
        for row in self.sorted_current_centers_up:
            if row:
                rows.append(row)
        for row in self.sorted_current_centers_down:
            if row:
                rows.append(row)

        edge_set = set()
        edge_centers.clear()
        if not rows:
            return edge_centers

        top_row = max(rows, key=lambda r: r[0][1])
        bottom_row = min(rows, key=lambda r: r[0][1])

        for row in rows:
            if row is top_row or row is bottom_row:
                for pt in row:
                    edge_set.add(pt)
            else:
                edge_set.add(row[0])
                edge_set.add(row[-1])

        edge_centers.extend(list(edge_set))
        try:
            self.edge_centers = edge_centers
        except Exception:
            pass
        return edge_centers

    def group_centers_by_x(
            self, centers: List[Tuple[float, float]], tol: float = 1e-3
    ) -> Tuple[List[List[Tuple[float, float]]], List[List[Tuple[float, float]]]]:
        """
        按照 x 坐标将圆心分组为列，并分为左侧（x<0）和右侧（x>=0）
        1. x坐标差值绝对值≤1的点算同一列
        2. 左右对称的列（x和-x）算同一组，放在同一行
        3. 始终保持与满布状态相同的列数结构，缺失的列用空列表填充
        """
        from collections import defaultdict

        # 获取当前管程分程形式
        is_special_layout = hasattr(
            self, "tube_pass_form_value"
        ) and self.tube_pass_form_value in ["1.1", "2.1", "4.1", "4.3", "6.1"]

        # 处理当前传入的圆心
        left_groups = defaultdict(list)
        right_groups = defaultdict(list)

        for x, y in centers:
            x_key = int(round(abs(x) / tol))  # 使用x坐标的绝对值作为键
            if x < 0:
                left_groups[x_key].append((x, y))
            else:
                right_groups[x_key].append((x, y))

        # 获取满布状态的列键作为参考
        full_keys_set = set()

        # 如果存在满布状态数据，获取其列键
        if hasattr(self, "full_sorted_current_centers_left") and hasattr(
                self, "full_sorted_current_centers_right"
        ):
            # 获取满布状态的列键（x坐标的绝对值）
            for col in self.full_sorted_current_centers_left:
                if col:  # 确保列不为空
                    x = col[0][0]  # 取该列第一个点的x坐标
                    full_keys_set.add(int(round(abs(x) / tol)))

            for col in self.full_sorted_current_centers_right:
                if col:  # 确保列不为空
                    x = col[0][0]  # 取该列第一个点的x坐标
                    full_keys_set.add(int(round(abs(x) / tol)))

        # 获取当前状态的列键
        current_keys_set = set()
        current_keys_set.update(left_groups.keys())
        current_keys_set.update(right_groups.keys())

        # 合并满布状态和当前状态的列键
        all_keys_set = full_keys_set.union(current_keys_set) if full_keys_set else current_keys_set

        # 按x绝对值从小到大排序
        sorted_keys = sorted(all_keys_set)

        # 构建结果
        left_grouped = []
        right_grouped = []

        for key in sorted_keys:
            # 获取对应列的左侧点和右侧点
            left_col = left_groups.get(key, [])
            right_col = right_groups.get(key, [])

            # 对每列按y坐标排序
            left_col_sorted = sorted(left_col, key=lambda p: p[1])
            right_col_sorted = sorted(right_col, key=lambda p: p[1])

            left_grouped.append(left_col_sorted)
            right_grouped.append(right_col_sorted)

        # 特殊布局处理
        if is_special_layout:
            # 确保中间列（key=0）只有右侧有值，左侧为空
            if sorted_keys and sorted_keys[0] == 0:
                left_grouped[0] = []  # 中间列左侧强制为空

        return left_grouped, right_grouped
    def on_table_right_click(self, position):
        """处理表格右键点击事件，取消选中状态"""
        # 清除所有选中
        self.hole_distribution_table.clearSelection()
        # 始终使用整行选中

        self.on_row_selection_changed()

    def _remove_abs_selection_marker(self, x, y):
        """移除绝对坐标处的选中 marker（与换热管选中叠层一致，data(0)=='marker'）。"""
        from PyQt5.QtCore import QPointF
        from PyQt5.QtWidgets import QGraphicsEllipseItem

        if not hasattr(self, "graphics_scene") or not self.graphics_scene:
            return
        try:
            pt = QPointF(float(x), float(y))
        except Exception:
            return
        for it in self.graphics_scene.items(pt):
            if isinstance(it, QGraphicsEllipseItem) and it.data(0) == "marker":
                self.graphics_scene.removeItem(it)
                break

    def _add_abs_selection_marker(self, x, y):
        """在绝对坐标处叠一层淡蓝实心 marker（与 eventFilter 中换热管选中一致）。"""
        from PyQt5.QtCore import Qt
        from PyQt5.QtGui import QPen, QBrush, QColor
        from PyQt5.QtWidgets import QGraphicsEllipseItem

        if not hasattr(self, "graphics_scene") or not self.graphics_scene:
            return
        try:
            fx, fy = float(x), float(y)
        except Exception:
            return
        # 避免重复叠 marker
        self._remove_abs_selection_marker(fx, fy)
        r = float(getattr(self, "r", 0) or 0)
        if r <= 0:
            return
        pen = QPen(Qt.NoPen)
        brush = QBrush(QColor(173, 216, 230))
        marker = self.graphics_scene.addEllipse(
            fx - r, fy - r, 2 * r, 2 * r, pen, brush
        )
        marker.setData(0, "marker")
        try:
            # 普通拉杆本体 z 常为 20，marker 需在其之上
            marker.setZValue(25)
        except Exception:
            pass

    def simulate_center_click(self, x, y):
        """模拟点击圆心，直接处理选中逻辑，不通过eventFilter"""
        # 临时设置鼠标坐标
        self.mouse_x = x
        self.mouse_y = y

        # 确保圆心列表存在
        if not hasattr(self, "full_sorted_current_centers_up"):
            self.full_sorted_current_centers_up = []
        if not hasattr(self, "full_sorted_current_centers_down"):
            self.full_sorted_current_centers_down = []

        # 根据y坐标方向选择正确的圆心列表
        if self.mouse_y >= 0:
            centers = self.full_sorted_current_centers_up
            y_multiplier = 1
        else:
            centers = self.full_sorted_current_centers_down
            y_multiplier = -1

        # 根据x坐标方向确定列号
        x_multiplier = 1 if self.mouse_x >= 0 else -1

        # 查找最近的圆心
        result = (
            self.find_nearest_circle_index(
                centers, [], self.mouse_x, self.mouse_y, self.r
            )
            if centers
            else None
        )

        if result:
            row, col = result
            x_center, y_center = centers[row][col]
            row_label = (row + 1) * y_multiplier
            col_label = (col + 1) * x_multiplier
            label = (row_label, col_label)

            if not hasattr(self, "selected_centers"):
                self.selected_centers = []

            if label in self.selected_centers:
                # 取消选中 → 删除 marker，使用列表推导式创建新列表
                new_selected = [c for c in self.selected_centers if c != label]
                self.selected_centers = new_selected
                self._remove_abs_selection_marker(x_center, y_center)
            else:
                # 添加选中 → 画 marker，通过新列表赋值方式添加
                new_selected = self.selected_centers + [label]
                self.selected_centers = new_selected
                self._add_abs_selection_marker(x_center, y_center)

    # TODO 整行选中函数
    def on_row_selection_changed(self):
        self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
            self.group_centers_by_y(self.global_centers)
        )
        self.sorted_current_centers_up, self.sorted_current_centers_down = (
            self.group_centers_by_y(self.current_centers)
        )
        """响应右侧表格选中事件，高亮对应小圆和表格整行，并同步更新 self.selected_centers"""
        if not hasattr(self, "full_sorted_current_centers_up") or not hasattr(
                self, "full_sorted_current_centers_down"
        ):
            return

        # 获取当前管程分程形式，判断是否为特殊布局
        is_special_layout = hasattr(
            self, "tube_pass_form_value"
        ) and self.tube_pass_form_value in ["4.3", "6.2"]

        # 清除旧高亮，恢复为标准小圆
        self.clear_selection_highlight()
        self.isZhenglie = True

        # 清除表格所有行的高亮
        for row in range(self.hole_distribution_table.rowCount()):
            for col in range(self.hole_distribution_table.columnCount()):
                item = self.hole_distribution_table.item(row, col)
                if item:
                    # 恢复默认样式
                    item.setBackground(QBrush(Qt.NoBrush))

        # 获取当前选中的单元格并提取所有选中行（去重）
        selected_indexes = self.hole_distribution_table.selectedIndexes()
        selected_rows = (
            set(index.row() for index in selected_indexes)
            if selected_indexes
            else set()
        )

        if not selected_rows:
            return

        # 高亮所有选中行的表格单元格
        for row in selected_rows:
            # 高亮表格中选中行的所有列
            for col in range(self.hole_distribution_table.columnCount()):
                item = self.hole_distribution_table.item(row, col)
                if item:
                    # 设置单元格背景为蓝色
                    item.setBackground(QBrush(QColor(173, 216, 230)))  # LightBlue
                else:
                    # 如果单元格不存在，创建一个临时项来设置背景
                    temp_item = QTableWidgetItem()
                    temp_item.setBackground(QBrush(QColor(173, 216, 230)))
                    self.hole_distribution_table.setItem(row, col, temp_item)

        # 通过eventFilter来逐个处理圆心选中
        for row in selected_rows:
            # 特殊布局处理：如果是第一行且是特殊布局，只处理正行
            if is_special_layout and row == 0:
                # 只处理上半部分的第一行（最中间的行）
                if row < len(self.full_sorted_current_centers_up):
                    centers_up = self.full_sorted_current_centers_up[row]
                    for col_idx, (x, y) in enumerate(centers_up):
                        # 通过eventFilter来处理选中逻辑
                        self.simulate_center_click(x, y)
            else:
                # 正常处理：上下对称行
                # 处理下半部分（行号为负）
                if row < len(self.full_sorted_current_centers_down):
                    centers_down = self.full_sorted_current_centers_down[row]
                    for col_idx, (x, y) in enumerate(centers_down):
                        # 通过eventFilter来处理选中逻辑
                        self.simulate_center_click(x, y)

                # 处理上半部分（行号为正）
                if row < len(self.full_sorted_current_centers_up):
                    centers_up = self.full_sorted_current_centers_up[row]
                    for col_idx, (x, y) in enumerate(centers_up):
                        # 通过eventFilter来处理选中逻辑
                        self.simulate_center_click(x, y)

        # 整行选中完成后，提示当前选中的换热管孔数量
        try:
            count = (
                len(self.selected_centers) if hasattr(self, "selected_centers") else 0
            )
            message = f"您当前选中的换热管孔的数量为{count}个"
            self.line_tip.setText(message)
            self.line_tip.setStyleSheet("color: black;")
            self.line_tip.setVisible(True)
            from PyQt5.QtCore import QTimer

            QTimer.singleShot(5000, lambda: self.line_tip.setText(""))
        except AttributeError:
            count = (
                len(self.selected_centers) if hasattr(self, "selected_centers") else 0
            )
            message = f"您当前选中的换热管孔的数量为{count}个"
            print(message)

    # TODO 整列选中函数
    def on_col_selection_changed(self):
        """整列选中：按列高亮并选中对应的左右列圆心"""
        # 更新列分组（满布与当前）
        self.full_sorted_current_centers_left, self.full_sorted_current_centers_right = (
            self.group_centers_by_x(self.global_centers)
        )
        self.sorted_current_centers_left, self.sorted_current_centers_right = (
            self.group_centers_by_x(self.current_centers)
        )

        if not hasattr(self, "full_sorted_current_centers_left") or not hasattr(
                self, "full_sorted_current_centers_right"
        ):
            return

        # 特殊布局：只保留中间列的一侧（右侧）有值
        is_special_layout = hasattr(self, "tube_pass_form_value") and (
                self.tube_pass_form_value in ["1.1", "2.1", "4.1", "4.3", "6.1"]
        )

        # 清除旧高亮
        self.clear_selection_highlight()
        self.isZhenglie = True

        # 清除表格所有单元格高亮
        for row in range(self.hole_distribution_table.rowCount()):
            for col in range(self.hole_distribution_table.columnCount()):
                item = self.hole_distribution_table.item(row, col)
                if item:
                    item.setBackground(QBrush(Qt.NoBrush))

        # 当前选中的行集合（按列排列时，一行代表一列的数据）
        selected_indexes = self.hole_distribution_table.selectedIndexes()
        selected_rows = (
            set(index.row() for index in selected_indexes) if selected_indexes else set()
        )
        if not selected_rows:
            return

        # 表格高亮选中行
        for row in selected_rows:
            for col in range(self.hole_distribution_table.columnCount()):
                item = self.hole_distribution_table.item(row, col)
                if item:
                    item.setBackground(QBrush(QColor(173, 216, 230)))  # LightBlue
                else:
                    temp_item = QTableWidgetItem()
                    temp_item.setBackground(QBrush(QColor(173, 216, 230)))
                    self.hole_distribution_table.setItem(row, col, temp_item)

        # 逐列处理圆心选中
        for row in selected_rows:
            col_idx = row  # 当前表格行对应的列索引
            # 特殊布局：中间列只选右侧
            if is_special_layout and col_idx == 0:
                if col_idx < len(self.full_sorted_current_centers_right):
                    centers_right = self.full_sorted_current_centers_right[col_idx]
                    for (x, y) in centers_right:
                        self.simulate_center_click(x, y)
                continue

            # 正常对称处理：左右两侧
            if col_idx < len(self.full_sorted_current_centers_left):
                centers_left = self.full_sorted_current_centers_left[col_idx]
                for (x, y) in centers_left:
                    self.simulate_center_click(x, y)

            if col_idx < len(self.full_sorted_current_centers_right):
                centers_right = self.full_sorted_current_centers_right[col_idx]
                for (x, y) in centers_right:
                    self.simulate_center_click(x, y)

        # 提示当前选中数量
        try:
            count = (
                len(self.selected_centers) if hasattr(self, "selected_centers") else 0
            )
            message = f"您当前选中的换热管孔的数量为{count}个"
            self.line_tip.setText(message)
            self.line_tip.setStyleSheet("color: black;")
            self.line_tip.setVisible(True)
            from PyQt5.QtCore import QTimer

            QTimer.singleShot(5000, lambda: self.line_tip.setText(""))
        except AttributeError:
            count = (
                len(self.selected_centers) if hasattr(self, "selected_centers") else 0
            )
            message = f"您当前选中的换热管孔的数量为{count}个"
            print(message)

    def bind_table_selection_handler(self):
        """根据排列方式绑定行/列选中逻辑"""
        if not hasattr(self, "hole_distribution_table"):
            return
        table = self.hole_distribution_table
        try:
            table.itemSelectionChanged.disconnect()
        except Exception:
            pass

        if getattr(self, "is_arrange_by_row", True):
            table.setSelectionBehavior(QAbstractItemView.SelectRows)
            table.itemSelectionChanged.connect(self.on_row_selection_changed)
        else:
            # 按列排列时，表格一行对应一列的数据，仍按行选择
            table.setSelectionBehavior(QAbstractItemView.SelectRows)
            table.itemSelectionChanged.connect(self.on_col_selection_changed)

    def _rel_label_set_for_hole_distribution_table_row(self, tbl_row):
        """与 on_row_selection_changed / on_col_selection_changed 一致，得到该表行对应的全部相对 (row,col) 标签集合。"""
        labels = set()

        def add_from_xy(x, y):
            if y >= 0:
                centers = self.full_sorted_current_centers_up
                y_multiplier = 1
            else:
                centers = self.full_sorted_current_centers_down
                y_multiplier = -1
            x_multiplier = 1 if x >= 0 else -1
            result = (
                self.find_nearest_circle_index(centers, [], x, y, self.r)
                if centers
                else None
            )
            if result:
                row, col = result
                row_label = (row + 1) * y_multiplier
                col_label = (col + 1) * x_multiplier
                labels.add((row_label, col_label))

        if getattr(self, "is_arrange_by_row", True):
            self.full_sorted_current_centers_up, self.full_sorted_current_centers_down = (
                self.group_centers_by_y(self.global_centers)
            )
            is_special_layout = hasattr(
                self, "tube_pass_form_value"
            ) and self.tube_pass_form_value in ["4.3", "6.2"]
            if is_special_layout and tbl_row == 0:
                if tbl_row < len(self.full_sorted_current_centers_up):
                    for x, y in self.full_sorted_current_centers_up[tbl_row]:
                        add_from_xy(x, y)
            else:
                if tbl_row < len(self.full_sorted_current_centers_down):
                    for x, y in self.full_sorted_current_centers_down[tbl_row]:
                        add_from_xy(x, y)
                if tbl_row < len(self.full_sorted_current_centers_up):
                    for x, y in self.full_sorted_current_centers_up[tbl_row]:
                        add_from_xy(x, y)
        else:
            self.full_sorted_current_centers_left, self.full_sorted_current_centers_right = (
                self.group_centers_by_x(self.global_centers)
            )
            is_special_layout_col = hasattr(self, "tube_pass_form_value") and (
                self.tube_pass_form_value in ["1.1", "2.1", "4.1", "4.3", "6.1"]
            )
            col_idx = tbl_row
            if is_special_layout_col and col_idx == 0:
                if col_idx < len(self.full_sorted_current_centers_right):
                    for x, y in self.full_sorted_current_centers_right[col_idx]:
                        add_from_xy(x, y)
            else:
                if col_idx < len(self.full_sorted_current_centers_left):
                    for x, y in self.full_sorted_current_centers_left[col_idx]:
                        add_from_xy(x, y)
                if col_idx < len(self.full_sorted_current_centers_right):
                    for x, y in self.full_sorted_current_centers_right[col_idx]:
                        add_from_xy(x, y)
        return labels

    def _hole_table_line_nos_fully_in_selection(self, selected_centers_expanded):
        """按第 0 列显示为 1/2/3 识别分布表行；若该行全部管孔标签 ⊆ 本次删除集合，则返回对应中心线编号集合。"""
        table = getattr(self, "hole_distribution_table", None)
        if table is None:
            return set()
        sel = set()
        for item in selected_centers_expanded or []:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                a, b = item[0], item[1]
                if isinstance(a, int) and isinstance(b, int):
                    sel.add((a, b))
        if not sel:
            return set()
        out = set()
        for r in range(table.rowCount()):
            item0 = table.item(r, 0)
            if item0 is None:
                continue
            try:
                n = int(str(item0.text()).strip())
            except (ValueError, TypeError):
                continue
            if n not in (1, 2, 3):
                continue
            expected = self._rel_label_set_for_hole_distribution_table_row(r)
            if expected and expected.issubset(sel):
                out.add(n)
        return out

    def _apply_cross_pipe_reset_for_centerlines(self, line_nos):
        """整行/整列删除「第0列为1/2/3」后，将对应交叉布管 bool 与 coord/abs 缓存清空并尝试落库。"""
        if not line_nos:
            return
        row_mode = getattr(self, "is_arrange_by_row", True)
        for k in (1, 2, 3):
            if k not in line_nos:
                continue
            setattr(self, f"abs_coords_line{k}", [])
            if row_mode:
                setattr(self, f"is_x_line{k}", False)
                setattr(self, f"coord_x_line{k}_2", [])
                setattr(self, f"coord_x_line{k}_4", [])
            else:
                setattr(self, f"is_y_line{k}", False)
                setattr(self, f"coord_y_line{k}_2", [])
                setattr(self, f"coord_y_line{k}_4", [])
        try:
            self.build_sql_for_cross_pipes()
        except Exception as e:
            print(f"[_apply_cross_pipe_reset_for_centerlines] build_sql_for_cross_pipes: {e}")

    def clear_selection_highlight(self):
        from PyQt5.QtCore import QPointF, Qt
        from PyQt5.QtWidgets import QGraphicsEllipseItem
        # ⚠️ 原生层闪退(0xC0000005)规避：
        # 布管/重建场景期间，Qt 可能正处于图元批量增删与重绘过程中。
        # 此时遍历 scene.items() 并对图元 setPen/setBrush/removeItem 容易触发 C++ 访问违规。
        # 因此在布管进行中仅清理 Python 侧“选中状态”，不触碰 scene 图元。
        if getattr(self, "_buguan_in_progress", False):
            try:
                self._selected_centers = []
            except Exception:
                pass
            try:
                if hasattr(self, "selected_lagans"):
                    self.selected_lagans = []
            except Exception:
                pass
            try:
                if hasattr(self, "selected_side_rods"):
                    self.selected_side_rods = []
            except Exception:
                pass
            return

        try:
            print(
                "[clear_selection_highlight] called, has selected_centers=",
                hasattr(self, "selected_centers") and bool(self.selected_centers),
                "len(selected_lagans)=",
                len(self.selected_lagans) if hasattr(self, "selected_lagans") else 0,
            )
        except Exception:
            pass

        # 1) 清除管孔选中高亮（marker）
        if hasattr(self, "selected_centers") and self.selected_centers:
            for row_label, col_label in self.selected_centers:
                # 确定是上半部分还是下半部分
                is_upper = row_label > 0
                row_idx = abs(row_label) - 1
                col_idx = abs(col_label) - 1  # 处理列的绝对值

                # 选择正确的圆心列表
                centers = (
                    self.full_sorted_current_centers_up
                    if is_upper
                    else self.full_sorted_current_centers_down
                )

                # 检查索引有效性
                if row_idx < 0 or row_idx >= len(centers):
                    continue
                if col_idx < 0 or col_idx >= len(centers[row_idx]):
                    continue

                x, y = centers[row_idx][col_idx]
                click_point = QPointF(x, y)

                # 只删除标记项，保留原始圆
                for item in self.graphics_scene.items(click_point):
                    if (
                            isinstance(item, QGraphicsEllipseItem)
                            and item.data(0) == "marker"
                    ):
                        self.graphics_scene.removeItem(item)
                        break

        # 2) 清除普通拉杆和自由拉杆的选中高亮
        try:
            # 普通拉杆
            if hasattr(self, "selected_lagans") and self.selected_lagans:
                try:
                    print(
                        "[clear_selection_highlight] reset selected_lagans count=",
                        len(self.selected_lagans),
                    )
                except Exception:
                    pass
                for rod in list(self.selected_lagans):
                    try:
                        if hasattr(rod, "is_selected"):
                            rod.is_selected = False
                        if hasattr(rod, "original_pen"):
                            rod.setPen(rod.original_pen)
                        if hasattr(rod, "original_brush"):
                            rod.setBrush(rod.original_brush)
                        rod.update()
                    except Exception:
                        pass
                self.selected_lagans = []

            # 自由拉杆（最左最右拉杆）
            if hasattr(self, "selected_side_rods") and self.selected_side_rods:
                try:
                    print(
                        "[clear_selection_highlight] reset selected_side_rods count=",
                        len(self.selected_side_rods),
                    )
                except Exception:
                    pass
                for rod in list(self.selected_side_rods):
                    try:
                        if hasattr(rod, "is_selected"):
                            rod.is_selected = False
                        if hasattr(rod, "original_pen"):
                            rod.setPen(rod.original_pen)
                        if hasattr(rod, "original_brush"):
                            rod.setBrush(rod.original_brush)
                        rod.update()
                    except Exception:
                        pass
                self.selected_side_rods = []
            # 兜底：遍历场景中所有拉杆圆（ClickableCircleItem），确保状态与画刷恢复
            try:
                if hasattr(self, "graphics_scene") and self.graphics_scene:
                    reset_count = 0
                    for item in self.graphics_scene.items():
                        # 使用类型名检查，避免 ClickableCircleItem 在不同导入路径下类标识不一致
                        if (
                                hasattr(item, "__class__")
                                and item.__class__.__name__ == "ClickableCircleItem"
                        ):
                            if hasattr(item, "is_selected"):
                                item.is_selected = False
                            if hasattr(item, "original_pen"):
                                item.setPen(item.original_pen)
                            if hasattr(item, "original_brush"):
                                item.setBrush(item.original_brush)
                            item.update()
                            reset_count += 1
                    try:
                        print(
                            "[clear_selection_highlight] fallback reset lagan items count=",
                            reset_count,
                        )
                    except Exception:
                        pass
            except Exception:
                pass
        except Exception:
            pass

        # 3) 最后清空管孔选中记录
        if hasattr(self, "selected_centers"):
            self.selected_centers = []

        # 4) 最终兜底：按颜色清理所有淡蓝色实心圆，确保界面上无残留高亮
        try:
            if hasattr(self, "graphics_scene") and self.graphics_scene:
                from PyQt5.QtGui import QColor, QBrush

                target_color = QColor(173, 216, 230)
                for it in list(self.graphics_scene.items()):
                    if (
                            isinstance(it, QGraphicsEllipseItem)
                            and it.brush().color() == target_color
                    ):
                        # 若是 marker，直接删除
                        if it.data(0) == "marker":
                            self.graphics_scene.removeItem(it)
                            continue

                        # 否则尽量恢复原始画刷；若无则置为无填充
                        if hasattr(it, "original_brush"):
                            it.setBrush(it.original_brush)
                        else:
                            it.setBrush(QBrush(Qt.NoBrush))
                        it.update()
        except Exception:
            pass

    def on_show_operations_click(self):
        if not hasattr(self, "operations") or not self.operations:
            QMessageBox.information(self, "操作记录", "暂无操作记录")
            return

        lines = []
        for i, op in enumerate(self.operations, 1):
            optype = op.get("type", "")

            # ---- 拉杆 ----
            if optype == "lagan":
                lines.append(
                    f"{i}. 拉杆 -> 第 {op.get('row', '?')} 行, 第 {op.get('col', '?')} 列"
                )

            # ---- 删除换热管 ----
            elif optype == "del":
                r, c = op.get("row"), op.get("col")
                if r is not None and c is not None:
                    lines.append(f"{i}. 删除换热管 -> 第 {r} 行, 第 {c} 列")
                else:
                    coord = op.get("absolute_coord") or op.get("absolute_coords")
                    lines.append(f"{i}. 删除换热管 -> 坐标 {coord}")

            # ---- 添加换热管 ----
            elif optype == "add_tube":
                if "row" in op and "col" in op:
                    lines.append(
                        f"{i}. 添加换热管 -> 第 {op['row']} 行, 第 {op['col']} 列"
                    )
                elif "relative_coord" in op:
                    rc = op["relative_coord"]
                    lines.append(f"{i}. 添加换热管 -> 第 {rc[0]} 行, 第 {rc[1]} 列")
                else:
                    coord = op.get("absolute_coord") or op.get("absolute_coords")
                    lines.append(f"{i}. 添加换热管 -> 坐标 {coord}")

            # ---- 非管区拉杆 ----
            elif optype == "small_block":
                lines.append(
                    f"{i}. 非管区拉杆 -> 第 {op.get('row', '?')} 行 ({op.get('side', '?')} 侧)"
                )

            # ---- 中间挡管 ----
            elif optype == "center_block":
                pt1, pt2 = op.get("from", ("?", "?"))
                lines.append(f"{i}. 中间挡管 -> 来自坐标 {pt1} 和 {pt2}")

            # ---- 其它操作 ----
            else:
                lines.append(f"{i}. 未知操作: {op}")

        # ---- 显示 ----
        dialog = QDialog(self)
        dialog.setWindowTitle("操作记录")
        layout = QVBoxLayout(dialog)

        from PyQt5.QtWidgets import QTextEdit

        text_box = QTextEdit(dialog)
        text_box.setReadOnly(True)
        text_box.setText("\n".join(lines))
        layout.addWidget(text_box)

        dialog.setLayout(layout)
        dialog.resize(480, 600)
        dialog.exec_()

    def find_closest_to_axes(self):
        if self.sorted_current_centers_up and self.sorted_current_centers_down:

            self.print_cross_x_up_line1 = []
            self.print_cross_x_up_line2 = []
            self.print_cross_x_up_line3 = []
            self.print_cross_x_down_line1 = []
            self.print_cross_x_down_line2 = []
            self.print_cross_x_down_line3 = []

            self.print_cross_y_left_line1 = []
            self.print_cross_y_left_line2 = []
            self.print_cross_y_left_line3 = []
            self.print_cross_y_right_line1 = []
            self.print_cross_y_right_line2 = []
            self.print_cross_y_right_line3 = []

            up_row_distances = []
            down_row_distances = []

            # 上半部分行距离计算
            for row_idx, row in enumerate(self.sorted_current_centers_up):
                if row:  # 确保行不为空
                    avg_y = sum(abs(y) for _, y in row) / len(row)
                    up_row_distances.append((row_idx, avg_y, row))

            # 下半部分行距离计算
            for row_idx, row in enumerate(self.sorted_current_centers_down):
                if row:  # 确保行不为空
                    avg_y = sum(abs(y) for _, y in row) / len(row)
                    down_row_distances.append((row_idx, avg_y, row))

            # 按距离排序并取前3行
            up_row_distances.sort(key=lambda x: x[1])
            down_row_distances.sort(key=lambda x: x[1])

            # 存储上半部分最近的3行
            for i in range(min(3, len(up_row_distances))):
                if i == 0:
                    self.print_cross_x_up_line1 = up_row_distances[i][2]
                elif i == 1:
                    self.print_cross_x_up_line2 = up_row_distances[i][2]
                elif i == 2:
                    self.print_cross_x_up_line3 = up_row_distances[i][2]

            # 存储下半部分最近的3行
            for i in range(min(3, len(down_row_distances))):
                if i == 0:
                    self.print_cross_x_down_line1 = down_row_distances[i][2]
                elif i == 1:
                    self.print_cross_x_down_line2 = down_row_distances[i][2]
                elif i == 2:
                    self.print_cross_x_down_line3 = down_row_distances[i][2]

            # 2. 处理Y轴相关的列（左侧和右侧）
            # 收集所有点的X坐标信息
            all_points = []
            for row in (
                    self.sorted_current_centers_up + self.sorted_current_centers_down
            ):
                all_points.extend(row)

            if all_points:
                # 按X坐标绝对值排序（距离Y轴的距离）
                sorted_by_x = sorted(all_points, key=lambda p: abs(p[0]))

                # 分离左侧（X<0）和右侧（X>0）的点
                left_points = [p for p in sorted_by_x if p[0] < 0]
                right_points = [p for p in sorted_by_x if p[0] > 0]

                # 取左侧最近的3列（去重，按X坐标分组）
                left_groups = {}
                for x, y in left_points:
                    x_key = round(x, 2)  # 按X坐标分组（保留2位小数）
                    if x_key not in left_groups:
                        left_groups[x_key] = []
                    left_groups[x_key].append((x, y))

                # 按X坐标绝对值排序左侧列
                sorted_left_cols = sorted(left_groups.items(), key=lambda x: abs(x[0]))

                # 存储左侧最近的3列
                for i in range(min(3, len(sorted_left_cols))):
                    col_points = sorted_left_cols[i][1]
                    if i == 0:
                        self.print_cross_y_left_line1 = col_points
                    elif i == 1:
                        self.print_cross_y_left_line2 = col_points
                    elif i == 2:
                        self.print_cross_y_left_line3 = col_points

                # 按X坐标绝对值排序右侧列
                right_groups = {}
                for x, y in right_points:
                    x_key = round(x, 2)  # 按X坐标分组（保留2位小数）
                    if x_key not in right_groups:
                        right_groups[x_key] = []
                    right_groups[x_key].append((x, y))

                sorted_right_cols = sorted(
                    right_groups.items(), key=lambda x: x[0]
                )  # 右侧按正X值排序

                # 存储右侧最近的3列
                for i in range(min(3, len(sorted_right_cols))):
                    col_points = sorted_right_cols[i][1]
                    if i == 0:
                        self.print_cross_y_right_line1 = col_points
                    elif i == 1:
                        self.print_cross_y_right_line2 = col_points
                    elif i == 2:
                        self.print_cross_y_right_line3 = col_points
        else:
            # 如果数据为空，初始化所有变量为空列表
            self.print_cross_x_up_line1 = []
            self.print_cross_x_up_line2 = []
            self.print_cross_x_up_line3 = []
            self.print_cross_x_down_line1 = []
            self.print_cross_x_down_line2 = []
            self.print_cross_x_down_line3 = []
            self.print_cross_y_left_line1 = []
            self.print_cross_y_left_line2 = []
            self.print_cross_y_left_line3 = []
            self.print_cross_y_right_line1 = []
            self.print_cross_y_right_line2 = []
            self.print_cross_y_right_line3 = []

    def find_full_closest_to_axes(self):
        if (
                self.full_sorted_current_centers_up
                and self.full_sorted_current_centers_down
        ):

            self.full_print_cross_x_up_line1 = []
            self.full_print_cross_x_up_line2 = []
            self.full_print_cross_x_up_line3 = []
            self.full_print_cross_x_down_line1 = []
            self.full_print_cross_x_down_line2 = []
            self.full_print_cross_x_down_line3 = []

            self.full_print_cross_y_left_line1 = []
            self.full_print_cross_y_left_line2 = []
            self.full_print_cross_y_left_line3 = []
            self.full_print_cross_y_right_line1 = []
            self.full_print_cross_y_right_line2 = []
            self.full_print_cross_y_right_line3 = []

            up_row_distances = []
            down_row_distances = []

            # 上半部分行距离计算
            for row_idx, row in enumerate(self.full_sorted_current_centers_up):
                if row:  # 确保行不为空
                    avg_y = sum(abs(y) for _, y in row) / len(row)
                    up_row_distances.append((row_idx, avg_y, row))

            # 下半部分行距离计算
            for row_idx, row in enumerate(self.full_sorted_current_centers_down):
                if row:  # 确保行不为空
                    avg_y = sum(abs(y) for _, y in row) / len(row)
                    down_row_distances.append((row_idx, avg_y, row))

            # 按距离排序并取前3行
            up_row_distances.sort(key=lambda x: x[1])
            down_row_distances.sort(key=lambda x: x[1])

            # 存储上半部分最近的3行
            for i in range(min(3, len(up_row_distances))):
                if i == 0:
                    self.full_print_cross_x_up_line1 = up_row_distances[i][2]
                elif i == 1:
                    self.full_print_cross_x_up_line2 = up_row_distances[i][2]
                elif i == 2:
                    self.full_print_cross_x_up_line3 = up_row_distances[i][2]

            # 存储下半部分最近的3行
            for i in range(min(3, len(down_row_distances))):
                if i == 0:
                    self.full_print_cross_x_down_line1 = down_row_distances[i][2]
                elif i == 1:
                    self.full_print_cross_x_down_line2 = down_row_distances[i][2]
                elif i == 2:
                    self.full_print_cross_x_down_line3 = down_row_distances[i][2]

            # 2. 处理Y轴相关的列（左侧和右侧）
            # 收集所有点的X坐标信息
            all_points = []
            for row in (
                    self.full_sorted_current_centers_up
                    + self.full_sorted_current_centers_down
            ):
                all_points.extend(row)

            if all_points:
                # 按X坐标绝对值排序（距离Y轴的距离）
                sorted_by_x = sorted(all_points, key=lambda p: abs(p[0]))

                # 分离左侧（X<0）和右侧（X>0）的点
                left_points = [p for p in sorted_by_x if p[0] < 0]
                right_points = [p for p in sorted_by_x if p[0] > 0]

                # 取左侧最近的3列（去重，按X坐标分组）
                left_groups = {}
                for x, y in left_points:
                    x_key = round(x, 2)  # 按X坐标分组（保留2位小数）
                    if x_key not in left_groups:
                        left_groups[x_key] = []
                    left_groups[x_key].append((x, y))

                # 按X坐标绝对值排序左侧列
                sorted_left_cols = sorted(left_groups.items(), key=lambda x: abs(x[0]))

                # 存储左侧最近的3列
                for i in range(min(3, len(sorted_left_cols))):
                    col_points = sorted_left_cols[i][1]
                    if i == 0:
                        self.full_print_cross_y_left_line1 = col_points
                    elif i == 1:
                        self.full_print_cross_y_left_line2 = col_points
                    elif i == 2:
                        self.full_print_cross_y_left_line3 = col_points

                # 按X坐标绝对值排序右侧列
                right_groups = {}
                for x, y in right_points:
                    x_key = round(x, 2)  # 按X坐标分组（保留2位小数）
                    if x_key not in right_groups:
                        right_groups[x_key] = []
                    right_groups[x_key].append((x, y))

                sorted_right_cols = sorted(
                    right_groups.items(), key=lambda x: x[0]
                )  # 右侧按正X值排序

                # 存储右侧最近的3列
                for i in range(min(3, len(sorted_right_cols))):
                    col_points = sorted_right_cols[i][1]
                    if i == 0:
                        self.full_print_cross_y_right_line1 = col_points
                    elif i == 1:
                        self.full_print_cross_y_right_line2 = col_points
                    elif i == 2:
                        self.full_print_cross_y_right_line3 = col_points

            # -------------------------- 第二步：对Y轴坐标按y值排序（X轴无需排序，保持原顺序） --------------------------
            # Y轴左线1-3
            self.full_print_cross_y_left_line1.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )
            self.full_print_cross_y_left_line2.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )
            self.full_print_cross_y_left_line3.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )
            # Y轴右线1-3
            self.full_print_cross_y_right_line1.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )
            self.full_print_cross_y_right_line2.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )
            self.full_print_cross_y_right_line3.sort(
                key=lambda coord: (
                    coord[1]
                    if isinstance(coord, (list, tuple)) and len(coord) >= 2
                    else 0
                )
            )

            # -------------------------- 第三步：为12个坐标列表批量添加序号（序号从1开始） --------------------------
            # 定义"变量名→原始列表"的映射，避免重复代码
            full_line_mappings = [
                # X轴上侧线：变量名 → 待添加序号的列表
                ("full_print_cross_x_up_line1", self.full_print_cross_x_up_line1),
                ("full_print_cross_x_up_line2", self.full_print_cross_x_up_line2),
                ("full_print_cross_x_up_line3", self.full_print_cross_x_up_line3),
                # X轴下侧线
                ("full_print_cross_x_down_line1", self.full_print_cross_x_down_line1),
                ("full_print_cross_x_down_line2", self.full_print_cross_x_down_line2),
                ("full_print_cross_x_down_line3", self.full_print_cross_x_down_line3),
                # Y轴左侧线
                ("full_print_cross_y_left_line1", self.full_print_cross_y_left_line1),
                ("full_print_cross_y_left_line2", self.full_print_cross_y_left_line2),
                ("full_print_cross_y_left_line3", self.full_print_cross_y_left_line3),
                # Y轴右侧线
                ("full_print_cross_y_right_line1", self.full_print_cross_y_right_line1),
                ("full_print_cross_y_right_line2", self.full_print_cross_y_right_line2),
                ("full_print_cross_y_right_line3", self.full_print_cross_y_right_line3),
            ]

            # 遍历映射，为每个列表添加序号（格式：(序号, x, y)），并更新实例变量
            for var_name, line_list in full_line_mappings:
                # 处理坐标格式：可能是 (x, y) 或已经是 (序号, x, y)
                updated_line = []
                for i, point in enumerate(line_list):
                    if isinstance(point, (list, tuple)) and len(point) >= 2:
                        # 如果已经是 (序号, x, y) 格式，取后两个元素；否则取全部
                        if len(point) == 3:
                            x, y = point[1], point[2]
                        else:
                            x, y = point[0], point[1]
                        updated_line.append((i + 1, x, y))
                # 通过setattr更新实例的对应变量
                setattr(self, var_name, updated_line)
        else:
            # 如果数据为空，初始化所有变量为空列表
            self.full_print_cross_x_up_line1 = []
            self.full_print_cross_x_up_line2 = []
            self.full_print_cross_x_up_line3 = []
            self.full_print_cross_x_down_line1 = []
            self.full_print_cross_x_down_line2 = []
            self.full_print_cross_x_down_line3 = []
            self.full_print_cross_y_left_line1 = []
            self.full_print_cross_y_left_line2 = []
            self.full_print_cross_y_left_line3 = []
            self.full_print_cross_y_right_line1 = []
            self.full_print_cross_y_right_line2 = []
            self.full_print_cross_y_right_line3 = []

    # 获取选中的两个换热管的编号，x轴上下编号
    def get_selected_x_center_numbers(
            self, selected_centers, print_cross_x_up, print_cross_x_down, row
    ):
        # 仅按当前可交叉布管候选（print_cross_*）匹配，避免使用 full_* 导致已删除管孔误参与
        up_number = None
        down_number = None

        for center in selected_centers:
            for item in print_cross_x_up:
                # item格式：(编号, x, y)，center格式：(x, y)
                if (item[1], item[2]) == center:
                    up_number = item[0]
                    break
            for item in print_cross_x_down:
                if (item[1], item[2]) == center:
                    down_number = item[0]
                    break

        if up_number is None or down_number is None:
            raise ValueError(
                "selected_centers中的坐标未完全匹配到print_cross_x_up或print_cross_x_down"
            )

        return {"up_number": up_number, "down_number": down_number}

    def get_selected_x_4_center_numbers(
            self, selected_centers, print_cross_x_up, print_cross_x_down
    ):

        up_numbers = []
        down_numbers = []

        # 遍历选中的每个坐标
        for center in selected_centers:
            # 检查是否属于上列表 self.print_cross_x_up_line1
            for item in print_cross_x_up:
                # item 格式为 (编号, x坐标, y坐标)，center 为 (x坐标, y坐标)
                if (item[1], item[2]) == center:
                    up_numbers.append(item[0])
                    break
            # 检查是否属于下列表 self.print_cross_x_down_line1
            for item in print_cross_x_down:
                if (item[1], item[2]) == center:
                    down_numbers.append(item[0])
                    break

        # 校验：必须恰好提取到 2 个上列表编号和 2 个下列表编号
        if len(up_numbers) != 2 or len(down_numbers) != 2:
            raise ValueError(
                f"需要选中 2 个上列表坐标和 2 个下列表坐标，但实际提取到 {len(up_numbers)} 个上列表编号，{len(down_numbers)} 个下列表编号"
            )

        return {"up_numbers": up_numbers, "down_numbers": down_numbers}

